"""Metric Based Phasing — Shiny for Python app.

Converted from the original Streamlit app. Analyzes Garmin .FIT files for
aerobic decoupling, efficiency factor (EF), durability metrics, and training
prescriptions.

UX/UI design follows the "Comprehensive Architecture and Design Strategy for
High-Performance Sports Analytics Applications in Shiny for Python" document:
  - Inverted Pyramid layout (KPIs → Trends → Deep Dive)
  - Semantic color palette (HR=Red, Power=Gold, Speed=Teal)
  - Dark mode CSS refinements (card depth, typography)
  - Progressive disclosure (accordions for advanced metrics)
  - Full-screen chart cards
  - RAG status colors (colorblind-safe)
  - Font Awesome icons on value boxes
"""

import asyncio
import base64
import hashlib
import inspect
import io
import json
import os
import re
import zipfile
from dataclasses import replace as dc_replace
import numpy as np
import pandas as pd
from pathlib import Path
from typing import Any, Dict, List, Optional, Tuple

from shiny import App, Inputs, Outputs, Session, reactive, render, req, ui
from shiny.types import FileInfo
import shinyswatch
from htmltools import HTML, Tag, TagList, css, div, span, h3, h4, p, tags
import faicons as fa

# Local modules
from utils import (
    HISTORY_COLUMNS, PROFILE_META_START_TIME_ISO,
    sanitize_slug, history_path, format_duration,
    pace_str_from_speed_mps,
    _fmt_thr_pct, status_color_for,
    downsample_for_plot,
)
from terrain import (
    TERRAIN_THRESHOLDS, BIKE_TERRAIN_THRESHOLDS,
    thresholds_for_session, ergometer_thresholds_by_duration,
    TerrainInfo, add_ngp_speed, compute_terrain, ensure_elapsed_sec,
    terrain_decoupling_zone,
    compute_cardiac_cost_metrics_1hz, compute_segment_ef_stability,
    compute_power_decay_after_kj,
)
from fit_parser import (
    parse_fit_bytes, infer_mode, infer_erg_subtype,
    get_activity_weather_summary, extract_temp_bounds_from_weather_summary,
    choose_output_metric, combine_fit_workouts,
)
from history import (
    load_history, save_history,
    _history_upsert_row, load_history_cached,
    clear_history_cache,
)
from tss import (
    auto_compute_tss, compute_power_tss, compute_run_tss,
    compute_hr_tss, normalized_power as tss_normalized_power,
    compute_pmc, daily_tss_from_history,
)

# Import analysis module (eager import for Shinylive/Pyodide compatibility)
import analysis as _analysis_mod
def _get_analysis():
    return _analysis_mod

import sprint_analysis as _sprint_mod

# Detect Shinylive / Pyodide (browser-based, no server-side network)
import sys
_IS_PYODIDE = sys.platform == "emscripten" or "pyodide" in sys.modules

# Athlete tracker: trigger immediate spreadsheet rebuild on rename/edit/delete
def _notify_athlete_tracker():
    """Tell the athlete tracker to rebuild MBP Athletes.xlsx immediately."""
    try:
        import athlete_tracker
        athlete_tracker.trigger_spreadsheet_update()
    except Exception:
        pass  # tracker may not be running (e.g. Shinylive)

# ---------------------------------------------------------------------------
# _maybe_await: wrapper for dual sync/async support
# ---------------------------------------------------------------------------
async def _maybe_await(result):
    """If result is awaitable (coroutine), await it; otherwise return as-is."""
    if inspect.isawaitable(result):
        return await result
    return result

# ---------------------------------------------------------------------------
# Proxy URL for Pyodide remote modules
# ---------------------------------------------------------------------------
_proxy_url: str = ""  # set by proxy UI in server()

# Gist URL for ngrok auto-discovery (public, no auth needed)
_GIST_RAW_URL = "https://gist.githubusercontent.com/dsingson5/20210ef251a6c4ebf1141068e9be2717/raw/proxy_url.txt"

# Eager-import remote sync modules so Shinylive registers them on the
# virtual filesystem (lazy imports inside functions fail in Pyodide).
_remote_garmin_mod = None
_remote_whoop_mod = None
try:
    import remote_garmin_sync as _remote_garmin_mod
except ImportError:
    pass
try:
    import remote_whoop_sync as _remote_whoop_mod
except ImportError:
    pass

# Garmin Connect sync (optional — server-side or remote via proxy)
_garmin_sync_mod = None
def _get_garmin_sync():
    global _garmin_sync_mod
    if _IS_PYODIDE:
        # In Pyodide, use remote module if proxy is configured
        if _proxy_url and _remote_garmin_mod is not None:
            _remote_garmin_mod.set_proxy_url(_proxy_url)
            return _remote_garmin_mod
        return None  # no proxy configured
    if _garmin_sync_mod is None:
        try:
            import garmin_sync
            _garmin_sync_mod = garmin_sync
        except ImportError:
            _garmin_sync_mod = False  # sentinel: not available
    return _garmin_sync_mod if _garmin_sync_mod is not False else None

# Whoop sync (optional — server-side or remote via proxy)
_whoop_sync_mod = None
def _get_whoop_sync():
    global _whoop_sync_mod
    if _IS_PYODIDE:
        # In Pyodide, use remote module if proxy is configured
        if _proxy_url and _remote_whoop_mod is not None:
            _remote_whoop_mod.set_proxy_url(_proxy_url)
            return _remote_whoop_mod
        return None  # no proxy configured
    if _whoop_sync_mod is None:
        try:
            import whoop_sync
            _whoop_sync_mod = whoop_sync
        except ImportError:
            _whoop_sync_mod = False
    return _whoop_sync_mod if _whoop_sync_mod is not False else None

# App base directory (where CSV history files live)
APP_DIR = Path(__file__).resolve().parent

# Pre-encoded images as base64 data URIs — lazy-loaded to avoid blocking startup
_images_cache = {}
def _get_image(name: str) -> str:
    """Lazy-load image data URI from _images module on first access."""
    if name not in _images_cache:
        from _images import IMG_MBP_INTRO, IMG_GARMIN_HELP, IMG_AD_INFOGRAPHIC, IMG_LAP_PRESS, IMG_TERRAIN, IMG_SPRINT_30S
        _images_cache.update({
            "IMG_MBP_INTRO": IMG_MBP_INTRO, "IMG_GARMIN_HELP": IMG_GARMIN_HELP,
            "IMG_AD_INFOGRAPHIC": IMG_AD_INFOGRAPHIC, "IMG_LAP_PRESS": IMG_LAP_PRESS,
            "IMG_TERRAIN": IMG_TERRAIN, "IMG_SPRINT_30S": IMG_SPRINT_30S,
        })
    return _images_cache.get(name, "")

# Build metadata (auto-generated by CI, defaults for local dev)
try:
    from _build_info import IS_BETA, BUILD_TIMESTAMP
except ImportError:
    IS_BETA = False
    BUILD_TIMESTAMP = ""

# If no CI timestamp, use app.py last-modified time (server / local dev)
if not BUILD_TIMESTAMP and not (sys.platform == "emscripten" or "pyodide" in sys.modules):
    try:
        import datetime as _dt
        _mtime = os.path.getmtime(Path(__file__).resolve())
        _pht = _dt.datetime.fromtimestamp(_mtime, tz=_dt.timezone(_dt.timedelta(hours=8)))
        BUILD_TIMESTAMP = _pht.strftime("%b %d, %Y %I:%M %p") + " PHT"
    except Exception:
        pass

# ---------------------------------------------------------------------------
# Plotly lazy loader
# ---------------------------------------------------------------------------
_plotly_go_cache = None
def _get_plotly_go():
    global _plotly_go_cache
    if _plotly_go_cache is None:
        import plotly.graph_objects as go
        _plotly_go_cache = go
    return _plotly_go_cache


# ===================================================================
# Whoop API key → history column mapping (shared by Analyze + Compare)
# ===================================================================
_WHOOP_COL_MAP = {
    "recovery_score": "whoop_score", "hrv_rmssd_milli": "whoop_hrv_ms",
    "resting_heart_rate": "whoop_resting_hr", "strain": "whoop_strain",
    "sleep_perf": "whoop_sleep_perf", "sleep_efficiency": "whoop_sleep_efficiency",
    "sleep_hours": "whoop_sleep_hours", "rem_min": "whoop_rem_min",
    "sws_min": "whoop_sws_min", "light_min": "whoop_light_min",
    "awake_min": "whoop_awake_min", "spo2": "whoop_spo2",
    "skin_temp": "whoop_skin_temp_c", "respiratory_rate": "whoop_resp_rate",
    "calories_kj": "whoop_calories_kj",
}

# ===================================================================
# Semantic Color Palette (from UX/UI doc Section 4.3)
# ===================================================================
# These are defined as Python constants and also injected as CSS variables.
COLOR_POWER = "#FFD700"       # Gold — energy/wattage
COLOR_HR = "#FF4136"          # Red — cardiac exertion
COLOR_CADENCE = "#2ECC40"     # Green — rhythm/flow
COLOR_SPEED = "#39CCCC"       # Teal — distinct from physio metrics
COLOR_ELEVATION = "#AAAAAA"   # Grey — earth-bound constraint
COLOR_EF = "#0074D9"          # Blue — efficiency
COLOR_ELITE = "#00FFFF"       # Cyan — colorblind-safe "good" (RAG)
COLOR_ADAPTING = "#FF851B"     # Orange — colorblind-safe "caution" (RAG)
COLOR_NEEDS_WORK = "#FF4136"  # Red — needs improvement


# ===================================================================
# Custom CSS (from UX/UI doc Sections 4.1, 4.2, 10.1)
# ===================================================================
CUSTOM_CSS = """
<style>
:root {
    --color-power: #FFD700;
    --color-hr: #FF4136;
    --color-cadence: #2ECC40;
    --color-speed: #39CCCC;
    --color-elevation: #AAAAAA;
    --color-ef: #0074D9;
    --color-elite: #00FFFF;
    --color-adapting: #FF851B;
    --color-needs-work: #FF4136;
    --bg-page: #101010;
    --bg-card: #1e1e1e;
    --bg-card-header: #252525;
}

/* Page background depth (Section 4.2) */
body, .bslib-page-fill {
    background-color: var(--bg-page) !important;
}

/* Card depth: slightly lighter than page to create depth without borders (Section 4.2) */
