.navbar .nav-link {
    opacity: 0.85;
}

/* Status badge pill styling */
.status-badge {
    display: inline-block;
    padding: 6px 14px;
    border-radius: 999px;
    font-weight: 800;
    font-size: 13px;
    color: #fff;
}

/* Smooth transitions */
.card, .bslib-value-box, .accordion {
    transition: box-shadow 0.2s ease;
}
.card:hover {
    box-shadow: 0 2px 12px rgba(0,0,0,0.4);
}

/* Clickable images — zoom cursor */
.zoomable-img {
