    font-size: 18px; line-height: 24px; text-align: center; margin-top: -2px; }
.phase-slider::-moz-range-thumb { width: 24px; height: 24px; background: transparent;
    border: none; cursor: pointer; font-size: 18px; }
.phase-labels { display: flex; justify-content: space-between; font-size: 9px;
    color: rgba(255,255,255,0.6); margin-top: 2px; user-select: none; }
.phase-labels span { text-align: center; flex: 1; }
.phase-labels span.active { color: #fff; font-weight: 700; }

/* ── KPI icon animations ── */
.kpi-ico-chart-line svg { animation: kpiWave 2.5s ease-in-out infinite; }
@keyframes kpiWave {
  0%, 100% { transform: translateY(0); }
