/* ── KPI trend indicators ── */
.kpi-trend { font-size:11px; font-weight:700; margin-left:6px; vertical-align:middle; }
.kpi-trend-up { color:#4ade80; }
.kpi-trend-down { color:#ff6b6b; }
.kpi-trend-flat { color:#94a3b8; }
</style>

<!-- Mobile phone detection: redirect to mobile UI -->
<script>
(function(){
    if(window.location.search.indexOf('desktop=1')!==-1){
        try{sessionStorage.setItem('mbp_desktop','1');}catch(e){}
        return;
    }
    try{if(sessionStorage.getItem('mbp_desktop')==='1') return;}catch(e){}
    var ua=navigator.userAgent||'';
    var isMobile=/Mobi|iPhone|iPod|Android|webOS|BlackBerry|IEMobile|Opera Mini/i.test(ua);
    var isIPad=/iPad/i.test(ua)||(navigator.platform==='MacIntel'&&navigator.maxTouchPoints>1);
    if(isMobile || isIPad){
        window.location.replace('/mobile.html'+window.location.search);
    }
})();
</script>

<!-- Lightbox container + JS -->
<div class="mbp-lightbox" id="mbpLightbox" onclick="this.classList.remove('active')">
    <span class="mbp-lightbox-close" onclick="document.getElementById('mbpLightbox').classList.remove('active')">&times;</span>
    <img id="mbpLightboxImg" src="" alt="Zoomed image" onclick="event.stopPropagation()">
</div>
<script>
function mbpZoom(el){
    var lb=document.getElementById('mbpLightbox');
    document.getElementById('mbpLightboxImg').src=el.src;
    lb.classList.add('active');
}
function mbpGetSelectedISOs(){
    var cbs=document.querySelectorAll('.mbp-del-cb:checked');
    var isos=[]; cbs.forEach(function(cb){isos.push(cb.dataset.iso);});
    return JSON.stringify({isos:isos,ts:Date.now()});
}
function mbpLoadSession(iso){
    Shiny.setInputValue('_reload_session_iso',iso,{priority:'event'});
}
function mbpSaveToStorage(slug,csvText){
    try{localStorage.setItem('mbp_csv_'+slug,csvText);}catch(e){}
}
function mbpSetLastProfile(slug){
    try{localStorage.setItem('mbp_last_profile',slug);}catch(e){}
}
function mbpGetLastProfile(){
    try{return localStorage.getItem('mbp_last_profile')||'';}catch(e){return '';}
}
function mbpRemoveFromStorage(slug){
    try{localStorage.removeItem('mbp_csv_'+slug);}catch(e){}
}
function mbpGetAllStorageKeys(){
    var keys=[];
    try{for(var i=0;i<localStorage.length;i++){
        var k=localStorage.key(i);
        if(k&&k.startsWith('mbp_csv_'))keys.push(k.substring(8));
    }}catch(e){}
    return JSON.stringify(keys);
}
function mbpGetStorageCsv(slug){
    try{return localStorage.getItem('mbp_csv_'+slug)||'';}catch(e){return '';}
}
function mbpSetGarminSession(sid){
    try{localStorage.setItem('mbp_garmin_session',sid);}catch(e){}
}
function mbpGetGarminSession(){
    try{return localStorage.getItem('mbp_garmin_session')||'';}catch(e){return '';}
}
function mbpClearGarminSession(){
    try{localStorage.removeItem('mbp_garmin_session');}catch(e){}
}
function mbpSetWhoopSession(sid){
    try{localStorage.setItem('mbp_whoop_session',sid);}catch(e){}
}
function mbpGetWhoopSession(){
    try{return localStorage.getItem('mbp_whoop_session')||'';}catch(e){return '';}
}
function mbpClearWhoopSession(){
    try{localStorage.removeItem('mbp_whoop_session');}catch(e){}
}
// Register eval_js handler early so send_custom_message works immediately
(function _regEvalJs(){
    function _tryReg(){
        if(typeof Shiny!=='undefined'&&Shiny.addCustomMessageHandler){
            if(!window._mbpEvalJs){
                Shiny.addCustomMessageHandler('eval_js',function(m){eval(m);});
                window._mbpEvalJs=true;
            }
        } else {
            setTimeout(_tryReg, 100);
        }
    }
    if(document.readyState==='loading'){
        document.addEventListener('DOMContentLoaded', _tryReg);
    } else {
        _tryReg();
    }
})();
// Detect ?source=beta and inject BETA badge into navbar
(function(){
    if(new URLSearchParams(window.location.search).get('source')==='beta'){
        function _addBeta(){
            var brand=document.querySelector('.navbar-brand');
            if(!brand){setTimeout(_addBeta,200);return;}
            if(brand.querySelector('.mbp-beta-badge')) return;
            var b=document.createElement('span');
            b.className='mbp-beta-badge';
            b.textContent=' — BETA';
            b.style.cssText='font-weight:600;color:#f59e0b;font-size:0.85em;';
            brand.appendChild(b);
        }
        if(document.readyState==='loading') document.addEventListener('DOMContentLoaded',_addBeta);
        else _addBeta();
    }
})();
// Training Phase slider → Shiny input binding + label highlighting
(function(){
    function _bindPhase(){
        var sl=document.getElementById('training_phase_slider');
        if(!sl) { setTimeout(_bindPhase, 200); return; }
        function _update(){
            var v=parseInt(sl.value);
            if(typeof Shiny!=='undefined'&&Shiny.setInputValue) Shiny.setInputValue('training_phase_slider',v);
            var labels=document.querySelectorAll('#phase_labels span');
            labels.forEach(function(s,i){ s.className=i===v?'active':''; });
        }
        sl.addEventListener('input', _update);
        _update();
    }
    if(document.readyState==='loading') document.addEventListener('DOMContentLoaded',_bindPhase);
    else _bindPhase();
})();
function mbpSortTable(th){
    var table=th.closest('table'), tbody=table.tBodies[0];
    var idx=Array.from(th.parentNode.children).indexOf(th);
    var rows=Array.from(tbody.rows);
    var asc=th.dataset.sortDir!=='asc'; th.dataset.sortDir=asc?'asc':'desc';
    rows.sort(function(a,b){
        var ac=a.cells[idx], bc=b.cells[idx];
        var as=ac.dataset.sort, bs=bc.dataset.sort;
        if(as!==undefined&&bs!==undefined) return asc?as.localeCompare(bs):bs.localeCompare(as);
        var at=ac.textContent.trim(), bt=bc.textContent.trim();
        var an=parseFloat(at.replace(/[^0-9.\-]/g,'')), bn=parseFloat(bt.replace(/[^0-9.\-]/g,''));
        if(!isNaN(an)&&!isNaN(bn)) return asc?an-bn:bn-an;
        return asc?at.localeCompare(bt):bt.localeCompare(at);
    });
    rows.forEach(function(r){tbody.appendChild(r);});
}
// ---- Mobile app-switch auto-reconnect ----
// When the user switches apps on a phone/tablet, the OS suspends the browser
// tab and the WebSocket dies.  On return we detect the dead connection and
// reload the page so Shiny re-establishes everything (WS, session, auto-
// restore of Garmin/Whoop tokens from disk).
(function(){
    var _lastVisible = Date.now();
    var _reloading = false;

    function _isShinyConnected(){
        // Shiny stores its WebSocket on Shiny.shinyapp.$socket
        try {
            var sock = Shiny.shinyapp.$socket;
            if(!sock) return false;
            // readyState: 0=CONNECTING, 1=OPEN, 2=CLOSING, 3=CLOSED
            return sock.readyState === 0 || sock.readyState === 1;
        } catch(e){ return false; }
    }

    function _onVisible(){
        if(_reloading) return;
        var now = Date.now();
        var away = now - _lastVisible;

        // If we were away for more than 5 seconds, check the WebSocket
        if(away > 5000){
            // Give the browser a moment to resume the WS after un-suspend
            setTimeout(function(){
                if(_reloading) return;
                if(!_isShinyConnected()){
                    console.log('[MBP] WebSocket dead after app switch ('
                        + Math.round(away/1000) + 's away) — reloading');
                    _reloading = true;
                    window.location.reload();
                }
            }, 1500);
        }
    }

    // visibilitychange: fires on mobile app switch, desktop tab switch
    document.addEventListener('visibilitychange', function(){
        if(document.visibilityState === 'hidden'){
            _lastVisible = Date.now();
        } else if(document.visibilityState === 'visible'){
            _onVisible();
        }
    });

    // pageshow: fires on iOS Safari back/forward cache ("bfcache") restore
    window.addEventListener('pageshow', function(e){
        if(e.persisted){
            // Page was restored from bfcache — WS is definitely dead
            console.log('[MBP] bfcache restore — reloading');
            _reloading = true;
            window.location.reload();
        }
    });

    // Fallback: periodic heartbeat check (catches edge cases like
    // laptop lid close / WiFi reconnect / long idle without suspend)
    setInterval(function(){
        if(document.visibilityState !== 'visible') return;
        if(_reloading) return;
        if(!_isShinyConnected()){
            console.log('[MBP] Periodic check: WebSocket dead — reloading');
            _reloading = true;
            window.location.reload();
        }
    }, 30000);  // every 30 seconds
})();
</script>
"""


