# ===================================================================
# Server
# ===================================================================

def server(input: Inputs, output: Outputs, session: Session):
    # ----- Garmin activity type badge colours -----
    _GARMIN_TYPE_COLORS = {
        "running": "#00d2ff", "cycling": "#ff9500", "swimming": "#00c7b1",
        "walking": "#a8e6cf", "hiking": "#8bc34a", "strength_training": "#e040fb",
        "cardio_training": "#ff5252", "yoga": "#ce93d8", "elliptical": "#ff7043",
        "indoor_cycling": "#ffb74d", "treadmill_running": "#4fc3f7",
        "open_water_swimming": "#26c6da", "pool_swimming": "#00bcd4",
        "trail_running": "#66bb6a", "virtual_ride": "#ffa726",
        "multi_sport": "#7c4dff", "other": "#90a4ae",
    }

    # ----- Reactive values -----
    parsed_data = reactive.Value(None)  # (meta, df_raw) tuple
    fit_bytes_val = reactive.Value(b"")
    fit_name_val = reactive.Value("")
    history_trigger = reactive.Value(0)  # increment to reload history
    _combine_mode = reactive.Value(False)  # multi-FIT combine toggle
    _storage_restored = reactive.Value(False)  # track if localStorage was restored

    # ----- Garmin Connect reactive values -----
    _garmin_client = reactive.Value(None)       # authenticated Garmin client
    _garmin_mfa_state = reactive.Value(None)    # (client, mfa_context) during MFA
    _garmin_activities = reactive.Value([])     # fetched activity list
    _garmin_fit_data = reactive.Value(None)     # (bytes, filename) from Garmin download
    _garmin_status = reactive.Value("")         # status message for UI
    _garmin_restore_done = reactive.Value(False)  # prevent repeated auto-restore
    _garmin_athlete_name = reactive.Value("")       # display name from Garmin for auto-profile

    # ----- Whoop Connect reactive values -----
    _whoop_tokens = reactive.Value(None)        # token dict (access_token, refresh_token, ...)
    _whoop_profile = reactive.Value(None)       # {"first_name": ..., "last_name": ..., "user_id": ...}
    _whoop_status = reactive.Value("")          # status message for UI
    _whoop_recent_data = reactive.Value([])     # list of merged day dicts from get_recent_recovery
    _whoop_restore_done = reactive.Value(False) # prevent repeated auto-restore
    _whoop_autofill_data = reactive.Value(None)  # dict with recovery/sleep/cycle for current activity

    # ----- Proxy server reactive values (Pyodide only) -----
    _proxy_connected = reactive.Value(False)
    _proxy_status_msg = reactive.Value("")
    _health_check_task = reactive.Value(None)  # asyncio.Task for polling loop

    # --- Auto-connect to proxy on startup (Pyodide only) ---
    _proxy_auto_connect_done = reactive.Value(False)

    @reactive.Effect
    async def _proxy_auto_connect():
        """Automatically fetch latest proxy URL from Gist and connect on startup."""
        global _proxy_url
        if not _IS_PYODIDE:
            return
        with reactive.isolate():
            if _proxy_auto_connect_done():
                return
        _proxy_auto_connect_done.set(True)

        import asyncio as _aio
        from pyodide.http import pyfetch  # type: ignore
        import time as _time, json as _json

        # --- Step 1: Fetch latest proxy URL from Gist ---
        _proxy_status_msg.set("Connecting to proxy...")
        proxy_url = ""
        try:
            cache_bust = int(_time.time())
            resp = await pyfetch(f"{_GIST_RAW_URL}?t={cache_bust}", method="GET")
            proxy_url = (await resp.string()).strip().rstrip("/")
        except Exception:
            pass

        if not proxy_url or not (proxy_url.startswith("http://") or proxy_url.startswith("https://")):
            _proxy_status_msg.set("")  # silently fail — no proxy available
            return

        # --- Step 2: Ping the proxy to verify it's alive ---
        try:
            resp = await pyfetch(
                f"{proxy_url}/api/ping", method="GET",
                headers={"ngrok-skip-browser-warning": "1"},
            )
            text = await resp.string()
            result = _json.loads(text)
        except Exception as e:
            _proxy_status_msg.set("")  # silently fail
            return

        if not result.get("ok"):
            _proxy_status_msg.set("")
            return

        # --- Step 3: Connected! ---
        _proxy_url = proxy_url
        _proxy_connected.set(True)
        _proxy_status_msg.set(f"🔗 Proxy connected (v{result.get('version', '?')})")
        ui.notification_show("🔗 Connected to proxy server", type="message", duration=3)

        # Start health-check polling loop
        with reactive.isolate():
            old_task = _health_check_task()
            if old_task is not None:
                old_task.cancel()
        _health_check_task.set(_aio.create_task(_health_check_loop()))

        # Per-device session restore from localStorage
        js_get = (
            "Shiny.setInputValue('_device_garmin_sid', mbpGetGarminSession());"
            "Shiny.setInputValue('_device_whoop_sid', mbpGetWhoopSession());"
        )
        await session.send_custom_message("eval_js", js_get)

        # Auto-hide the status bar after 5 seconds
        await _aio.sleep(5)
        with reactive.isolate():
            if _proxy_connected():
                _proxy_status_msg.set("")

    # --- Per-device Garmin session restore (from localStorage) ---
    @reactive.Effect
    @reactive.event(input._device_garmin_sid)
    async def _restore_device_garmin():
        sid = input._device_garmin_sid()
        if not sid:
            return  # New device — no saved session, show login form
        gsync = _get_garmin_sync()
        if not gsync or not hasattr(gsync, "validate_session"):
            return
        try:
            client = await _maybe_await(gsync.validate_session(sid))
            if client is not None:
                _garmin_client.set(client)
                dname = gsync.get_display_name(client)
                if dname and dname != "Garmin User":
                    _garmin_athlete_name.set(dname)
                _garmin_restore_done.set(True)
            else:
                # Session expired on server — clear localStorage
                await session.send_custom_message("eval_js", "mbpClearGarminSession();")
        except Exception:
            pass

    # --- Per-device Whoop session restore (from localStorage) ---
    @reactive.Effect
    @reactive.event(input._device_whoop_sid)
    async def _restore_device_whoop():
        sid = input._device_whoop_sid()
        if not sid:
            return  # New device — no saved session, show login form
        wsync = _get_whoop_sync()
        if not wsync:
            return
        try:
            # Set the whoop_session_id so subsequent calls use it
            wsync._whoop_session_id = sid
            tokens = await _maybe_await(wsync.load_tokens())
            if tokens is not None:
                _whoop_tokens.set(tokens)
                _whoop_restore_done.set(True)
                creds = await _maybe_await(wsync.load_credentials())
                if creds:
                    try:
                        profile, tokens = await _maybe_await(
                            wsync.get_profile(tokens, creds.get("client_id", ""), creds.get("client_secret", ""))
                        )
                        _whoop_tokens.set(tokens)
                        _whoop_profile.set(profile)
                    except Exception:
                        pass
            else:
                # Session expired on server — clear localStorage
                await session.send_custom_message("eval_js", "mbpClearWhoopSession();")
        except Exception:
            await session.send_custom_message("eval_js", "mbpClearWhoopSession();")

    # --- Health-check polling loop (auto-reconnect on server restart) ---
    async def _health_check_loop():
        """Background loop: ping proxy every 30s. Auto-reconnect via Gist on failure."""
        global _proxy_url
        import asyncio as _aio
        while True:
            await _aio.sleep(30)
            # Only check if we think we're connected
            with reactive.isolate():
                connected = _proxy_connected()
            if not connected:
                continue
            # Ping current proxy
            try:
                if _IS_PYODIDE:
                    from pyodide.http import pyfetch  # type: ignore
                    resp = await pyfetch(
                        f"{_proxy_url}/api/ping", method="GET",
                        headers={"ngrok-skip-browser-warning": "1"},
                    )
                    text = await resp.string()
                    import json as _json
                    result = _json.loads(text)
                    if result.get("ok"):
                        continue  # Still alive
                # If not Pyodide or ping didn't return ok, treat as failure
            except Exception:
                pass

            # Proxy unreachable — attempt auto-reconnect via Gist
            _proxy_connected.set(False)
            _proxy_status_msg.set("🔗 Reconnecting to proxy...")
            try:
                if _IS_PYODIDE:
                    from pyodide.http import pyfetch  # type: ignore
                    import time as _time, json as _json
                    cache_bust = int(_time.time())
                    resp = await pyfetch(
                        f"{_GIST_RAW_URL}?t={cache_bust}",
                        method="GET",
                    )
                    new_url = (await resp.string()).strip().rstrip("/")

                    if new_url and (
                        new_url.startswith("http://") or new_url.startswith("https://")
                    ):
                        # Ping the new (or same) URL
                        resp2 = await pyfetch(
                            f"{new_url}/api/ping", method="GET",
                            headers={"ngrok-skip-browser-warning": "1"},
                        )
                        text2 = await resp2.string()
                        result2 = _json.loads(text2)
                        if result2.get("ok"):
                            # Auto-reconnect success!
                            _proxy_url = new_url
                            _proxy_connected.set(True)
                            _proxy_status_msg.set(
                                f"🔗 Proxy connected (v{result2.get('version', '?')})"
                            )
                            ui.notification_show(
                                "🔗 Proxy auto-reconnected",
                                type="message", duration=3,
                            )
                            # Re-restore per-device sessions from localStorage
                            js_get = (
                                "Shiny.setInputValue('_device_garmin_sid', mbpGetGarminSession());"
                                "Shiny.setInputValue('_device_whoop_sid', mbpGetWhoopSession());"
                            )
                            await session.send_custom_message("eval_js", js_get)
                            # Auto-hide status after 5s
                            await _aio.sleep(5)
                            _proxy_status_msg.set("")
                            continue
            except Exception:
                pass

            # Auto-reconnect failed — will keep retrying silently
            _proxy_status_msg.set("⚠️ Proxy offline — retrying...")
            # Wait longer before next retry
            await _aio.sleep(30)

    @output
    @render.ui
    def proxy_status_ui():
        msg = _proxy_status_msg()
        if not msg:
            return ui.div()
        if "connected" in msg.lower() and "offline" not in msg.lower():
            color = "#4ade80"
            bg = "rgba(74,222,128,0.08)"
        elif "offline" in msg.lower() or "❌" in msg:
            color = "#ff6b6b"
            bg = "rgba(255,107,107,0.08)"
        elif "Connecting" in msg or "Reconnecting" in msg or "retrying" in msg.lower():
            color = "#facc15"
            bg = "rgba(250,204,21,0.08)"
        else:
            color = "#aaa"
            bg = "transparent"
        return ui.div(
            ui.tags.span(msg, style=f"font-size: 11px; color: {color};"),
            style=f"background: {bg}; border-radius: 6px; padding: 4px 10px; margin-bottom: 6px;",
        )

    # ----- Helper: persist CSV to browser localStorage -----
    async def _persist_to_browser(slug: str):
        """After saving a CSV to disk, also push it to browser localStorage."""
        hp = APP_DIR / f"ad_history_{slug}.csv"
        if hp.exists():
            try:
                csv_text = hp.read_text(encoding="utf-8")
                js = f"mbpSaveToStorage({json.dumps(slug)},{json.dumps(csv_text)});"
                await session.send_custom_message("eval_js", js)
            except Exception:
                pass

    async def _remove_from_browser(slug: str):
        """Remove a profile from browser localStorage."""
        js = f"mbpRemoveFromStorage({json.dumps(slug)});"
        await session.send_custom_message("eval_js", js)

    # ----- Restore profiles from browser localStorage on startup -----
    @reactive.Effect
    async def _restore_from_storage():
        """On first load, ask browser for all stored CSVs in one batch.

        We trigger via a short delay to ensure the eval_js handler is registered
        in the browser before we fire the custom message.
        """
        with reactive.isolate():
            already = _storage_restored()
        if already:
            return
        _storage_restored.set(True)

        # Give the browser time to register the eval_js handler
        await asyncio.sleep(1.5)

        # Batch-fetch all CSVs from localStorage in a single JS call
        js = (
            "var keys=JSON.parse(mbpGetAllStorageKeys());"
            "var batch={};"
            "keys.forEach(function(k){var c=mbpGetStorageCsv(k);if(c)batch[k]=c;});"
            "Shiny.setInputValue('_restore_batch', JSON.stringify(batch));"
        )
        await session.send_custom_message("eval_js", js)

    @reactive.Effect
    @reactive.event(input._restore_batch)
    def _write_restored_csvs():
        """Write all restored CSVs from localStorage to the virtual filesystem."""
        raw = input._restore_batch()
        if not raw:
            return
        try:
            batch = json.loads(raw)
        except Exception:
            return
        if not isinstance(batch, dict) or not batch:
            return
        restored = 0
        for slug, csv_text in batch.items():
            if not slug or not csv_text:
                continue
            hp = APP_DIR / f"ad_history_{slug}.csv"
            # Always overwrite if the file doesn't exist or is empty
            should_write = (not hp.exists()) or (hp.stat().st_size < 10)
            if should_write:
                try:
                    hp.write_text(csv_text, encoding="utf-8")
                    restored += 1
                except Exception:
                    pass
        if restored > 0:
            clear_history_cache()
            history_trigger.set(history_trigger() + 1)
            ui.notification_show(f"Restored {restored} profile(s) from browser storage.", type="message", duration=4)

    # --- Restore last-used profile from localStorage ---
    @reactive.Effect
    async def _restore_last_profile():
        """After profiles are loaded, restore the last-used profile selection."""
        _ = history_trigger()  # re-run when profiles change
        with reactive.isolate():
            restored = _storage_restored()
        if not restored:
            return
        await asyncio.sleep(2.0)  # wait for profile choices to be populated
        js = "Shiny.setInputValue('_last_profile_slug', mbpGetLastProfile());"
        await session.send_custom_message("eval_js", js)

    @reactive.Effect
    @reactive.event(input._last_profile_slug)
    def _apply_last_profile():
        slug = input._last_profile_slug()
        if not slug:
            return
        # Only apply if profile exists
        hp = APP_DIR / f"ad_history_{slug}.csv"
        if hp.exists():
            ui.update_selectize("compare_profile", selected=slug)

    # ===================================================================
    # Garmin Connect — UI + server logic
    # ===================================================================

    @output
    @render.ui
    def garmin_connect_ui():
        """Render Garmin Connect panel: login form OR connected state."""
        gsync = _get_garmin_sync()
