                ui.p("Garmin Connect sync is not available (missing garminconnect library).",
                     style="opacity: 0.6; font-size: 12px;"),
            )

        client = _garmin_client()
        mfa_state = _garmin_mfa_state()

        # --- State B: Connected ---
