                        f'font-size:10px;padding:1px 6px;border-radius:8px;margin-left:6px;">'
                        f'{atype.replace("_"," ")}</span>'
                    ) if atype else ""
                    # Use raw HTML button + JS to send activity ID via Shiny.setInputValue
                    load_btn_html = (
                        f'<button class="btn btn-primary btn-sm" '
                        f'onclick="Shiny.setInputValue(\'_garmin_load_id\', '
                        f'JSON.stringify({{id:\'{aid}\', ts:Date.now()}}));" '
                        f'style="margin-top:4px;margin-bottom:4px;">Load</button>'
                    )
                    activity_items.append(
                        ui.div(
                            ui.div(
                                ui.tags.span(aname, style="font-weight: 600; font-size: 13px;"),
                                ui.HTML(type_badge_html),
                                ui.tags.span(f" — {adate}", style="font-size: 11px; opacity: 0.7;"),
                                style="margin-bottom: 2px;",
                            ),
                            ui.div(
                                ui.tags.span(adist_km, style="font-size: 11px; margin-right: 8px;") if adist_km else "",
                                ui.tags.span(adur_str, style="font-size: 11px; margin-right: 8px;") if adur_str else "",
                            ),
                            ui.HTML(load_btn_html),
                            style="padding: 6px 8px; border: 1px solid rgba(255,255,255,0.08); border-radius: 6px; margin-bottom: 6px;",
                        )
                    )
            return ui.div(
                ui.div(
                    fa.icon_svg("circle-check", width="14px", height="14px", fill=COLOR_ELITE),
                    ui.tags.span(f" Connected as {name}",
                                 style=f"color: {COLOR_ELITE}; font-weight: 600; font-size: 13px; margin-left: 4px;"),
                    style="margin-bottom: 8px;",
                ),
                ui.layout_columns(
                    ui.input_action_button("garmin_fetch_activities", "Fetch Latest Activities",
                                           class_="btn-info btn-sm"),
                    ui.input_action_button("garmin_disconnect", "Disconnect",
                                           class_="btn-outline-danger btn-sm"),
