    # --- Try to auto-restore saved Garmin session on startup ---
    @reactive.Effect
    async def _garmin_auto_restore():
        """On startup, check if a saved Garmin session exists (runs once).
        Also sets the Garmin athlete display name as the default Compare profile.

        Tokens are persisted to disk (~/.garminconnect/) on login, so restoring
        from disk works for both Shinylive (Pyodide) and the dedicated server.
        """
        with reactive.isolate():
            if _garmin_restore_done():
                return
        _garmin_restore_done.set(True)
        gsync = _get_garmin_sync()
        if gsync is None:
            return
        with reactive.isolate():
            if _garmin_client() is not None:
                return  # already connected
        try:
            client = await _maybe_await(gsync.load_saved_session())
            if client is not None:
                _garmin_client.set(client)
                # Auto-set Garmin athlete name as default profile
                try:
                    dname = gsync.get_display_name(client)
                    if dname and dname != "Garmin User":
                        _garmin_athlete_name.set(dname)
                except Exception:
                    pass
        except Exception:
            pass

    # --- Auto-set Garmin athlete name as Compare profile ---
    @reactive.Effect
    def _garmin_set_default_profile():
        """When Garmin athlete name is discovered, auto-select it as the Compare profile
        only if no profile is currently selected."""
        name = _garmin_athlete_name()
        req(name)
        slug = sanitize_slug(name)
        if not slug or slug == "default":
            return
        # Only auto-set if no profile is currently selected
        with reactive.isolate():
            current = input.compare_profile()
        if current:
            return  # user already has a profile selected, don't override
        # Update selectize with this profile name (creates it if new)
        ui.update_selectize("compare_profile", choices={slug: name}, selected=slug)

    # --- Login button handler ---
    @reactive.Effect
    @reactive.event(input.garmin_connect_btn)
    async def _garmin_login():
        gsync = _get_garmin_sync()
        req(gsync)
        email = (input.garmin_email() or "").strip()
        password = input.garmin_password() or ""
        if not email or not password:
            _garmin_status.set("Please enter email and password.")
            return
        _garmin_status.set("Connecting to Garmin...")
        try:
            client = await _maybe_await(gsync.login_garmin(email, password))
            _garmin_client.set(client)
            _garmin_mfa_state.set(None)
            _garmin_status.set("")
            ui.notification_show("Connected to Garmin Connect!", type="message", duration=4)
            # Save session ID to localStorage for this device
            sid = getattr(client, "session_id", "")
            if sid and _IS_PYODIDE:
                await session.send_custom_message("eval_js", f"mbpSetGarminSession({json.dumps(sid)});")
            # Auto-set Garmin athlete name as default profile
            try:
                dname = gsync.get_display_name(client)
                if dname and dname != "Garmin User":
                    _garmin_athlete_name.set(dname)
                    # Register for background auto-fetch
                    try:
                        _slug = sanitize_slug(dname)
                        gsync._save_token(client, slug=_slug)
                        import auto_fetch
                        auto_fetch.register_athlete(_slug, dname, garmin=True)
                    except Exception:
                        pass
            except Exception:
                pass
        except gsync.GarminMFARequired as mfa_exc:
            _garmin_mfa_state.set((mfa_exc.client, mfa_exc.mfa_context))
            _garmin_status.set("")
        except Exception as e:
            _garmin_status.set(gsync.classify_error(e))

