            _garmin_status.set(f"Found {len(acts)} activity(ies)." if acts else "No activities found.")
        except Exception as e:
            err_msg = gsync.classify_error(e)
            if "expired" in err_msg.lower() or "401" in str(e) or "403" in str(e):
                _garmin_client.set(None)
                await _maybe_await(gsync.clear_session())
                _garmin_status.set("Session expired. Please reconnect.")
                ui.notification_show("Garmin session expired. Please reconnect.", type="error", duration=6)
            else:
