    # --- Load activity button handler (via JS bridge) ---
    @reactive.Effect
    @reactive.event(input._garmin_load_id)
    async def _garmin_load_activity():
        """Handle click on a Garmin activity 'Load' button."""
        gsync = _get_garmin_sync()
        req(gsync)
        raw = input._garmin_load_id()
        if not raw:
            return
        try:
            data = json.loads(raw)
            aid = str(data.get("id", ""))
        except Exception:
            return
        if not aid:
            return
        client = _garmin_client()
        req(client)

        # Find the activity in the cached list
        activities = _garmin_activities()
        act = None
        for a in activities:
            if str(a.get("activityId", "")) == aid:
                act = a
                break
        aname = act.get("activityName", "Activity") if act else f"Activity {aid}"
        adate = str(act.get("startTimeLocal", ""))[:10] if act else ""

        _garmin_status.set(f"Downloading {aname}...")
        try:
            fbytes = await _maybe_await(gsync.download_fit_bytes(client, aid))
        except Exception as e:
            err_msg = gsync.classify_error(e)
            if "expired" in err_msg.lower():
                _garmin_client.set(None)
                await _maybe_await(gsync.clear_session())
            _garmin_status.set(err_msg)
            ui.notification_show(err_msg, type="error", duration=6)
            return

        if fbytes is None:
            _garmin_status.set("No .FIT file found in this activity.")
            ui.notification_show("Activity doesn't contain a .FIT file.", type="warning", duration=5)
            return

        # Set the Garmin FIT data — this triggers parsed_fit() to re-run
        display_name = f"Garmin: {aname} ({adate})"
        _garmin_fit_data.set((fbytes, display_name))
        _garmin_status.set(f"Loaded: {display_name}")
        ui.notification_show(f"Loaded {display_name}", type="message", duration=5)

