    # --- Whoop auto-restore from saved tokens ---
    @reactive.Effect
    async def _whoop_auto_restore():
        """On startup, try to restore Whoop session from saved tokens (runs once).

        Tokens are persisted to disk on login, so restoring from disk works
        for both Shinylive (Pyodide) and the dedicated server.
        """
        wsync = _get_whoop_sync()
        if not wsync:
            return
        if _whoop_restore_done():
            return
        _whoop_restore_done.set(True)
        tokens = await _maybe_await(wsync.load_tokens())
        if tokens is None:
            return
        creds = await _maybe_await(wsync.load_credentials())
        if creds is None:
            return
        # Token still valid or try refresh
        if wsync.is_token_expired(tokens):
            try:
                tokens = await _maybe_await(wsync.refresh_access_token(
                    tokens["refresh_token"], creds["client_id"], creds["client_secret"]))
            except Exception:
                return
        _whoop_tokens.set(tokens)
        # Fetch profile
        try:
            profile, tokens = await _maybe_await(wsync.get_profile(tokens, creds["client_id"], creds["client_secret"]))
            _whoop_tokens.set(tokens)
            _whoop_profile.set(profile)
        except Exception:
            pass

