    # --- Whoop connect button ---
    @reactive.Effect
    @reactive.event(input.whoop_connect_btn)
    async def _whoop_connect():
        wsync = _get_whoop_sync()
        req(wsync)
        cid = input.whoop_client_id()
        csecret = input.whoop_client_secret()
        if not cid or not csecret:
            _whoop_status.set("Please enter both Client ID and Client Secret.")
            return

        await _maybe_await(wsync.save_credentials(cid, csecret))
        _whoop_status.set("Starting authorization...")

        # Build redirect_uri: use proxy ngrok URL if available (so callback works from any device)
        _redir_uri = None
        if _proxy_url:
            _redir_uri = f"{_proxy_url}/api/whoop/callback"

        try:
            if _redir_uri:
                auth_url, state = await _maybe_await(wsync.get_auth_url(cid, _redir_uri))
            else:
                auth_url, state = await _maybe_await(wsync.get_auth_url(cid))
        except Exception as e:
            _whoop_status.set(f"Error building auth URL: {e}")
            return

        # Open auth URL in the client's browser (not the server's)
        try:
            await session.send_custom_message("eval_js", f"window.open({json.dumps(auth_url)}, '_blank');")
        except Exception:
            pass

        _whoop_status.set("Waiting for authorization... (check your browser)")

        if _IS_PYODIDE:
            # In Pyodide, the proxy handles the callback server via long-poll
            try:
                code, recv_state, port = await _maybe_await(wsync.start_callback_server(timeout=120))
                if code is None:
                    _whoop_status.set("Authorization timed out. Please try again.")
                    return
                redirect_uri = f"http://localhost:{port}/callback"
                tokens = await _maybe_await(wsync.exchange_code_for_tokens(code, cid, csecret, redirect_uri))
                _whoop_tokens.set(tokens)
                profile, tokens = await _maybe_await(wsync.get_profile(tokens, cid, csecret))
                _whoop_tokens.set(tokens)
                _whoop_profile.set(profile)
                name = f"{profile.get('first_name', '')} {profile.get('last_name', '')}".strip()
                _whoop_status.set(f"Connected as {name}")
                ui.notification_show(f"\u2705 Connected to Whoop as {name}!", type="message", duration=5)
                # Register for background auto-fetch (Whoop)
                try:
                    _slug = sanitize_slug(name) if name else ""
                    if _slug:
                        wsync.save_tokens(tokens, slug=_slug)
                        wsync.save_credentials(cid, csecret, slug=_slug)
                        import auto_fetch
                        auto_fetch.register_athlete(_slug, name, whoop=True)
                except Exception:
                    pass
                # Save Whoop session ID to localStorage for this device
                w_sid = getattr(wsync, '_whoop_session_id', '')
                if w_sid and _IS_PYODIDE:
                    await session.send_custom_message("eval_js", f"mbpSetWhoopSession({json.dumps(w_sid)});")
            except Exception as e:
                _whoop_status.set(wsync.classify_error(e))
        else:
            # Server-side: use API server wait_callback if proxy available, else localhost fallback
            import threading

            def _do_oauth():
                try:
                    if _proxy_url and _redir_uri:
                        # Poll API server's wait_callback which waits for /api/whoop/callback
                        import urllib.request
                        payload = json.dumps({
                            "client_id": cid,
                            "client_secret": csecret,
                            "redirect_uri": _redir_uri,
                            "timeout": 120,
                        }).encode()
                        req = urllib.request.Request(
                            f"{_proxy_url}/api/whoop/wait_callback",
                            data=payload,
                            headers={"Content-Type": "application/json"},
                            method="POST",
                        )
                        resp = urllib.request.urlopen(req, timeout=130)
                        result = json.loads(resp.read())
                        if "error" in result:
                            _whoop_status.set(result["error"])
                            return
                        tokens = result.get("tokens")
                    else:
                        # Localhost fallback (only works if browser is on same machine)
                        code, recv_state, port = wsync.start_callback_server(timeout=120)
                        if code is None:
                            _whoop_status.set("Authorization timed out. Please try again.")
                            return
                        redirect_uri = f"http://localhost:{port}/callback"
                        tokens = wsync.exchange_code_for_tokens(code, cid, csecret, redirect_uri)

                    _whoop_tokens.set(tokens)
                    profile, tokens = wsync.get_profile(tokens, cid, csecret)
                    _whoop_tokens.set(tokens)
                    _whoop_profile.set(profile)
                    name = f"{profile.get('first_name', '')} {profile.get('last_name', '')}".strip()
                    _whoop_status.set(f"Connected as {name}")
                    ui.notification_show(f"\u2705 Connected to Whoop as {name}!", type="message", duration=5)
                    # Register for background auto-fetch (Whoop)
                    try:
                        _slug = sanitize_slug(name) if name else ""
                        if _slug:
                            wsync.save_tokens(tokens, slug=_slug)
                            wsync.save_credentials(cid, csecret, slug=_slug)
                            import auto_fetch
                            auto_fetch.register_athlete(_slug, name, whoop=True)
                    except Exception:
                        pass
                except Exception as e:
                    _whoop_status.set(wsync.classify_error(e))

            t = threading.Thread(target=_do_oauth, daemon=True)
            t.start()

