    # --- Whoop fetch latest 14 days ---
    @reactive.Effect
    @reactive.event(input.whoop_fetch_recent)
    async def _whoop_fetch_recent():
        wsync = _get_whoop_sync()
        req(wsync)
        tokens = _whoop_tokens()
        req(tokens)
        creds = await _maybe_await(wsync.load_credentials())
        req(creds)
        cid, csecret = creds["client_id"], creds["client_secret"]

        _whoop_status.set("Fetching 14 days of Whoop data...")

        try:
            recent, tokens = await _maybe_await(wsync.get_recent_recovery(tokens, cid, csecret, days=14))
            _whoop_tokens.set(tokens)
            _whoop_recent_data.set(recent)
        except Exception as e:
            err_msg = wsync.classify_error(e)
            if "expired" in err_msg.lower():
                _whoop_tokens.set(None)
                _whoop_profile.set(None)
                await _maybe_await(wsync.clear_tokens())
            _whoop_status.set(f"Whoop error: {err_msg}")
            ui.notification_show(f"Whoop fetch failed: {err_msg}", type="error", duration=8)
            return

        if not recent:
            _whoop_status.set("No scored Whoop data found for the last 14 days.")
            return

        # Auto-populate history for matching dates
        slug = None
        try:
            slug = input.profile()
        except Exception:
            pass
        if not slug:
            _whoop_status.set(f"Fetched {len(recent)} day(s). Select an athlete profile to auto-update history.")
            return

        athlete = slug.replace("_", " ").title()
        hp = history_path(athlete, APP_DIR)
        hist = load_history(hp)
        updated = 0

        if "date" not in hist.columns:
            _whoop_status.set("No sessions in profile to update.")
            return
        # Pre-compute date string for O(1) matching
        hist["_date_str"] = hist["date"].astype(str).str.strip()
        for rd in recent:
            d = rd.get("date", "")
            if not d:
                continue
            mask = hist["_date_str"] == d
            if not mask.any():
                continue
            # Vectorized update via .loc
            any_set = False
            for src_key, dst_col in _WHOOP_COL_MAP.items():
                val = rd.get(src_key)
                if val is not None:
                    hist.loc[mask, dst_col] = val
                    any_set = True
            if any_set:
                updated += int(mask.sum())
        hist.drop(columns=["_date_str"], inplace=True, errors="ignore")

        if updated > 0:
            save_history(hist, hp)
            _notify_athlete_tracker()  # update MBP Athletes.xlsx immediately
            await _persist_to_browser(slug)
            clear_history_cache()
            history_trigger.set(history_trigger() + 1)

        _whoop_status.set(f"Fetched {len(recent)} day(s). Updated {updated} session(s) with Whoop data.")
        ui.notification_show(f"\u2705 Updated {updated} session(s) with Whoop data.", type="message", duration=5)

    # --- Whoop auto-fill for current activity ---
    @reactive.Effect
    @reactive.event(input.whoop_autofill_current)
    async def _whoop_autofill_current():
        wsync = _get_whoop_sync()
        req(wsync)
        tokens = _whoop_tokens()
        req(tokens)
        creds = await _maybe_await(wsync.load_credentials())
        req(creds)
        cid, csecret = creds["client_id"], creds["client_secret"]

        # Get date of currently loaded FIT file
        try:
            pdata = parsed_fit()
            req(pdata)
            meta = pdata[0]
            start_time = meta.get("start_time")
            if start_time is None:
                _whoop_status.set("No activity loaded to auto-fill.")
                return
            st = pd.Timestamp(start_time)
            if st.tzinfo is None:
                st = st.tz_localize("UTC")
            pht = st.tz_convert("Asia/Manila")
            date_str = pht.strftime("%Y-%m-%d")
        except Exception:
            _whoop_status.set("Load a .FIT file first to auto-fill Whoop data.")
            return

        _whoop_status.set(f"Fetching Whoop data for {date_str}...")

        try:
            recovery, tokens = await _maybe_await(wsync.get_recovery_for_date(tokens, cid, csecret, date_str))
            _whoop_tokens.set(tokens)
            sleep_data, tokens = await _maybe_await(wsync.get_sleep_for_date(tokens, cid, csecret, date_str))
            _whoop_tokens.set(tokens)
            cycle_data, tokens = await _maybe_await(wsync.get_cycle_for_date(tokens, cid, csecret, date_str))
            _whoop_tokens.set(tokens)
        except Exception as e:
            err_msg = wsync.classify_error(e)
            if "expired" in err_msg.lower():
                _whoop_tokens.set(None)
                _whoop_profile.set(None)
                await _maybe_await(wsync.clear_tokens())
            _whoop_status.set(f"Whoop error: {err_msg}")
            ui.notification_show(f"Whoop auto-fill failed: {err_msg}", type="error", duration=8)
            return

        parts = []
        if recovery:
            rs = recovery.get("recovery_score")
            hrv = recovery.get("hrv_rmssd_milli")
            if rs is not None:
                parts.append(f"Recovery: {rs:.0f}%")
            if hrv is not None:
                parts.append(f"HRV: {hrv:.0f}ms")
        if cycle_data:
            strain = cycle_data.get("strain")
            if strain is not None:
                parts.append(f"Strain: {strain:.1f}")
        if sleep_data:
            sh = sleep_data.get("total_sleep_hours")
            sp = sleep_data.get("sleep_performance_percentage")
            if sh is not None:
                parts.append(f"Sleep: {sh:.1f}h")
            if sp is not None:
                parts.append(f"({sp:.0f}%)")

        if not parts:
            _whoop_status.set(f"No scored Whoop data for {date_str}.")
            return

        # Store as reactive for use during save
        _whoop_autofill_data.set({
            "date": date_str,
            "recovery": recovery,
            "sleep": sleep_data,
            "cycle": cycle_data,
        })

        summary = " | ".join(parts)
        _whoop_status.set(f"{date_str}: {summary}")
        ui.notification_show(f"Whoop: {summary}", type="message", duration=5)

