    # ---- Sprint Analysis reactive calc ----
    @reactive.Calc
    def sprint_analysis_result():
        """Run sprint detection + classification when sprint_mode is active."""
        if not input.sprint_mode():
            return None
        analysis = _get_analysis()
        data = parsed_fit()
        req(data)
        meta, df_raw, fname, fbytes = data
        mode = mode_resolved()
        df_work = df_work_calc()

        # Resample to 1Hz
        cols_1hz = ["heart_rate", "power_w", "cadence", "speed_mps", "ngp_speed_mps", "grade"]
        df_1hz, _ = analysis.resample_records_to_1hz(df_work, cols_1hz, max_gap_sec=10.0)
        if df_1hz.empty:
            return {"error": "No data after 1Hz resampling."}
        df_1hz = df_1hz.sort_index()
        t0 = df_work.index[0]
        df_1hz["elapsed_sec"] = (df_1hz.index - t0).total_seconds()

        # Total duration
        total_elapsed_sec = float(df_1hz["elapsed_sec"].max())
        total_minutes = total_elapsed_sec / 60.0

        # HRmax override
        hr_max_input = None
        try:
            v = input.sprint_hrmax()
            if v is not None and float(v) > 0:
                hr_max_input = float(v)
        except Exception:
            pass

        # Detect sprints
        try:
            sprint_result = _sprint_mod.detect_sprints(df_1hz, mode, hr_max=hr_max_input)
        except Exception as e:
            return {"error": f"Sprint detection failed: {e}"}

        if sprint_result is None:
            return {"error": "Fewer than 2 sprints detected. Ensure this is a hill sprint session with clear on/off efforts."}

        # Warmup deviation
        warmup_dev = None
        if sprint_result.sprints:
            first_start = sprint_result.sprints[0].start_sec
            if first_start > 600:  # >10 min warmup
                baseline_hr = hr_max_input * 0.55 if hr_max_input else None
                warmup_dev = _sprint_mod.compute_warmup_deviation(df_1hz, first_start, baseline_hr)

        # Terrain info
        terrain_info = compute_terrain(df_work, max_gap_sec=10.0, mode=mode)

        # Weather & name
        garmin_name = (meta.get("athlete_name") or "").strip() or "Athlete"
        weather = get_activity_weather_summary(meta, df_raw)

        return {
            "sprint_result": sprint_result,
            "warmup_dev": warmup_dev,
            "meta": meta,
            "df_raw": df_raw,
            "fname": fname,
            "mode": mode,
            "terrain_info": terrain_info,
            "garmin_name": garmin_name,
            "weather": weather,
            "total_minutes": total_minutes,
            "hr_max_input": hr_max_input,
        }

