    async def _save_history():
        # --- Sprint mode save branch ---
        if input.sprint_mode():
            sprint_res = sprint_analysis_result()
            req(sprint_res)
            if "error" in sprint_res:
                ui.notification_show(f"Cannot save: {sprint_res['error']}", type="error")
                return
            sr = sprint_res["sprint_result"]
            meta = sprint_res["meta"]
            athlete = input.athlete_id() or sprint_res.get("garmin_name", "Athlete")
            start_time = meta.get("start_time")
            start_iso = str(start_time.isoformat()) if hasattr(start_time, "isoformat") else str(start_time)
            terrain_info = sprint_res.get("terrain_info")
            dist_val = terrain_info.distance_km if terrain_info and np.isfinite(terrain_info.distance_km) else 0.0
            elev_val = terrain_info.elev_gain_m if terrain_info and np.isfinite(terrain_info.elev_gain_m) else 0.0

            row = {
                "start_time_iso": start_iso,
                "athlete_id": athlete,
                "date": str(start_time.date()) if hasattr(start_time, "date") else "",
                "mode": sprint_res.get("mode", "run"),
                "terrain": terrain_info.terrain if terrain_info else "Unknown",
                "output_used": sr.sprints[0].output_unit if sr.sprints else "W",
                "distance_km": dist_val,
                "elev_gain_m": elev_val,
                "decoupling_pct": sr.fatigue_index_pct,
                "status": sr.session_verdict,
                "total_minutes": sprint_res.get("total_minutes", 0),
                "file_name": sprint_res.get("fname", ""),
                "weather_summary": sprint_res.get("weather", ""),
                "hill_sprints": "1",
                "sprint_duration_sec": sr.sprints[0].duration_sec if sr.sprints else 30,
                "sprint_sets": sr.num_sprints,
                "sprint_fatigue_index_pct": sr.fatigue_index_pct,
                "sprint_peak_hr_pct_max": sr.peak_hr_pct_of_max if np.isfinite(sr.peak_hr_pct_of_max) else float("nan"),
                "sprint_verdict": sr.session_verdict,
                "avg_hr": sr.hr_max_session if np.isfinite(sr.hr_max_session) else float("nan"),
                "avg_power_w": sr.avg_mean_output if np.isfinite(sr.avg_mean_output) else float("nan"),
            }

            # Whoop auto-fill
            waf = _whoop_autofill_data()
            w_recovery = waf.get("recovery") if waf else None
            w_sleep = waf.get("sleep") if waf else None
            w_cycle = waf.get("cycle") if waf else None
            if w_recovery:
                if w_recovery.get("recovery_score") is not None:
                    row["whoop_score"] = w_recovery["recovery_score"]
                if w_recovery.get("hrv_rmssd_milli") is not None:
                    row["whoop_hrv_ms"] = w_recovery["hrv_rmssd_milli"]
                if w_recovery.get("resting_heart_rate") is not None:
                    row["whoop_resting_hr"] = w_recovery["resting_heart_rate"]
            if w_sleep:
                if w_sleep.get("sleep_performance_percentage") is not None:
                    row["whoop_sleep_perf"] = w_sleep["sleep_performance_percentage"]
                if w_sleep.get("total_sleep_hours") is not None:
                    row["whoop_sleep_hours"] = w_sleep["total_sleep_hours"]
            if w_cycle:
                if w_cycle.get("strain") is not None:
                    row["whoop_strain"] = w_cycle["strain"]

            hp = history_path(athlete, APP_DIR)
            hist = load_history(hp)
            hist, action = _history_upsert_row(hist, row)
            try:
                save_history(hist, hp)
                _notify_athlete_tracker()
                await _persist_to_browser(sanitize_slug(athlete))
                clear_history_cache()
                history_trigger.set(history_trigger() + 1)
                ui.notification_show(f"Sprint session {action} to history for {athlete}.", type="message")
                # Copy FIT file from _temp to athlete's permanent directory
                try:
                    _slug = sanitize_slug(athlete)
                    _temp_path = _fit_store_path_local("_temp", start_iso)
                    _perm_path = _fit_store_path_local(_slug, start_iso)
                    if _temp_path.exists():
                        _perm_path.parent.mkdir(parents=True, exist_ok=True)
                        import shutil
                        shutil.copy2(str(_temp_path), str(_perm_path))
                        _temp_path.unlink(missing_ok=True)  # clean up temp
                    if _perm_path.exists():
                        await _store_fit_on_server(_perm_path.read_bytes(), _slug, start_iso)
                except Exception:
                    pass
            except Exception as e:
                ui.notification_show(f"Error saving sprint history: {e}", type="error")
            return

        result = analysis_result()
        req(result)
        if "error" in result:
            return

        athlete = input.athlete_id() or result.get("garmin_name", "Athlete")
        res = result["res"]
        meta = result["meta"]
        start_time = meta.get("start_time")
        start_iso = str(start_time.isoformat()) if hasattr(start_time, "isoformat") else str(start_time)

        # RPE values (user-entered, optional)
        try:
            rpe_h1 = float(input.save_rpe_h1()) if input.save_rpe_h1() is not None else float("nan")
        except Exception:
            rpe_h1 = float("nan")
        try:
            rpe_h2 = float(input.save_rpe_h2()) if input.save_rpe_h2() is not None else float("nan")
        except Exception:
            rpe_h2 = float("nan")

        # Distance / Elevation — use user-entered value if available, else FIT data
        is_stairmaster = result["mode"] == "stairmaster"
        fit_dist = result["terrain_info"].distance_km
        fit_elev = result["terrain_info"].elev_gain_m
        if is_stairmaster:
            try:
                elev_val = float(input.save_elev_gain_m()) if input.save_elev_gain_m() is not None else fit_elev
            except Exception:
                elev_val = fit_elev
            dist_val = fit_dist
        else:
            try:
                dist_val = float(input.save_distance_km()) if input.save_distance_km() is not None else fit_dist
            except Exception:
                dist_val = fit_dist
            elev_val = fit_elev

        # Whoop auto-fill data (if available)
        waf = _whoop_autofill_data()
        w_recovery = waf.get("recovery") if waf else None
        w_sleep = waf.get("sleep") if waf else None
        w_cycle = waf.get("cycle") if waf else None

        row = {
            "start_time_iso": start_iso,
            "athlete_id": athlete,
            "date": str(start_time.date()) if hasattr(start_time, "date") else "",
            "mode": result["mode"],
            "terrain": result["terrain"],
            "output_used": result["output_used"],
            "distance_km": dist_val,
            "elev_gain_m": elev_val,
            "decoupling_pct": res.decoupling_pct,
            "low_thr": result["low_thr"],
            "high_thr": result["high_thr"],
            "status": result["status"],
            "ef": result["ef"],
            "avg_hr": result["avg_hr"],
            "avg_output": result["avg_out"],
            "avg_speed_kph": result["avg_speed_kph"],
            "avg_power_w": result["avg_power_w"],
            "output_unit": result["output_unit"],
            "total_minutes": result["total_minutes"],
            "minutes_analyzed": result["minutes_analyzed"],
            "file_name": result.get("fname", ""),
            "weather_summary": result.get("weather", ""),
            "hr_h1": res.hr1,
            "hr_h2": res.hr2,
            "out_h1": res.out1,
            "out_h2": res.out2,
            "drift_driver": result["driver_label"],
            "rpe_h1": rpe_h1,
            "rpe_h2": rpe_h2,
            "warmup_min": result["warmup_min"],
            "end_exclude_min": result["end_exclude_min"],
            "event_goal_min": result["event_goal_min"],
            "erg_subtype": result["erg_subtype"],
            "temp_min_c": result.get("temp_min", float("nan")),
            "temp_max_c": result.get("temp_max", float("nan")),
            "time_to_drift_sec": result.get("drift_sec", float("nan")),
            "time_to_drift_elapsed_sec": result.get("drift_elapsed_sec", float("nan")),
        }

        # Add Whoop auto-fill columns if data is available
        if w_recovery:
            if w_recovery.get("recovery_score") is not None:
                row["whoop_score"] = w_recovery["recovery_score"]
            if w_recovery.get("hrv_rmssd_milli") is not None:
                row["whoop_hrv_ms"] = w_recovery["hrv_rmssd_milli"]
            if w_recovery.get("resting_heart_rate") is not None:
                row["whoop_resting_hr"] = w_recovery["resting_heart_rate"]
            if w_recovery.get("spo2_percentage") is not None:
                row["whoop_spo2"] = w_recovery["spo2_percentage"]
            if w_recovery.get("skin_temp_celsius") is not None:
                row["whoop_skin_temp_c"] = w_recovery["skin_temp_celsius"]
        if w_sleep:
            if w_sleep.get("sleep_performance_percentage") is not None:
                row["whoop_sleep_perf"] = w_sleep["sleep_performance_percentage"]
            if w_sleep.get("sleep_efficiency_percentage") is not None:
                row["whoop_sleep_efficiency"] = w_sleep["sleep_efficiency_percentage"]
            if w_sleep.get("total_sleep_hours") is not None:
                row["whoop_sleep_hours"] = w_sleep["total_sleep_hours"]
            if w_sleep.get("rem_min") is not None:
                row["whoop_rem_min"] = w_sleep["rem_min"]
            if w_sleep.get("sws_min") is not None:
                row["whoop_sws_min"] = w_sleep["sws_min"]
            if w_sleep.get("light_min") is not None:
                row["whoop_light_min"] = w_sleep["light_min"]
            if w_sleep.get("awake_min") is not None:
                row["whoop_awake_min"] = w_sleep["awake_min"]
            if w_sleep.get("respiratory_rate") is not None:
                row["whoop_resp_rate"] = w_sleep["respiratory_rate"]
        if w_cycle:
            if w_cycle.get("strain") is not None:
                row["whoop_strain"] = w_cycle["strain"]
            if w_cycle.get("kilojoules") is not None:
                row["whoop_calories_kj"] = w_cycle["kilojoules"]

        # Compute TSS for this session and store in the row
        try:
            _mode = result["mode"]
            _dur_sec = float(result["total_minutes"]) * 60 if np.isfinite(float(result.get("total_minutes", 0))) else 0
            _power_1hz = None
            _pd = parsed_data()
            if _pd is not None:
                _, _df_raw = _pd
                if "power_w" in _df_raw.columns:
                    _power_1hz = pd.to_numeric(_df_raw["power_w"], errors="coerce")
            _hr_1hz = None
            if _pd is not None:
                _, _df_raw = _pd
                if "heart_rate_bpm" in _df_raw.columns:
                    _hr_1hz = pd.to_numeric(_df_raw["heart_rate_bpm"], errors="coerce")
            _ngp = 0.0
            if _pd is not None:
                _, _df_raw = _pd
                if "ngp_speed_mps" in _df_raw.columns:
                    _ngp_s = pd.to_numeric(_df_raw["ngp_speed_mps"], errors="coerce").dropna()
                    _ngp = float(_ngp_s.mean()) if not _ngp_s.empty else 0.0
            _avg_spd = float(result.get("avg_speed_kph", 0) or 0) / 3.6
            _ftp_w = 0
            try:
                _ftp_w = float(input.tss_ftp_w() or 0)
            except Exception:
                try:
                    _ftp_w = float(input.ftp_w() or 0)
                except Exception:
                    pass
            _ftp_pace = 0.0
            try:
                _ftp_pace = _parse_pace_to_mps(input.tss_ftp_pace() or "")
            except Exception:
                pass
            _lthr = 0
            try:
                _lthr = float(input.tss_lthr() or 0)
            except Exception:
                pass
            _rhr = 0
            try:
                _rhr = float(input.tss_resting_hr() or 0)
            except Exception:
                pass
            _mhr = 0
            try:
                _mhr = float(input.tss_max_hr() or 0)
            except Exception:
                pass
            _tss_r = auto_compute_tss(
                mode=_mode, duration_sec=_dur_sec,
                power_w_1hz=_power_1hz, ftp_w=_ftp_w,
                ngp_mps=_ngp, avg_speed_mps=_avg_spd, ftp_pace_mps=_ftp_pace,
                hr_1hz=_hr_1hz, lthr=_lthr, resting_hr=_rhr, max_hr=_mhr,
            )
            if np.isfinite(_tss_r.get("tss", float("nan"))):
                row["tss"] = round(_tss_r["tss"], 1)
                row["tss_method"] = _tss_r.get("method", "")
                row["intensity_factor"] = round(_tss_r.get("if_", float("nan")), 3)
                row["normalized_power_w"] = round(_tss_r.get("np", float("nan")), 0) if np.isfinite(_tss_r.get("np", float("nan"))) else ""
        except Exception:
            pass

        hp = history_path(athlete, APP_DIR)
        hist = load_history(hp)
        hist, action = _history_upsert_row(hist, row)
        try:
            save_history(hist, hp)
            _notify_athlete_tracker()  # update MBP Athletes.xlsx immediately
            await _persist_to_browser(sanitize_slug(athlete))
            clear_history_cache()
            history_trigger.set(history_trigger() + 1)
            ui.notification_show(f"Session {action} to history for {athlete}.", type="message")
            # Copy FIT file from _temp to athlete's permanent directory
            try:
                _slug = sanitize_slug(athlete)
                _temp_path = _fit_store_path_local("_temp", start_iso)
                _perm_path = _fit_store_path_local(_slug, start_iso)
                if _temp_path.exists():
                    _perm_path.parent.mkdir(parents=True, exist_ok=True)
                    import shutil
                    shutil.copy2(str(_temp_path), str(_perm_path))
                    _temp_path.unlink(missing_ok=True)  # clean up temp
                # Also try api_server (for remote/Pyodide access)
                if _perm_path.exists():
                    await _store_fit_on_server(_perm_path.read_bytes(), _slug, start_iso)
            except Exception:
                pass  # best-effort
        except Exception as e:
            ui.notification_show(f"Error saving history: {e}", type="error")

