    # --- Rename profile ---
    @reactive.Effect
    @reactive.event(input.rename_profile_btn)
    async def _rename_profile():
        old_slug = input.compare_profile()
        new_name = (input.rename_profile_input() or "").strip()
        req(old_slug)
        if not new_name:
            ui.notification_show("Please enter a new name.", type="warning", duration=3)
            return
        new_slug = sanitize_slug(new_name)
        if new_slug == old_slug:
            ui.notification_show("Name is the same.", type="warning", duration=3)
            return
        # Check if new slug already exists
        new_hp = APP_DIR / f"ad_history_{new_slug}.csv"
        if new_hp.exists():
            ui.notification_show(f"Profile '{new_name}' already exists.", type="error", duration=4)
            return
        old_hp = APP_DIR / f"ad_history_{old_slug}.csv"
        if not old_hp.exists():
            ui.notification_show("Current profile not found.", type="error", duration=3)
            return
        # Read, update athlete_id, write to new path
        hist = load_history(old_hp)
        if "athlete_id" in hist.columns:
            hist["athlete_id"] = new_name
        save_history(hist, new_hp)
        # Remove old file and old localStorage
        old_hp.unlink()
        _notify_athlete_tracker()  # update MBP Athletes.xlsx immediately
        await _remove_from_browser(old_slug)
        # Persist new to browser
        await _persist_to_browser(new_slug)
        # Update last-used profile
        js = f"mbpSetLastProfile({json.dumps(new_slug)});"
        await session.send_custom_message("eval_js", js)
        clear_history_cache()
        history_trigger.set(history_trigger() + 1)
        # Clear input and select the new profile
        ui.update_text("rename_profile_input", value="")
        ui.notification_show(f"Profile renamed to '{new_name}'.", type="message", duration=5)

