    # --- Date range: default to Philippine dates of sessions ---
    @reactive.Effect
    async def _set_date_range_defaults():
        """Set date range to span all session dates (converted to PHT).

        Small delay lets the client-side Bootstrap datepicker plugin
        finish initialising before the server pushes an update message.
        Without this, the first update can hit before ``bsDatepicker``
        is registered, causing a harmless but noisy JS console error.
        """
        hist = compare_history()
        if hist is None or hist.empty or "date" not in hist.columns:
            return
        dates = pd.to_datetime(hist["date"], errors="coerce").dropna()
        if dates.empty:
            return
        await asyncio.sleep(1)  # let datepicker JS initialise
        min_date = dates.min().date()
        max_date = dates.max().date()
        ui.update_date_range("compare_date_range", start=min_date, end=max_date)

    @reactive.Calc
    def compare_history():
        """Load history for selected profile."""
        _ = history_trigger()
        slug = input.compare_profile()
        req(slug)
        hp = APP_DIR / f"ad_history_{slug}.csv"
        if not hp.exists():
            return pd.DataFrame(columns=HISTORY_COLUMNS)
        try:
            mtime = hp.stat().st_mtime
            return load_history_cached(str(hp), mtime)
        except Exception:
            return load_history(hp)

    # --- Hill Sprint reminder (fires when profile data changes) ---
    _hill_sprint_reminded = reactive.Value("")  # tracks which profile was last reminded

    @reactive.Effect
    def _hill_sprint_reminder():
        hist = compare_history()
        if hist is None or hist.empty:
            return
        slug = ""
        try:
            slug = input.compare_profile() or ""
        except Exception:
            return
        with reactive.isolate():
            if _hill_sprint_reminded() == slug:
                return  # already reminded for this profile
        _hill_sprint_reminded.set(slug)

        # Check phase — only remind during Base phase
        try:
            phase = int(input.training_phase_slider() or 0)
            if phase != 0:  # 0 = Base
                return
        except Exception:
            pass  # default to Base if slider not available

        # Find last hill sprint session
        if "hill_sprints" not in hist.columns or "date" not in hist.columns:
            # No hill sprint data yet — remind after first day
            ui.notification_show(
                "\u23f0 Hill Sprint reminder: No hill sprint sessions recorded yet.\n"
                "Protocol: 30s \u00d7 6-10 all-out (first 15s max, last 15s gassed). "
                "4 min rest between sets. Stop if next rep >10% slower.",
                type="warning", duration=12,
            )
            return

        hs_rows = hist[hist["hill_sprints"].astype(str).str.strip() == "1"]
        if hs_rows.empty:
            ui.notification_show(
                "\u23f0 Hill Sprint reminder: No hill sprint sessions recorded yet.\n"
                "Protocol: 30s \u00d7 6-10 all-out (first 15s max, last 15s gassed). "
                "4 min rest between sets. Stop if next rep >10% slower.",
                type="warning", duration=12,
            )
            return

        last_hs_date = pd.to_datetime(hs_rows["date"], errors="coerce").max()
        if pd.isna(last_hs_date):
            return
        days_since = (pd.Timestamp.now() - last_hs_date).days
        if days_since >= 7:
            ui.notification_show(
                f"\u23f0 Hill Sprint reminder: It's been {days_since} days since your last hill sprint session.\n"
                "Protocol: 30s \u00d7 6-10 all-out (first 15s max, last 15s gassed). "
                "4 min rest between sets. Stop if next rep >10% slower.",
                type="warning", duration=12,
            )

    @reactive.Calc
    def compare_filtered():
        """Apply all sidebar filters to history."""
        hist = compare_history()
        req(not hist.empty)

        # Filter out meta rows
        if "start_time_iso" in hist.columns:
            hist = hist[hist["start_time_iso"].astype(str) != PROFILE_META_START_TIME_ISO].copy()
        else:
            hist = hist.copy()
        if hist.empty:
            return hist

        # Pre-compute normalised mode column ONCE (avoids 3+ redundant .str chains)
        if "mode" in hist.columns:
            hist["_mode_lower"] = hist["mode"].astype(str).str.strip().str.lower()
        else:
            hist["_mode_lower"] = "unknown"

        # Pre-sort by date ONCE (downstream consumers no longer need to re-sort)
        if "date" in hist.columns:
            hist["_dt"] = pd.to_datetime(hist["date"], errors="coerce")
            hist = hist.dropna(subset=["_dt"]).sort_values("_dt")

        # Activity type filter (switch-based)
        active_types = []
        for t in ["run", "bike", "erg", "ski", "stairmaster"]:
            try:
                if input[f"compare_type_{t}"]():
                    active_types.append(t)
            except Exception:
                active_types.append(t)  # default to included if switch not yet rendered
        if active_types:
            hist = hist[hist["_mode_lower"].isin(active_types)]

        # Duration quality filter (Run/Stairmaster >= 60 min, Bike/Erg/Ski >= 90 min)
        try:
            if input.compare_quality_duration():
                if "total_minutes" in hist.columns:
                    tm = pd.to_numeric(hist["total_minutes"], errors="coerce")
                    short_thr = hist["_mode_lower"].map(
                        {"run": 60, "stairmaster": 60, "bike": 90, "erg": 90, "ski": 90}
                    ).fillna(60)
                    hist = hist[tm >= short_thr]
        except Exception:
            pass

        # Distance filter (target + tolerance range slider)
        try:
            target = float(input.compare_target_dist_km() or 0)
        except Exception:
            target = 0.0
        if target > 0 and "distance_km" in hist.columns:
            try:
                tol_range = input.compare_dist_tol_km()
                tol_lo = float(tol_range[0]) if tol_range else 0
                tol_hi = float(tol_range[1]) if tol_range else 100
            except Exception:
                tol_lo, tol_hi = 0, 100
            dk = pd.to_numeric(hist["distance_km"], errors="coerce")
            hist = hist[(dk >= target - tol_hi) & (dk <= target + tol_hi)]

        # Temperature filter
        try:
            temp_range = input.compare_temp_range()
            temp_lo = float(temp_range[0])
            temp_hi = float(temp_range[1])
        except Exception:
            temp_lo, temp_hi = 0, 40
        include_unknown_temp = True
        try:
            include_unknown_temp = bool(input.compare_include_unknown_temp())
        except Exception:
            pass
        if "temp_min_c" in hist.columns or "temp_max_c" in hist.columns:
            t_min = pd.to_numeric(hist.get("temp_min_c", pd.Series(dtype=float)), errors="coerce")
            t_max = pd.to_numeric(hist.get("temp_max_c", pd.Series(dtype=float)), errors="coerce")
            has_temp = t_min.notna() | t_max.notna()
            in_range = (
                ((t_min.fillna(-999) >= temp_lo) | t_min.isna()) &
                ((t_max.fillna(999) <= temp_hi) | t_max.isna())
            )
            if include_unknown_temp:
                hist = hist[in_range | ~has_temp]
            else:
                hist = hist[in_range & has_temp]

        # Elevation profile filter (for run sessions)
        try:
            elev_types = []
            if input.compare_elev_flat():
                elev_types.append("flat")
            if input.compare_elev_rolling():
                elev_types.append("rolling")
            if input.compare_elev_hilly():
                elev_types.append("hilly")
            if input.compare_elev_mountainous():
                elev_types.append("mountainous")
            if elev_types and "terrain" in hist.columns:
                terrain_col = hist["terrain"].astype(str).str.strip().str.lower()
                is_run = hist["_mode_lower"] == "run"
                terrain_ok = terrain_col.isin(elev_types)
                hist = hist[~is_run | terrain_ok]
        except Exception:
            pass

        # Date filter (uses pre-computed _dt column from above)
        try:
            dr = input.compare_date_range()
            if dr and len(dr) == 2 and "_dt" in hist.columns:
                hist = hist[(hist["_dt"] >= pd.Timestamp(dr[0])) & (hist["_dt"] <= pd.Timestamp(dr[1]))]
        except Exception:
            pass

        return hist

    @output
    @render.ui
    def compare_kpis():
        hist = compare_filtered()
        req(not hist.empty)

        # Already pre-sorted by _dt and has _mode_lower from compare_filtered()
        hs = hist
        if hs.empty:
            return ui.div()

        # Filter run sessions only for run-specific KPIs (uses pre-computed _mode_lower)
        runs = hs[hs["_mode_lower"] == "run"]

        # Quality runs: ≥60 min only — used for EF Var, AD%, Recovery HR, RPE
        _tm = pd.to_numeric(runs["total_minutes"], errors="coerce") if "total_minutes" in runs.columns else pd.Series(dtype=float, index=runs.index)
        qruns = runs[_tm >= 60] if not _tm.empty else runs

        def _kpi_card(title, value, icon_name, accent, card_id, subtitle="", trend=""):
            """Custom styled KPI card matching Recovery HR style. Clickable for info.
            trend: formatted string like '▲ 5.2%' or '▼ 3.1%' or '' for no data.
            """
            h = accent.lstrip("#")
            r, g, b = int(h[0:2], 16), int(h[2:4], 16), int(h[4:6], 16)
            bg = f"rgba({r},{g},{b},0.12)"
            border = f"rgba({r},{g},{b},0.25)"
            ico = fa.icon_svg(icon_name, width="28px", height="28px", fill=accent)
            ico_cls = f"kpi-ico-{icon_name}"
            sub_el = [ui.tags.span(subtitle, style=f"font-size:10px; opacity:0.7; color:{accent}; display:block; margin-top:2px; white-space:pre-line;")] if subtitle else []
            # Trend indicator element
            if trend.startswith("▲"):
                trend_el = ui.tags.span(trend, class_="kpi-trend kpi-trend-up", title="Improved — moving toward build phase")
            elif trend.startswith("▼"):
                trend_el = ui.tags.span(trend, class_="kpi-trend kpi-trend-down", title="Worsened — moving toward overtraining")
            elif trend:
                trend_el = ui.tags.span(trend, class_="kpi-trend kpi-trend-flat", title="No change")
            else:
                trend_el = None
            click_js = f"Shiny.setInputValue('kpi_info_click','{card_id}',{{priority:'event'}});"
            trend_els = [trend_el] if trend_el else []
            return ui.div(
                ui.div(
                    ui.div(ico, class_=ico_cls, style="margin-right:10px; display:flex; align-items:center;"),
                    ui.div(
                        ui.tags.span(title, style="font-size:11px; opacity:0.7; display:block;"),
                        ui.tags.span(value, style=f"font-size:22px; font-weight:800; color:{accent};"),
                        *trend_els,
                        *sub_el,
                    ),
                    style="display:flex; align-items:center; padding:12px 16px;",
                ),
                style=f"background:{bg}; border:1px solid {border}; border-radius:8px; height:100%; cursor:pointer;",
                onclick=click_js,
            )

        # --- KPI 1: 4-Week Run EF Variance (runs ≥60 min) ---
        ef_var_val = "—"
        ef_var_color = "#facc15"
        ef_var_trend = ""  # lower CV = better (toward build)
        if not qruns.empty and "ef" in qruns.columns:
            cutoff = pd.Timestamp.now() - pd.Timedelta(weeks=4)
            recent_runs = qruns[qruns["_dt"] >= cutoff]
            ef_4w = pd.to_numeric(recent_runs["ef"], errors="coerce").dropna()
            if len(ef_4w) >= 2:
                ef_mean = ef_4w.mean()
                if ef_mean > 0:
                    ef_cv = (ef_4w.std() / ef_mean) * 100
                    ef_var_val = f"{ef_cv:.1f}%"
                    ef_var_color = "#4ade80" if ef_cv <= 2 else "#facc15"
                    # Trend: compare CV with vs without latest session
                    # Use absolute pp difference (values are already %)
                    if len(ef_4w) >= 3:
                        ef_prev = ef_4w.iloc[:-1]
                        prev_mean = ef_prev.mean()
                        if prev_mean > 0:
                            prev_cv = (ef_prev.std() / prev_mean) * 100
                            diff = ef_cv - prev_cv  # percentage-point change
                            # Lower CV = improved (invert sign)
                            if diff < -0.1:
                                ef_var_trend = f"▲ {abs(diff):.1f}pp"
                            elif diff > 0.1:
                                ef_var_trend = f"▼ {abs(diff):.1f}pp"

        # --- KPI 2: Average Run Decoupling % (runs ≥60 min) ---
        avg_dec_val = "—"
        avg_dec_color = "#4ade80"
        avg_dec_trend = ""  # lower decoupling = better (toward build)
        if not qruns.empty and "decoupling_pct" in qruns.columns:
            dec_vals = pd.to_numeric(qruns["decoupling_pct"], errors="coerce").dropna()
            if not dec_vals.empty:
                avg_dec_pct = dec_vals.mean()
                avg_dec_val = f"{avg_dec_pct:.1f}%"
                if avg_dec_pct <= 3:
                    avg_dec_color = "#4ade80"
                elif avg_dec_pct <= 5:
                    avg_dec_color = "#facc15"
                else:
                    avg_dec_color = "#ff6b6b"
                # Trend: latest session decoupling vs previous session
                # Use absolute pp difference (values are already %)
                if len(dec_vals) >= 2:
                    cur_dec = float(dec_vals.iloc[-1])
                    prev_dec = float(dec_vals.iloc[-2])
                    diff = cur_dec - prev_dec  # percentage-point change
                    # Lower decoupling = improved (invert sign)
                    if diff < -0.2:
                        avg_dec_trend = f"▲ {abs(diff):.1f}pp"
                    elif diff > 0.2:
                        avg_dec_trend = f"▼ {abs(diff):.1f}pp"

        # --- KPI 3: AeT/FTP Ratio (steady-state run power vs FTP) ---
        aet_ftp_val = "—"
        aet_ftp_color = "#facc15"
        aet_ftp_sub = ""
        aet_ftp_trend = ""  # higher ratio = better (toward build)
        ftp_w = 0
        try:
            ftp_w = float(input.ftp_w() or 0)
        except Exception:
            pass
        if ftp_w > 0 and not runs.empty and "avg_power_w" in runs.columns:
            run_power = pd.to_numeric(runs["avg_power_w"], errors="coerce").dropna()
            run_power = run_power[run_power > 0]
            if not run_power.empty:
                aet_power = run_power.mean()
                ratio = (aet_power / ftp_w) * 100
                aet_ftp_val = f"{ratio:.0f}%"
                aet_ftp_sub = f"{aet_power:.0f}W / {ftp_w:.0f}W"
                aet_ftp_color = "#4ade80" if ratio >= 80 else "#facc15"
                # Trend: avg power with vs without latest session
                # Use absolute pp difference (values are already %)
                if len(run_power) >= 2:
                    prev_power = run_power.iloc[:-1].mean()
                    prev_ratio = (prev_power / ftp_w) * 100
                    diff = ratio - prev_ratio  # percentage-point change
                    # Higher ratio = improved
                    if diff > 0.5:
                        aet_ftp_trend = f"▲ {abs(diff):.1f}pp"
                    elif diff < -0.5:
                        aet_ftp_trend = f"▼ {abs(diff):.1f}pp"
        elif ftp_w <= 0:
            aet_ftp_sub = "Set FTP in Session → Settings"

        # 4-week avg run pace and avg normalized power from quality runs (≥60 min)
        _pace_sub = ""      # → Avg Run AD% card
        _norm_pwr_sub = ""  # → 4wk Run EF Var card
        if not qruns.empty:
            cutoff_4w = pd.Timestamp.now() - pd.Timedelta(weeks=4)
            qr4w = qruns[qruns["_dt"] >= cutoff_4w]
            if not qr4w.empty:
                # Avg run pace (from avg_speed_kph → m/s)
                if "avg_speed_kph" in qr4w.columns:
                    spd_vals = pd.to_numeric(qr4w["avg_speed_kph"], errors="coerce").dropna()
                    spd_vals = spd_vals[spd_vals > 0]
                    if not spd_vals.empty:
                        _pace_sub = f"4wk Pace {pace_str_from_speed_mps(spd_vals.mean() / 3.6)}"
                # Avg normalized power (from avg_power_w)
                if "avg_power_w" in qr4w.columns:
                    pwr_vals = pd.to_numeric(qr4w["avg_power_w"], errors="coerce").dropna()
                    pwr_vals = pwr_vals[pwr_vals > 0]
                    if not pwr_vals.empty:
                        _norm_pwr_sub = f"4wk Avg {pwr_vals.mean():.0f}W"

        # --- KPI 4: Latest Time-to-Drift ---
        ttd_val = "—"
        ttd_color = "#4ade80"
        ttd_trend = ""  # higher TTD = better (toward build)
        if "time_to_drift_sec" in hs.columns:
            ttd_num = pd.to_numeric(hs["time_to_drift_sec"], errors="coerce")
            ttd_valid = hs[ttd_num.notna() & (ttd_num > 0)]
            if not ttd_valid.empty:
                latest_ttd_sec = float(ttd_num[ttd_valid.index[-1]])
                latest_ttd_min = latest_ttd_sec / 60.0
                ttd_val = f"{latest_ttd_min:.0f} min"
                if latest_ttd_min < 60:
                    ttd_color = "#ff6b6b"
                elif latest_ttd_min <= 120:
                    ttd_color = "#facc15"
                else:
                    ttd_color = "#4ade80"
                # Trend: latest vs previous session TTD
                if len(ttd_valid) >= 2:
                    prev_ttd = float(ttd_num[ttd_valid.index[-2]]) / 60.0
                    if prev_ttd > 0:
                        pct = ((latest_ttd_min - prev_ttd) / prev_ttd) * 100
                        # Higher TTD = improved
                        if pct > 1:
                            ttd_trend = f"▲ {abs(pct):.1f}%"
                        elif pct < -1:
                            ttd_trend = f"▼ {abs(pct):.1f}%"

        # --- KPI 5: Latest 2-min Recovery Gap (runs ≥60 min) ---
        # Gap = last HR at stop − HR after 2 min. Higher = better recovery.
        rhr_val = "—"
        rhr_color = "#94a3b8"
        rhr_label = ""
        rhr_trend = ""  # higher gap = better (toward build)
        if not qruns.empty and "recovery_hr" in qruns.columns:
            rhr_num = pd.to_numeric(qruns["recovery_hr"], errors="coerce")
            rhr_valid = qruns[rhr_num.notna() & (rhr_num > 0)]
            if not rhr_valid.empty:
                latest_rhr = float(rhr_num[rhr_valid.index[-1]])
                rhr_val = f"{latest_rhr:.0f} bpm"
                if latest_rhr > 60:
                    rhr_color = "#0B7A3E"; rhr_label = "Elite"
                elif latest_rhr >= 50:
                    rhr_color = "#1FAF5A"; rhr_label = "Excellent"
                elif latest_rhr >= 40:
                    rhr_color = "#9BE15D"; rhr_label = "Good"
                elif latest_rhr >= 30:
                    rhr_color = "#FFD166"; rhr_label = "Average"
                elif latest_rhr >= 22:
                    rhr_color = "#F28C28"; rhr_label = "Below Avg"
                else:
                    rhr_color = "#D62828"; rhr_label = "Poor"
                # Trend: latest vs previous — higher gap = improved
                if len(rhr_valid) >= 2:
                    prev_rhr = float(rhr_num[rhr_valid.index[-2]])
                    if prev_rhr > 0:
                        pct = ((latest_rhr - prev_rhr) / prev_rhr) * 100
                        if pct > 1:
                            rhr_trend = f"▲ {abs(pct):.1f}%"
                        elif pct < -1:
                            rhr_trend = f"▼ {abs(pct):.1f}%"

        # --- KPI 6: Latest RPE (runs ≥60 min) ---
        rpe_val = "—"
        rpe_color = "#4ade80"
        rpe_trend = ""  # lower RPE = better (toward build)
        if not qruns.empty and ("rpe_h1" in qruns.columns or "rpe_h2" in qruns.columns):
            rpe1 = pd.to_numeric(qruns.get("rpe_h1", pd.Series(dtype=float)), errors="coerce")
            rpe2 = pd.to_numeric(qruns.get("rpe_h2", pd.Series(dtype=float)), errors="coerce")
            rpe_avg = (rpe1.fillna(rpe2) + rpe2.fillna(rpe1)) / 2.0
            rpe_valid = qruns[rpe_avg.notna() & (rpe_avg > 0)]
            if not rpe_valid.empty:
                latest_rpe = float(rpe_avg[rpe_valid.index[-1]])
                rpe_val = f"{latest_rpe:.1f}"
                if latest_rpe <= 3:
                    rpe_color = "#4ade80"
                elif latest_rpe <= 6:
                    rpe_color = "#facc15"
                else:
                    rpe_color = "#ff6b6b"
                # Trend: latest vs previous session RPE
                if len(rpe_valid) >= 2:
                    prev_rpe = float(rpe_avg[rpe_valid.index[-2]])
                    if prev_rpe > 0:
                        pct = ((latest_rpe - prev_rpe) / prev_rpe) * 100
                        # Lower RPE = improved (invert sign)
                        if pct < -1:
                            rpe_trend = f"▲ {abs(pct):.1f}%"
                        elif pct > 1:
                            rpe_trend = f"▼ {abs(pct):.1f}%"

        # Build Recovery HR label suffix
        rhr_suffix = f" {rhr_label}" if rhr_label else ""
        rhr_display = ui.TagList(rhr_val, ui.tags.span(rhr_suffix, style=f"font-size:11px; font-weight:600; margin-left:4px;")) if rhr_label else rhr_val

        return ui.layout_columns(
            _kpi_card("4wk Run EF Var", ef_var_val, "chart-line", ef_var_color, "ef_var", subtitle=_norm_pwr_sub, trend=ef_var_trend),
            _kpi_card("Avg Run AD%", avg_dec_val, "arrow-trend-up", avg_dec_color, "avg_dec", subtitle=_pace_sub, trend=avg_dec_trend),
            _kpi_card("AeT / FTP", aet_ftp_val, "bolt", aet_ftp_color, "aet_ftp", subtitle=aet_ftp_sub, trend=aet_ftp_trend),
            _kpi_card("Time to Drift", ttd_val, "clock", ttd_color, "ttd", trend=ttd_trend),
            _kpi_card("2min Recovery Gap", rhr_display, "heart-pulse", rhr_color, "rhr", trend=rhr_trend),
            _kpi_card("Latest RPE", rpe_val, "gauge-high", rpe_color, "rpe", trend=rpe_trend),
            col_widths=[2, 2, 2, 2, 2, 2],
        )

