    @reactive.Effect
    @reactive.event(input.kpi_info_click)
    def _kpi_info_notify():
        card_id = input.kpi_info_click()
        if card_id not in _KPI_INFO:
            return
        # Toggle: if same card clicked again, close it
        with reactive.isolate():
            currently_open = _kpi_notif_open()
        if currently_open == card_id:
            ui.notification_remove("kpi_info")
            _kpi_notif_open.set("")
            return
        # Close any existing KPI notification, then show new one
        if currently_open:
            ui.notification_remove("kpi_info")
        title, body = _KPI_INFO[card_id]
        ui.notification_show(
            ui.TagList(
                ui.tags.strong(title, style="display:block; margin-bottom:6px; font-size:13px;"),
                ui.tags.div(body, style="white-space:pre-line; font-size:12px; line-height:1.5;"),
            ),
            duration=None,
            type="default",
            id="kpi_info",
        )
        _kpi_notif_open.set(card_id)

    @output
    @render.ui
    def compare_charts():
        hist = compare_filtered()
        req(not hist.empty)

        go = _get_plotly_go()

        # Already pre-sorted by _dt with _mode_lower from compare_filtered()
        hist_sorted = hist
        ef_num = pd.to_numeric(hist_sorted["ef"], errors="coerce") if "ef" in hist_sorted.columns else pd.Series(dtype=float)
        dec_num = pd.to_numeric(hist_sorted["decoupling_pct"], errors="coerce") if "decoupling_pct" in hist_sorted.columns else pd.Series(dtype=float)

        _chart_layout = dict(
            height=340,
            margin=dict(l=10, r=10, t=10, b=10),
            paper_bgcolor="rgba(0,0,0,0)",
            plot_bgcolor="rgba(16,16,16,0.8)",
            font=dict(family="Roboto Mono, JetBrains Mono, monospace", color="rgba(255,255,255,0.85)"),
            xaxis=dict(gridcolor="rgba(255,255,255,0.05)"),
            yaxis=dict(gridcolor="rgba(255,255,255,0.05)"),
        )

        # --- Workout-type icon mapping for trend charts ---
        _MODE_MARKER = {
            "run": {"symbol": "circle", "label": "\U0001f3c3 Run"},
            "bike": {"symbol": "square", "label": "\U0001f6b4 Bike"},
            "erg": {"symbol": "diamond", "label": "\U0001f6a3 Row Erg"},
            "ski": {"symbol": "hexagram", "label": "\u26f7\ufe0f Ski Erg"},
            "stairmaster": {"symbol": "triangle-up", "label": "\U0001fa9c Stair"},
        }
        _MODE_COLOR_TINT = {
            "run": "#00FFFF",
            "bike": "#FFD700",
            "erg": "#2ECC40",
            "ski": "#E040FB",
            "stairmaster": "#FF851B",
        }
        _mode_col = hist_sorted["_mode_lower"] if "_mode_lower" in hist_sorted.columns else pd.Series("run", index=hist_sorted.index)
        _unique_modes = sorted(_mode_col.unique())

        # --- Pre-compute session detail arrays for hover tooltips ---
        def _fmt_session_dt(row):
            iso = row.get("start_time_iso", "")
            d = row.get("date", "")
            if iso and iso != "nan" and len(str(iso)) > 10:
                try:
                    _ts = pd.Timestamp(iso)
                    return _ts.strftime("%Y-%m-%d %I:%M %p")
                except Exception:
                    pass
            return str(d) if d and str(d) != "nan" else "—"
        _h_date = hist_sorted.apply(_fmt_session_dt, axis=1)
        _h_total_min = pd.to_numeric(hist_sorted.get("total_minutes", pd.Series(dtype=float)), errors="coerce")
        _h_dur_str = _h_total_min.apply(lambda m: f"{int(m // 60)}h {int(m % 60):02d}m" if pd.notna(m) and m >= 60 else (f"{int(m)}m" if pd.notna(m) else "—"))
        _h_avg_hr = pd.to_numeric(hist_sorted.get("avg_hr", pd.Series(dtype=float)), errors="coerce")
        _h_avg_hr_str = _h_avg_hr.apply(lambda v: f"{int(v)} bpm" if pd.notna(v) else "—")
        _h_avg_pw = pd.to_numeric(hist_sorted.get("avg_power_w", pd.Series(dtype=float)), errors="coerce")
        _h_avg_pw_str = _h_avg_pw.apply(lambda v: f"{int(v)} W" if pd.notna(v) and v > 0 else "—")
        _h_avg_spd = pd.to_numeric(hist_sorted.get("avg_speed_kph", pd.Series(dtype=float)), errors="coerce")
        def _spd_to_pace(kph):
            if pd.isna(kph) or kph <= 0:
                return "—"
            sec_per_km = 3600.0 / kph
            m, s = divmod(int(sec_per_km), 60)
            return f"{m}:{s:02d} /km"
        _h_pace_str = _h_avg_spd.apply(_spd_to_pace)
        # Combine pace and power into a single "output" string
        _h_output_str = pd.Series("", index=hist_sorted.index)
        for _idx in hist_sorted.index:
            pw = _h_avg_pw_str.loc[_idx]
            pace = _h_pace_str.loc[_idx]
            if pw != "—" and pace != "—":
                _h_output_str.loc[_idx] = f"{pace} · {pw}"
            elif pw != "—":
                _h_output_str.loc[_idx] = pw
            elif pace != "—":
                _h_output_str.loc[_idx] = pace
            else:
                _h_output_str.loc[_idx] = "—"

        # Base customdata: [date, duration, avg_hr, output(pace/power)]
        _base_cd = np.column_stack([_h_date.values, _h_dur_str.values, _h_avg_hr_str.values, _h_output_str.values])

        def _add_mode_traces(fig, x_col, y_series, base_color, name_prefix, hover_fmt, y_valid_mask=None, extra_customdata=None, extra_hover_lines=""):
            """Add per-mode line+marker traces (each mode connects only to itself)."""
            if y_valid_mask is None:
                y_valid_mask = y_series.notna()
            ok = y_valid_mask
            # Per-mode: connecting line + markers (each activity type is its own trace)
            for m in _unique_modes:
                info = _MODE_MARKER.get(m, {"symbol": "star", "label": m.title()})
                m_color = _MODE_COLOR_TINT.get(m, base_color)
                m_mask = ok & (_mode_col == m)
                if not m_mask.any():
                    continue
                # Build customdata for this subset
                cd = _base_cd[m_mask]
                if extra_customdata is not None:
                    cd = np.column_stack([cd, extra_customdata[m_mask]])
                ht = (
                    f"<b>{info['label']}: {hover_fmt}</b><br>"
                    f"Date: %{{customdata[0]}}<br>"
                    f"Duration: %{{customdata[1]}}<br>"
                    f"Avg HR: %{{customdata[2]}}<br>"
                    f"Output: %{{customdata[3]}}"
                    f"{extra_hover_lines}"
                    f"<extra></extra>"
                )
                fig.add_trace(go.Scatter(
                    x=hist_sorted.loc[m_mask, x_col],
                    y=y_series[m_mask],
                    mode="lines+markers",
                    name=info["label"],
                    line=dict(color=m_color, width=1.5),
                    opacity=0.8,
                    marker=dict(
                        symbol=info["symbol"],
                        size=9,
                        color=m_color,
                        line=dict(width=1, color="rgba(255,255,255,0.4)"),
                    ),
                    customdata=cd,
                    hovertemplate=ht,
                    legendgroup=m,
                ))

        def _add_zones(fig, zones):
            """Add horizontal colored zone bands to a chart (behind data).
            zones: list of (y0, y1, color_rgba, label) tuples.
            """
            for y0, y1, color, label in zones:
                fig.add_hrect(y0=y0, y1=y1, fillcolor=color, line_width=0,
                              layer="below", annotation_text=label,
                              annotation_position="top left",
                              annotation=dict(font_size=9, font_color="rgba(255,255,255,0.35)"))

        # --- Efficiency Factor trend ---
        fig_ef = go.Figure()
        _add_mode_traces(fig_ef, "_dt", ef_num, COLOR_EF, "EF", "%{y:.3f}")
        # EF zones: higher = better. Use data range to set sensible bounds.
        _ef_clean = ef_num.dropna()
        if not _ef_clean.empty:
            _ef_lo = float(_ef_clean.min()) * 0.95
            _ef_hi = float(_ef_clean.max()) * 1.05
            _ef_mid = (_ef_lo + _ef_hi) / 2.0
            _add_zones(fig_ef, [
                (_ef_lo, _ef_mid, "rgba(255,65,54,0.07)", "Lower EF"),      # red zone — below median
                (_ef_mid, _ef_hi, "rgba(74,222,128,0.07)", "Higher EF"),     # green zone — above median
            ])
        # Zoom y-axis to data range
        if not _ef_clean.empty:
            fig_ef.update_layout(yaxis_range=[_ef_lo, _ef_hi])
        fig_ef.update_layout(xaxis_title="Date", yaxis_title="Efficiency Factor (EF)",
                             legend=dict(x=0.01, y=0.99, bgcolor="rgba(0,0,0,0.5)"), **_chart_layout)

        # --- Aerobic Decoupling trend ---
        fig_dec = go.Figure()
        # AD zones: <0% purple (negative coupling), 0–3% green, 3–5% yellow, >5% red
        _add_zones(fig_dec, [
            (-10, 0,  "rgba(168,85,247,0.10)", "Negative"),    # purple — negative decoupling
            (0,   3,  "rgba(74,222,128,0.10)", "Coupled"),     # green — well coupled
            (3,   5,  "rgba(250,204,21,0.10)", "Moderate"),    # yellow — moderate drift
            (5,   25, "rgba(255,65,54,0.10)",  "Decoupled"),   # red — significant drift
        ])
        _add_mode_traces(fig_dec, "_dt", dec_num, COLOR_ADAPTING, "Decoupling %", "%{y:.1f}%")
        # Zoom y-axis to data range
        _dec_clean = dec_num.dropna()
        if not _dec_clean.empty:
            _dec_lo = min(float(_dec_clean.min()) - 1, -1)
            _dec_hi = max(float(_dec_clean.max()) + 1, 6)
            fig_dec.update_layout(yaxis_range=[_dec_lo, _dec_hi])
        fig_dec.update_layout(xaxis_title="Date", yaxis_title="Aerobic Decoupling (%)",
                              legend=dict(x=0.01, y=0.99, bgcolor="rgba(0,0,0,0.5)"), **_chart_layout)

        # Recovery HR after 2 min trend chart
        rhr_num = pd.to_numeric(hist_sorted.get("recovery_hr", pd.Series(dtype=float)), errors="coerce")
        rhr_valid = rhr_num.notna() & (rhr_num > 0)
        # Tooltip descriptions for each trend chart
        _TIP_EF = (
            "Tracks Efficiency Factor (speed ÷ heart rate) over time. "
            "Rising EF = improving aerobic fitness. "
            "Zones: 🟥 Below median · 🟩 Above median."
        )
        _TIP_AD = (
            "Aerobic Decoupling % — HR drift relative to pace/power (2nd half vs 1st half). "
            "Lower = stronger aerobic base. "
            "Zones: 🟪 <0% negative · 🟩 0–3% coupled · 🟨 3–5% moderate · 🟥 >5% decoupled."
        )
        _TIP_RHR = (
            "2-min Recovery Gap (Last HR − HR after 2 min), auto from Garmin FIT. "
            "Larger gap = better recovery. "
            "Zones: 🟥 <22 poor · 🟧 22–30 below avg · 🟨 30–40 avg · 🟩 40–60 good/excellent · 🟩 >60 elite."
        )
        _TIP_TTD = (
            "Time-to-Drift — minutes before cardiac drift begins. "
            "Longer = stronger endurance. "
            "Zones: 🟥 <60m poor · 🟨 60–120m moderate · 🟩 >120m strong."
        )
        _TIP_MA = (
            "Overlay multiple wellness and performance metrics on one timeline. "
            "Use the sidebar switches to toggle: Whoop/Garmin HRV, resting HR, strain, sleep, RPE, temperature, hydration, and nutrition. "
            "Dual Y-axes appear automatically when exactly 2 metrics of different scales are selected."
        )

        # Collect all trend chart panels for a single collapsible accordion
        _trend_panels = [
            ui.accordion_panel("Efficiency Factor Trend", _render_plotly_card("Efficiency Factor Trend", fig_ef, full_screen=True, static=True, tooltip=_TIP_EF)),
            ui.accordion_panel("Aerobic Decoupling Trend", _render_plotly_card("Aerobic Decoupling Trend", fig_dec, full_screen=True, static=True, tooltip=_TIP_AD)),
        ]
        if rhr_valid.any():
            fig_rhr = go.Figure()
            # Recovery Gap zones: higher drop = better recovery
            _add_zones(fig_rhr, [
                (0,  22, "rgba(255,65,54,0.10)",   "Poor"),         # red
                (22, 30, "rgba(242,140,40,0.10)",  "Below Avg"),    # orange
                (30, 40, "rgba(250,204,21,0.10)",  "Average"),      # yellow
                (40, 50, "rgba(155,225,93,0.10)",  "Good"),         # light green
                (50, 60, "rgba(31,175,90,0.10)",   "Excellent"),    # green
                (60, 100,"rgba(11,122,62,0.10)",   "Elite"),        # dark green
            ])
            # Extra customdata: last HR and recovery HR after 2 min
            _rhr_last = pd.to_numeric(hist_sorted.get("last_hr_bpm", pd.Series(dtype=float)), errors="coerce")
            _rhr_2min = pd.to_numeric(hist_sorted.get("recovery_hr_2min_bpm", pd.Series(dtype=float)), errors="coerce")
            _rhr_last_str = _rhr_last.apply(lambda v: f"{int(v)} bpm" if pd.notna(v) and v > 0 else "—").values
            _rhr_2min_str = _rhr_2min.apply(lambda v: f"{int(v)} bpm" if pd.notna(v) and v > 0 else "—").values
            _rhr_extra_cd = np.column_stack([_rhr_last_str, _rhr_2min_str])
            _rhr_extra_hover = "<br>Last HR: %{customdata[4]}<br>HR after 2min: %{customdata[5]}"
            _add_mode_traces(fig_rhr, "_dt", rhr_num, COLOR_HR, "2min Gap", "%{y:.0f} bpm", y_valid_mask=rhr_valid, extra_customdata=_rhr_extra_cd, extra_hover_lines=_rhr_extra_hover)
            # Zoom y-axis to data range
            _rhr_clean = rhr_num[rhr_valid]
            if not _rhr_clean.empty:
                _rhr_lo = max(float(_rhr_clean.min()) - 5, 0)
                _rhr_hi = float(_rhr_clean.max()) + 5
                fig_rhr.update_layout(yaxis_range=[_rhr_lo, _rhr_hi])
            fig_rhr.update_layout(xaxis_title="Date", yaxis_title="Recovery Gap (bpm)",
                                  legend=dict(x=0.01, y=0.99, bgcolor="rgba(0,0,0,0.5)"), **_chart_layout)
            _trend_panels.append(
                ui.accordion_panel("Recovery Heart Rate after 2 min Trend", _render_plotly_card("Recovery Heart Rate after 2 min Trend", fig_rhr, full_screen=True, static=True, tooltip=_TIP_RHR)),
            )

        # Time-to-Drift trend chart (only if data exists)
        ttd_num = pd.to_numeric(hist_sorted.get("time_to_drift_sec", pd.Series(dtype=float)), errors="coerce")
        ttd_valid = ttd_num.notna() & (ttd_num > 0)
        if ttd_valid.any():
            ttd_min = ttd_num / 60.0  # convert sec to min
            fig_ttd = go.Figure()
            # TTD zones: <60 red, 60-120 yellow, >120 green (minutes)
            _add_zones(fig_ttd, [
                (0,   60,  "rgba(255,65,54,0.08)",   "Poor (<60m)"),
                (60,  120, "rgba(250,204,21,0.08)",   "Moderate"),
                (120, 300, "rgba(74,222,128,0.08)",   "Strong (>120m)"),
            ])
            _add_mode_traces(fig_ttd, "_dt", ttd_min, COLOR_SPEED, "Time to Drift", "%{y:.1f} min", y_valid_mask=ttd_valid)
            # Zoom y-axis to data range
            _ttd_clean = ttd_min[ttd_valid]
            if not _ttd_clean.empty:
                _ttd_lo = max(float(_ttd_clean.min()) - 10, 0)
                _ttd_hi = float(_ttd_clean.max()) + 10
                fig_ttd.update_layout(yaxis_range=[_ttd_lo, _ttd_hi])
            fig_ttd.update_layout(xaxis_title="Date", yaxis_title="Time to Drift (min)",
                                  legend=dict(x=0.01, y=0.99, bgcolor="rgba(0,0,0,0.5)"), **_chart_layout)
            _trend_panels.append(
                ui.accordion_panel("Time-to-Drift Trend", _render_plotly_card("Time-to-Drift Trend", fig_ttd, full_screen=True, static=True, tooltip=_TIP_TTD)),
            )

        # Reactive multi-attribute trend chart — driven by sidebar switches
        # Each spec: (col_or_fn, label, color, dash, marker_symbol, hover_fmt, hover_unit, switch_id)
        _ma_specs = [
            ("whoop_score",       "Whoop Score",   "#a855f7", "solid",   "circle",       ":.0f", "",     "trend_whoop_score"),
            ("whoop_hrv_ms",      "HRV (Whoop)",   "#38bdf8", "solid",   "hexagram",     ":.0f", " ms",  "trend_whoop_hrv"),
            ("whoop_resting_hr",  "RHR (Whoop)",   "#fb7185", "solid",   "bowtie",       ":.0f", " bpm", "trend_whoop_rhr"),
            ("whoop_strain",      "Strain",        "#f97316", "solid",   "cross",        ":.1f", "",     "trend_whoop_strain"),
            ("whoop_sleep_hours", "Sleep Hours",   "#4ade80", "solid",   "pentagon",     ":.1f", " h",   "trend_sleep_hours"),
            ("whoop_sleep_perf",  "Sleep Perf %",  "#c084fc", "dash",    "triangle-down",":.0f", "%",    "trend_sleep_perf"),
            ("_fluid_l15",        "Fluid (L/15m)", "#3b82f6", "dash",    "square",       ":.2f", " L",   "trend_fluid"),
            ("_carb_g15",         "Carb (g/15m)",  COLOR_CADENCE, "dot", "diamond",      ":.1f", " g",   "trend_carb"),
            ("_temp_avg",         "Temp (°C)",     COLOR_ADAPTING, "dashdot", "triangle-up",":.1f","°C",  "trend_temp"),
            ("_rpe_avg",          "RPE",           COLOR_HR, "longdash", "star",          ":.1f", "",     "trend_rpe"),
            ("garmin_hrv_ms",     "HRV (Garmin)",  "#22d3ee", "dot",     "star-triangle-up", ":.0f", " ms",  "trend_garmin_hrv"),
            ("garmin_resting_hr", "RHR (Garmin)",  "#f472b6", "dashdot", "bowtie",       ":.0f", " bpm", "trend_garmin_rhr"),
        ]

        # Precompute temp and RPE averages as local Series (avoid mutating shared DataFrame)
        t_min_num = pd.to_numeric(hist_sorted.get("temp_min_c", pd.Series(dtype=float)), errors="coerce")
        t_max_num = pd.to_numeric(hist_sorted.get("temp_max_c", pd.Series(dtype=float)), errors="coerce")
        _temp_avg = (t_min_num.fillna(t_max_num) + t_max_num.fillna(t_min_num)) / 2.0
        rpe1 = pd.to_numeric(hist_sorted.get("rpe_h1", pd.Series(dtype=float)), errors="coerce")
        rpe2 = pd.to_numeric(hist_sorted.get("rpe_h2", pd.Series(dtype=float)), errors="coerce")
        _rpe_avg = (rpe1.fillna(rpe2) + rpe2.fillna(rpe1)) / 2.0
        # Fluid: convert total ml → L per 15 min
        _fluid_ml = pd.to_numeric(hist_sorted.get("fluid_intake_ml", pd.Series(dtype=float)), errors="coerce")
        _total_min = pd.to_numeric(hist_sorted.get("total_minutes", pd.Series(dtype=float)), errors="coerce")
        _fluid_l15 = (_fluid_ml / 1000.0) / (_total_min / 15.0)
        _fluid_l15 = _fluid_l15.replace([np.inf, -np.inf], np.nan)
        # Carb: convert total g → g per 15 min
        _carb_g = pd.to_numeric(hist_sorted.get("carb_intake_g", pd.Series(dtype=float)), errors="coerce")
        _carb_g15 = _carb_g / (_total_min / 15.0)
        _carb_g15 = _carb_g15.replace([np.inf, -np.inf], np.nan)
        # Local lookup for derived columns used in multi-attribute specs
        _derived_cols = {"_temp_avg": _temp_avg, "_rpe_avg": _rpe_avg, "_fluid_l15": _fluid_l15, "_carb_g15": _carb_g15}

        # Read sidebar switch states to decide which traces to show
        active_specs = []
        for spec in _ma_specs:
            switch_id = spec[7]
            try:
                if input[switch_id]():
                    active_specs.append(spec)
            except Exception:
                pass

        if active_specs:
            fig_ma = go.Figure()
            for col, label, color, dash, marker_sym, hfmt, hunit, _sid in active_specs:
                # Use derived local Series for computed columns, else read from DataFrame
                if col in _derived_cols:
                    raw_num = _derived_cols[col]
                else:
                    raw_num = pd.to_numeric(hist_sorted.get(col, pd.Series(dtype=float)), errors="coerce")
                ok = raw_num.notna() & (raw_num > 0) if col not in ("_temp_avg",) else raw_num.notna()
                if ok.any():
                    fig_ma.add_trace(go.Scatter(
                        x=hist_sorted.loc[ok, "_dt"], y=raw_num[ok],
                        mode="lines+markers", name=label,
                        line=dict(color=color, dash=dash, width=2.5),
                        marker=dict(size=7, symbol=marker_sym),
                        hovertemplate=f"{label}: %{{y{hfmt}}}{hunit}<extra></extra>",
                    ))

            # Use dual y-axes if exactly 2 different-scale metrics are active
            if len(active_specs) == 2:
                fig_ma.data[0].update(yaxis="y")
                if len(fig_ma.data) > 1:
                    fig_ma.data[-1].update(yaxis="y2")
                fig_ma.update_layout(
                    yaxis=dict(title=active_specs[0][1], gridcolor="rgba(255,255,255,0.05)"),
                    yaxis2=dict(title=active_specs[-1][1], overlaying="y", side="right",
                                gridcolor="rgba(255,255,255,0.05)"),
                )
            else:
                y_title = active_specs[0][1] if len(active_specs) == 1 else "Value"
                fig_ma.update_layout(yaxis=dict(title=y_title, gridcolor="rgba(255,255,255,0.05)")),

            fig_ma.update_layout(
                xaxis_title="Date",
                **_chart_layout,
                legend=dict(x=0.01, y=0.99, bgcolor="rgba(0,0,0,0.5)"),
            )
            _trend_panels.append(
                ui.accordion_panel("Trend Metrics", _render_plotly_card("Trend Metrics", fig_ma, full_screen=True, static=True, tooltip=_TIP_MA)),
            )

        # Wrap all trend chart panels in a single collapsible accordion, defaulted open
        return ui.accordion(
            *_trend_panels,
            id="acc_trend_charts",
            open=True,
        )

    @output
    @render.ui
    def compare_table():
        hist = compare_filtered()
        req(not hist.empty)

        # --- Emoji maps ---
        _MODE_EMOJI = {"run": "\U0001f3c3 Run", "bike": "\U0001f6b4 Bike", "erg": "\U0001f6a3 Row Erg", "ski": "\u26f7\ufe0f Ski Erg", "stairmaster": "\U0001fa9c Stairmaster"}
        _TERRAIN_EMOJI = {"flat": "\U0001f3dc\ufe0f Flat", "rolling": "\U0001f30a Rolling", "hilly": "\u26f0\ufe0f Hilly", "mountainous": "\U0001f3d4\ufe0f Mountainous", "unknown": "\u2753 Unknown"}

        # --- Short status labels ---
        def _short_status(s):
            sl = (s or "").strip().lower()
            if "elite" in sl:
                return "Elite"
            if "adapting" in sl:
                return "Adapting"
            if "negative" in sl and ("drift" in sl or "decoupling" in sl):
                return "Negative Drift"
            if "needs" in sl and "lessen" in sl:
                return "Needs Lessening"
            if "overtraining" in sl or "flush" in sl:
                return "Overtraining Warning (50% flush week needed)"
            if "unreliable" in sl or "low validity" in sl:
                return "Unreliable"
            return s[:30] if s else "\u2014"

        # --- AD% color: same logic as status but based on raw value ---
        def _ad_color(ad_val, status_str):
            """Color AD% using the status classification."""
            color = status_color_for(status_str)
            return color

        # --- Drift Driver color ---
        _DRIVER_COLORS = {
            "hr-driven": COLOR_HR,           # red
            "output-driven": COLOR_POWER,    # gold
            "balanced": COLOR_EF,            # blue
        }
        def _driver_color(driver):
            dl = (driver or "").strip().lower()
            for k, c in _DRIVER_COLORS.items():
                if k in dl:
                    return c
            return "#94a3b8"  # slate default

        df = hist.copy()

        # Philippine Date & Time (UTC+8) — format: Jan 1, 2026 06:48 AM
        def _fmt_pht(ts):
            try:
                if pd.isna(ts):
                    return ""
                return f"{ts.strftime('%b')} {ts.day}, {ts.strftime('%Y %I:%M %p')}"
            except Exception:
                return ""

        if "start_time_iso" in df.columns:
            pht = pd.to_datetime(df["start_time_iso"], errors="coerce", utc=True)
            pht = pht.dt.tz_convert("Asia/Manila")
            df["Date & Time"] = pht.apply(_fmt_pht)
            df["_sort_dt"] = pht.apply(lambda ts: ts.isoformat() if pd.notna(ts) else "")
            fallback = df["Date & Time"] == ""
            if fallback.any() and "date" in df.columns:
                df.loc[fallback, "Date & Time"] = df.loc[fallback, "date"].astype(str)
                df.loc[fallback, "_sort_dt"] = df.loc[fallback, "date"].astype(str)
        elif "date" in df.columns:
            df["Date & Time"] = df["date"].astype(str)
            df["_sort_dt"] = df["date"].astype(str)
        else:
            df["Date & Time"] = ""
            df["_sort_dt"] = ""

        # Mode with emoji (uses pre-computed _mode_lower from compare_filtered)
        df["Mode"] = df["_mode_lower"].map(
            lambda m: _MODE_EMOJI.get(m, m.title())
        ) if "_mode_lower" in df.columns else ""

        # Terrain with emoji
        df["Terrain"] = df["terrain"].astype(str).str.strip().str.lower().map(
            lambda t: _TERRAIN_EMOJI.get(t, t.title())
        ) if "terrain" in df.columns else ""

        # Raw status for color lookup
        df["_raw_status"] = df["status"].astype(str) if "status" in df.columns else ""
        df["Status"] = df["_raw_status"].apply(_short_status)

        # Numeric columns
        for src, dst, decimals in [
            ("decoupling_pct", "AD%", 1), ("ef", "EF", 3),
            ("warmup_min", "Warm-up", 0), ("avg_output", "Power", 1),
            ("avg_hr", "Avg HR", 0), ("total_minutes", "Total Minutes", 1),
            ("distance_km", "Distance", 2), ("recovery_hr", "2min Gap", 0),
            ("whoop_score", "Whoop", 0),
            ("garmin_hrv_ms", "HRV (ms)", 0), ("garmin_resting_hr", "G.Rest HR", 0),
        ]:
            df[dst] = pd.to_numeric(df[src], errors="coerce").round(decimals) if src in df.columns else float("nan")

        # Fluid: convert total ml → L per 15 min for display
        _fl_ml = pd.to_numeric(df.get("fluid_intake_ml", pd.Series(dtype=float)), errors="coerce")
        _fl_tm = pd.to_numeric(df.get("total_minutes", pd.Series(dtype=float)), errors="coerce")
        _fl_l15 = (_fl_ml / 1000.0) / (_fl_tm / 15.0)
        df["Fluid (L/15m)"] = _fl_l15.replace([np.inf, -np.inf], np.nan).round(2)

        # Carb: convert total g → g per 15 min for display
        _cb_g = pd.to_numeric(df.get("carb_intake_g", pd.Series(dtype=float)), errors="coerce")
        _cb_g15 = _cb_g / (_fl_tm / 15.0)
        df["Carb (g/15m)"] = _cb_g15.replace([np.inf, -np.inf], np.nan).round(1)

        # Temperature — vectorized (avoids slow row-by-row .apply)
        _t_min = pd.to_numeric(df.get("temp_min_c", pd.Series(dtype=float)), errors="coerce")
        _t_max = pd.to_numeric(df.get("temp_max_c", pd.Series(dtype=float)), errors="coerce")
        _has_both = _t_min.notna() & _t_max.notna()
        _has_min = _t_min.notna() & _t_max.isna()
        _has_max = _t_min.isna() & _t_max.notna()
        df["Temp"] = "\u2014"
        if _has_both.any():
            df.loc[_has_both, "Temp"] = _t_min[_has_both].astype(int).astype(str) + "-" + _t_max[_has_both].astype(int).astype(str) + "\u00b0C"
        if _has_min.any():
            df.loc[_has_min, "Temp"] = _t_min[_has_min].astype(int).astype(str) + "\u00b0C"
        if _has_max.any():
            df.loc[_has_max, "Temp"] = _t_max[_has_max].astype(int).astype(str) + "\u00b0C"

        # Weather from weather_summary
        df["Weather"] = df["weather_summary"].astype(str).apply(
            lambda w: w[:30] if w and w != "nan" else "\u2014"
        ) if "weather_summary" in df.columns else "\u2014"

        # Drift driver
        df["Drift Driver"] = df["drift_driver"].astype(str) if "drift_driver" in df.columns else ""

        show_cols = ["Date & Time", "Mode", "Terrain", "Status", "AD%", "EF",
                     "Warm-up", "Power", "Avg HR", "Total Minutes",
                     "Drift Driver", "Distance", "2min Gap",
                     "Temp", "Weather", "Fluid (L/15m)", "Carb (g/15m)", "Whoop",
                     "HRV (ms)", "G.Rest HR"]

        # --- Build HTML table rows with delete checkboxes ---
        html_rows = []
        iso_keys = []  # track start_time_iso for delete
        for idx_i, (_, r) in enumerate(df.iterrows()):
            iso_val = str(r.get("start_time_iso", "")) if "start_time_iso" in df.columns else ""
            iso_keys.append(iso_val)
            cb = f'<td><input type="checkbox" class="mbp-del-cb" data-iso="{iso_val}" style="cursor:pointer; accent-color:{COLOR_HR};"></td>'
            cells = [cb]
            for c in show_cols:
                v = r[c]
                is_nan = isinstance(v, float) and (pd.isna(v) or not np.isfinite(v))
                if c == "Date & Time":
                    sort_key = str(r.get("_sort_dt", ""))
                    cells.append(
                        f'<td data-sort="{sort_key}">'
                        f'<a href="#" class="mbp-session-link" data-iso="{iso_val}" '
                        f'style="color:#39CCCC; text-decoration:none; cursor:pointer;" '
                        f'onclick="mbpLoadSession(this.dataset.iso); return false;">{v}</a>'
                        f'</td>'
                    )
                elif c == "Status":
                    color = status_color_for(r["_raw_status"])
                    cells.append(f'<td><span style="color:{color}; font-weight:700;">{v}</span></td>')
                elif c == "AD%":
                    if is_nan:
                        cells.append("<td>\u2014</td>")
                    else:
                        color = status_color_for(r["_raw_status"])
                        cells.append(f'<td><span style="color:{color}; font-weight:600;">{v:.1f}%</span></td>')
                elif c == "Drift Driver":
                    dc = _driver_color(str(v))
                    txt = str(v) if v and str(v) != "nan" else "\u2014"
                    cells.append(f'<td><span style="color:{dc}; font-weight:600;">{txt}</span></td>')
                elif c == "Warm-up":
                    cells.append(f"<td>{int(v)} min</td>" if not is_nan else "<td>\u2014</td>")
                elif c == "2min Gap":
                    cells.append(f"<td>{int(v)} bpm</td>" if (not is_nan and v > 0) else "<td>\u2014</td>")
                elif is_nan:
                    cells.append("<td>\u2014</td>")
                else:
                    cells.append(f"<td>{v}</td>")
            html_rows.append("<tr>" + "".join(cells) + "</tr>")

        header_cells = '<th style="width:30px;">\u2716</th>' + "".join(
            f'<th onclick="mbpSortTable(this)" style="cursor:pointer; user-select:none;">{c} \u2195</th>'
            for c in show_cols
        )
        table_html = (
            '<div style="overflow-x: auto; max-height: 500px; overflow-y: auto;">'
            '<table id="mbpGranularTable" class="dataTable" style="width:100%; border-collapse:collapse; font-size:0.82rem;">'
            f"<thead><tr>{header_cells}</tr></thead>"
            f"<tbody>{''.join(html_rows)}</tbody></table></div>"
        )

        return ui.card(
            ui.card_header(
                ui.div(
                    ui.span(f"Granular Session Data ({len(html_rows)} sessions)"),
                    ui.div(
                        ui.input_action_button(
                            "edit_selected_sessions",
                            ui.TagList(fa.icon_svg("pen-to-square"), " Edit selected"),
                            class_="btn-warning btn-sm",
                            style="margin-right: 6px;",
                        ),
                        ui.input_action_button(
                            "delete_selected_sessions",
                            ui.TagList(fa.icon_svg("trash"), " Delete selected"),
                            class_="btn-danger btn-sm",
                        ),
                        style="display: flex; gap: 4px;",
                    ),
                    style="display: flex; justify-content: space-between; align-items: center;",
                ),
            ),
            ui.HTML(table_html),
            full_screen=True,
        )

    # --- Delete selected sessions ---
    @reactive.Effect
    @reactive.event(input.delete_selected_sessions)
    async def _delete_selected_sessions():
        """Show confirmation modal, then delete selected rows from history."""
        # Use JS to grab checked ISO values, pass via custom message
        js = "Shiny.setInputValue('_del_isos_json', mbpGetSelectedISOs());"
        await session.send_custom_message("eval_js", js)

    @reactive.Effect
    @reactive.event(input._del_isos_json)
    def _confirm_delete_sessions():
        raw = input._del_isos_json()
        if not raw:
            return
        try:
            parsed = json.loads(raw)
            isos = parsed.get("isos", []) if isinstance(parsed, dict) else parsed
        except Exception:
            isos = []
        if not isos:
            ui.notification_show("No sessions selected.", type="warning", duration=3)
            return
        _pending_del_isos.set(isos)
        ui.modal_show(
            ui.modal(
                ui.p(f"Are you sure you want to delete {len(isos)} session(s)? This cannot be undone.",
                     style="font-weight: 600;"),
                ui.layout_columns(
                    ui.input_action_button("confirm_del_yes", "Yes, delete", class_="btn-danger"),
                    ui.input_action_button("confirm_del_no", "Cancel", class_="btn-secondary"),
                    col_widths=[6, 6],
                ),
                title="Delete Sessions?",
                easy_close=True,
            ),
        )

    _pending_del_isos = reactive.Value([])

    @reactive.Effect
    @reactive.event(input.confirm_del_yes)
    async def _execute_delete_sessions():
        ui.modal_remove()
        isos = _pending_del_isos()
        if not isos:
            return
        slug = input.compare_profile()
        req(slug)
        hp = APP_DIR / f"ad_history_{slug}.csv"
        hist = load_history(hp)
        if hist.empty or "start_time_iso" not in hist.columns:
            return
        before = len(hist)
        hist = hist[~hist["start_time_iso"].astype(str).isin(isos)]
        after = len(hist)
        deleted = before - after
        if deleted > 0:
            save_history(hist, hp)
            _notify_athlete_tracker()  # update MBP Athletes.xlsx immediately
            await _persist_to_browser(slug)
            clear_history_cache()
            history_trigger.set(history_trigger() + 1)
            ui.notification_show(f"\u2705 Deleted {deleted} session(s).", type="message", duration=4)
            # Also delete stored FIT files locally + on api_server (best-effort)
            for _del_iso in isos:
                try:
                    _del_path = _fit_store_path_local(slug, _del_iso)
                    if _del_path.exists():
                        _del_path.unlink()
                except Exception:
                    pass
            try:
                await _fit_api_post("/api/fit/delete", {
                    "athlete_slug": slug,
                    "isos": isos,
                })
            except Exception:
                pass
        else:
            ui.notification_show("No matching sessions found.", type="warning", duration=3)
        _pending_del_isos.set([])

    @reactive.Effect
    @reactive.event(input.confirm_del_no)
    def _cancel_delete_sessions():
        ui.modal_remove()
        _pending_del_isos.set([])

    # --- Reload session from history (click session name in Granular Data) ---
    def _fit_store_path_local(athlete_slug: str, start_time_iso: str) -> Path:
        """Build local filesystem path for a stored FIT file."""
        safe_iso = start_time_iso.replace(":", "-").replace("+", "p")
        return APP_DIR / "fit_store" / athlete_slug / f"{safe_iso}.fit"

    @reactive.Effect
    @reactive.event(input._reload_session_iso)
    async def _reload_session_from_history():
        """Fetch stored FIT and replay full analysis in Session tab."""
        iso = input._reload_session_iso()
        req(iso)
        slug = input.compare_profile()
        req(slug)

        ui.notification_show("Loading session...", type="message", duration=2)

        # Switch to Session tab immediately so user sees it loading
        ui.update_navs("navbar", selected="Sessions")

        # Look up display name from history
        hp = APP_DIR / f"ad_history_{slug}.csv"
        hist = load_history(hp)
        match = hist[hist["start_time_iso"].astype(str) == iso]
        if not match.empty:
            row = match.iloc[0]
            fname = str(row.get("file_name", ""))
            if not fname or fname == "nan":
                fname = f"Session {iso}"
        else:
            fname = f"Session {iso}"

        fbytes = None

        # --- Strategy 1: Read directly from local disk (works in server mode) ---
        if not _IS_PYODIDE:
            # Try athlete's permanent directory first
            fpath = _fit_store_path_local(slug, iso)
            if fpath.exists():
                try:
                    fbytes = fpath.read_bytes()
                except Exception:
                    pass

            # Fallback: try _temp directory (FIT stored on upload but not yet saved)
            if fbytes is None:
                temp_path = _fit_store_path_local("_temp", iso)
                if temp_path.exists():
                    try:
                        fbytes = temp_path.read_bytes()
                    except Exception:
                        pass

            # Fallback: try api_server over HTTP if local file not found
            if fbytes is None:
                try:
                    result = await _fit_api_post("/api/fit/retrieve", {
                        "athlete_slug": slug,
                        "start_time_iso": iso,
                    })
                    if result.get("ok") and result.get("fit_base64"):
                        fbytes = base64.b64decode(result["fit_base64"])
                except Exception:
                    pass  # api_server not running — that's OK

        # --- Strategy 2: Use proxy (Pyodide/Shinylive mode) ---
        else:
            try:
                result = await _fit_api_post("/api/fit/retrieve", {
                    "athlete_slug": slug,
                    "start_time_iso": iso,
                })
                if result.get("ok") and result.get("fit_base64"):
                    fbytes = base64.b64decode(result["fit_base64"])
            except Exception as e:
                ui.notification_show(
                    f"Could not retrieve FIT file from server: {e}",
                    type="error", duration=6,
                )
                return

        if fbytes is None:
            ui.notification_show(
                "FIT file not found for this session. Only sessions saved after this update have stored FIT files.",
                type="warning", duration=6,
            )
            return

        # Pre-populate all saved user-entered data from history
        replay_data = {}
        if not match.empty:
            for col in ["avg_power_w", "rpe_h1", "rpe_h2", "athlete_id",
                         "distance_km", "elev_gain_m", "warmup_min"]:
                try:
                    v = row.get(col, None)
                    if v is not None and str(v).strip().lower() not in ("", "nan", "none"):
                        replay_data[col] = float(v) if col != "athlete_id" else str(v).strip()
                except (ValueError, TypeError):
                    pass
        _replay_session_data.set(replay_data)

        # Pre-set manual power so analysis doesn't block on it
        pw = replay_data.get("avg_power_w", 0)
        if pw and float(pw) > 0:
            _manual_power_stored.set(float(pw))

        # Inject into the reactive pipeline (same mechanism as Garmin download)
        _garmin_fit_data.set((fbytes, f"History: {fname}"))
        ui.notification_show(f"Loaded session: {fname}", type="message", duration=4)

