            try:
                v = row_data.get(col)
                if v is None:
                    return ""
                fv = float(v)
                if pd.isna(fv) or not np.isfinite(fv):
                    return ""
                # Show ints cleanly (no .0)
                if fv == int(fv) and col not in ("distance_km", "rpe_h1", "rpe_h2"):
                    return str(int(fv))
                return str(round(fv, 2))
