    def _get_row_data_for_iso(iso_val, hist_df):
        """Extract a row dict for a specific start_time_iso from a history DataFrame."""
        match = hist_df[hist_df["start_time_iso"].astype(str) == str(iso_val)]
        if match.empty:
            return {}
        row = match.iloc[0]
        d = {}
        for col in hist_df.columns:
            try:
                d[col] = row[col]
            except Exception:
                d[col] = None
        return d

