    @reactive.Calc
    def _tss_parsed():
        """Parse a FIT file for TSS — reuse Analyze tab data or use TSS tab upload."""
        # Prefer TSS tab's own upload if present
        tss_files = input.tss_fit_upload()
        if tss_files and len(tss_files) > 0:
            fp = tss_files[0]
            p = Path(fp["datapath"])
            if p.exists():
                raw = p.read_bytes()
                meta, df = parse_fit_bytes(raw)
                mode = infer_mode(meta, df)
                return meta, df, mode, fp.get("name", "unknown.fit")

        # Fall back to Analyze tab's parsed data
        pd_val = parsed_data()
        if pd_val is not None:
