            return meta, df, mode, fname

        return None

    def _parse_pace_to_mps(pace_str: str) -> float:
        """Convert 'mm:ss' pace per km to m/s speed."""
        try:
            parts = pace_str.strip().split(":")
            mins = int(parts[0])
            secs = int(parts[1]) if len(parts) > 1 else 0
            sec_per_km = mins * 60 + secs
            if sec_per_km <= 0:
                return 0.0
            return 1000.0 / sec_per_km
        except Exception:
            return 0.0

    @reactive.Calc
    def _tss_computed():
        """Compute TSS from parsed FIT data + user threshold inputs."""
        data = _tss_parsed()
        if data is None:
            return {}

        meta, df, mode, fname = data

        # Duration
        if "elapsed_sec" in df.columns:
            dur_vals = pd.to_numeric(df["elapsed_sec"], errors="coerce").dropna()
            duration_sec = float(dur_vals.max() - dur_vals.min()) if len(dur_vals) >= 2 else 0
        elif "timestamp" in df.columns:
            ts = pd.to_datetime(df["timestamp"], errors="coerce").dropna()
            duration_sec = float((ts.max() - ts.min()).total_seconds()) if len(ts) >= 2 else 0
        else:
            duration_sec = 0

        # Extract 1Hz series
        power_1hz = pd.to_numeric(df.get("power_w", pd.Series(dtype=float)), errors="coerce") if "power_w" in df.columns else None
        hr_1hz = pd.to_numeric(df.get("heart_rate_bpm", pd.Series(dtype=float)), errors="coerce") if "heart_rate_bpm" in df.columns else None

        # NGP or avg speed for running
        ngp_mps = 0.0
        avg_speed_mps = 0.0
        if "ngp_speed_mps" in df.columns:
            ngp_vals = pd.to_numeric(df["ngp_speed_mps"], errors="coerce").dropna()
            ngp_mps = float(ngp_vals.mean()) if not ngp_vals.empty else 0.0
        if "speed_mps" in df.columns:
            spd_vals = pd.to_numeric(df["speed_mps"], errors="coerce").dropna()
            spd_vals = spd_vals[spd_vals > 0.3]  # filter standstills
            avg_speed_mps = float(spd_vals.mean()) if not spd_vals.empty else 0.0

        # User thresholds
        ftp_w = 0
        try:
            ftp_w = float(input.tss_ftp_w() or 0)
        except Exception:
            pass

        ftp_pace_mps = _parse_pace_to_mps(input.tss_ftp_pace() or "")

        lthr = 0
        try:
            lthr = float(input.tss_lthr() or 0)
        except Exception:
            pass
        resting_hr = 0
        try:
            resting_hr = float(input.tss_resting_hr() or 0)
        except Exception:
            pass
        max_hr = 0
        try:
            max_hr = float(input.tss_max_hr() or 0)
        except Exception:
            pass

        is_male = True
        try:
            is_male = bool(input.tss_gender_male())
        except Exception:
            pass

        result = auto_compute_tss(
            mode=mode,
            duration_sec=duration_sec,
            power_w_1hz=power_1hz,
            ftp_w=ftp_w,
            ngp_mps=ngp_mps,
            avg_speed_mps=avg_speed_mps,
            ftp_pace_mps=ftp_pace_mps,
            hr_1hz=hr_1hz,
            lthr=lthr,
            resting_hr=resting_hr,
            max_hr=max_hr,
            is_male=is_male,
        )
        result["duration_sec"] = duration_sec
        result["mode"] = mode
        result["fname"] = fname
        return result

