                          layer="below", annotation_text=label,
                          annotation_position="top left",
                          annotation=dict(font_size=9, font_color="rgba(255,255,255,0.35)"))
        # Zero line for TSB
        fig.add_hline(y=0, line=dict(color="rgba(255,255,255,0.2)", width=1, dash="dot"))

        # Zoom y-axis to data range across all 3 traces
        _pmc_lo = min(float(pmc["ctl"].min()), float(pmc["atl"].min()), float(pmc["tsb"].min()))
        _pmc_hi = max(float(pmc["ctl"].max()), float(pmc["atl"].max()), float(pmc["tsb"].max()))
        _pmc_pad = max((_pmc_hi - _pmc_lo) * 0.08, 5)

        fig.update_layout(
            height=400,
            margin=dict(l=10, r=10, t=10, b=10),
            paper_bgcolor="rgba(0,0,0,0)",
