    async def _share_post(endpoint: str, data: dict) -> dict:
        """POST JSON to proxy server for share operations."""
        if _IS_PYODIDE:
            from pyodide.http import pyfetch  # type: ignore
            import json as _json
            url = f"{_proxy_url}{endpoint}"
            resp = await pyfetch(
                url, method="POST",
                headers={"Content-Type": "application/json",
                         "ngrok-skip-browser-warning": "1"},
                body=_json.dumps(data).encode("utf-8"),
            )
            text = await resp.string()
            return _json.loads(text)
        else:
            import requests as _req
            url = f"http://127.0.0.1:9876{endpoint}"
            resp = _req.post(url, json=data, timeout=30)
            return resp.json()

    async def _fit_api_post(endpoint: str, data: dict) -> dict:
        """POST JSON to proxy server for FIT file storage/retrieval."""
        if _IS_PYODIDE:
            from pyodide.http import pyfetch  # type: ignore
            import json as _json
            url = f"{_proxy_url}{endpoint}"
            resp = await pyfetch(
                url, method="POST",
                headers={"Content-Type": "application/json",
                         "ngrok-skip-browser-warning": "1"},
                body=_json.dumps(data).encode("utf-8"),
            )
            text = await resp.string()
            return _json.loads(text)
        else:
            import requests as _req
            url = f"http://127.0.0.1:9876{endpoint}"
            resp = _req.post(url, json=data, timeout=120)
            return resp.json()

    async def _store_fit_on_server(fbytes: bytes, athlete_slug: str, start_iso: str):
        """Store FIT bytes — locally to disk AND to api_server (best-effort)."""
        # Always write to local disk first (instant, no network needed)
        try:
            fpath = _fit_store_path_local(athlete_slug, start_iso)
            fpath.parent.mkdir(parents=True, exist_ok=True)
            fpath.write_bytes(fbytes)
        except Exception:
            pass

        # Also send to api_server over HTTP (for remote/Pyodide access)
        try:
            await _fit_api_post("/api/fit/store", {
                "fit_base64": base64.b64encode(fbytes).decode("ascii"),
                "athlete_slug": athlete_slug,
                "start_time_iso": start_iso,
            })
        except Exception:
            pass  # best-effort — don't fail save if remote storage fails

