    @reactive.Effect
    @reactive.event(input.share_download_server_btn)
    async def _share_download_server():
        """Generate server package ZIP and trigger browser download."""
        import base64 as _b64
        import zipfile as _zf
        import io as _io

        zip_b64 = ""
        if _IS_PYODIDE:
            # Use pre-built bundle from build step
            try:
                from _server_bundle import SERVER_ZIP_B64  # type: ignore
                zip_b64 = SERVER_ZIP_B64
            except ImportError:
                ui.notification_show("Server bundle not available in this build",
                                     type="warning")
                return
        else:
            # Local mode: build ZIP on the fly from actual files
            buf = _io.BytesIO()
            server_dir = APP_DIR
            with _zf.ZipFile(buf, "w", _zf.ZIP_DEFLATED) as zf:
                for fname in ["api_server.py", "garmin_sync.py", "whoop_sync.py"]:
                    fpath = server_dir / fname
                    if fpath.exists():
                        zf.write(str(fpath), f"mbp_server/{fname}")
                zf.writestr("mbp_server/requirements.txt",
                             "starlette\nuvicorn\ngarminconnect>=0.2.0\nrequests\npyngrok\n")
                zf.writestr("mbp_server/README.txt",
                             "Metric Based Phasing — Proxy Server Package\n"
                             "=============================================\n\n"
                             "SETUP:\n"
                             "1. Install Python 3.10+ (https://python.org)\n"
                             "2. pip install -r requirements.txt\n"
                             "3. (Optional) Set MBP_GIST_TOKEN env var for data sharing.\n"
                             "4. (Optional) pip install pyngrok + set NGROK_AUTHTOKEN.\n\n"
                             "RUN:\n"
                             "    python api_server.py\n")
            zip_b64 = _b64.b64encode(buf.getvalue()).decode("ascii")

        # Trigger browser download via JS
        js = (
            f"(function(){{"
            f"var b=atob('{zip_b64}');"
            f"var n=b.length,u=new Uint8Array(n);"
            f"for(var i=0;i<n;i++)u[i]=b.charCodeAt(i);"
            f"var bl=new Blob([u],{{type:'application/zip'}});"
            f"var a=document.createElement('a');"
            f"a.href=URL.createObjectURL(bl);"
            f"a.download='mbp_server.zip';"
            f"document.body.appendChild(a);a.click();"
            f"setTimeout(function(){{a.remove();URL.revokeObjectURL(a.href);}},1000);"
            f"}})()"
        )
        await session.send_custom_message("eval_js", js)
        ui.notification_show("Server package downloading...", type="message", duration=3)

