        gsync = _get_garmin_sync()
        req(gsync)
        client = _garmin_client()
        req(client)
        _garmin_compare_status.set("Fetching...")
        try:
            acts = await _maybe_await(gsync.fetch_activity_list(client, count=30))
            _garmin_activities.set(acts)
            _garmin_compare_status.set(f"{len(acts)} activity(ies) found." if acts else "No activities.")
        except Exception as e:
            err_msg = gsync.classify_error(e)
            if "expired" in err_msg.lower():
                _garmin_client.set(None)
                await _maybe_await(gsync.clear_session())
            _garmin_compare_status.set(f"Garmin error: {err_msg}")
            ui.notification_show(f"Garmin fetch failed: {err_msg}", type="error", duration=8)

    # --- Bulk-add Garmin activities (selected categories) ---
    @reactive.Effect
    @reactive.event(input._garmin_compare_add_all)
    async def _garmin_compare_add_bulk():
        gsync = _get_garmin_sync()
        req(gsync)
        raw = input._garmin_compare_add_all()
        if not raw:
            return
        try:
            data = json.loads(raw)
            mode = data.get("mode", "all")
            selected_cats = data.get("categories", [])  # list of typeKey strings
        except Exception:
            return
        client = _garmin_client()
        req(client)
        activities = _garmin_activities()
        req(activities)

        # Filter activities to only selected categories
        if mode == "categories" and selected_cats:
            cat_set = set(selected_cats)
            targets = []
            for a in activities:
                at_dict = a.get("activityType", {})
                tkey = at_dict.get("typeKey", "other") if isinstance(at_dict, dict) else "other"
                if tkey in cat_set:
                    targets.append(a)
            cat_label = ", ".join(c.replace("_", " ").title() for c in selected_cats[:3])
            if len(selected_cats) > 3:
                cat_label += f" +{len(selected_cats) - 3} more"
        else:
            targets = list(activities)
            cat_label = "all"

        if not targets:
            _garmin_compare_status.set(f"No activities found for {cat_label}.")
            return

        _garmin_compare_status.set(f"Downloading {len(targets)} {cat_label} activity(ies)...")
        added = 0
        skipped = 0
        dl_errors = []
        current = list(_garmin_compare_files())

        # Check already-added filenames to avoid duplicates (pre-scan list)
        existing_names = {fname for _, fname in current}

        # Also check sessions already saved in history (by date + activity name)
        saved_dates = set()
        try:
            slug = input.compare_profile()
            if slug:
                hp = history_path(slug.replace("_", " ").title(), APP_DIR)
                hist_check = load_history(hp)
                if not hist_check.empty and "date" in hist_check.columns:
                    # Vectorized: build sets from columns directly (no iterrows)
                    _dates_s = hist_check["date"].astype(str).str.strip()
                    saved_dates = set(_dates_s[_dates_s != ""])
                    if "file_name" in hist_check.columns:
                        _fnames_s = hist_check["file_name"].astype(str).str.strip()
                        existing_names.update(_fnames_s[_fnames_s != ""])
        except Exception:
            pass

        for i, act in enumerate(targets):
            aid = str(act.get("activityId", ""))
            aname = act.get("activityName", "Activity")
            adate = str(act.get("startTimeLocal", ""))[:10]
            display_name = f"Garmin_{aname}_{adate}.fit"

            # Skip if already in pre-scan or already saved in history
            if display_name in existing_names:
                skipped += 1
                _garmin_compare_status.set(f"Skipping {aname} (already added)… [{i+1}/{len(targets)}]")
                continue

            _garmin_compare_status.set(f"Downloading {aname}… [{i+1}/{len(targets)}]")
            try:
                fbytes = await _maybe_await(gsync.download_fit_bytes(client, aid))
            except Exception as e:
                err_msg = gsync.classify_error(e)
                if "expired" in err_msg.lower():
                    _garmin_client.set(None)
                    await _maybe_await(gsync.clear_session())
                    _garmin_compare_status.set(f"Session expired after {added} download(s).")
                    ui.notification_show(f"Garmin session expired: {err_msg}", type="error", duration=8)
                    break
                # Skip this activity but continue
                dl_errors.append(f"{aname}: {err_msg}")
                skipped += 1
                continue

            if fbytes is None:
                dl_errors.append(f"{aname}: No .FIT file available")
                skipped += 1
                continue

            current.append((fbytes, display_name))
            existing_names.add(display_name)
            added += 1

        _garmin_compare_files.set(current)
        parts = []
        if added > 0:
            parts.append(f"{added} added")
        if skipped > 0:
            parts.append(f"{skipped} skipped")
        summary = f"Done — {', '.join(parts)}." if parts else "Done."
        if dl_errors:
            summary += f" Errors: {'; '.join(dl_errors[:3])}"
            if len(dl_errors) > 3:
                summary += f" (+{len(dl_errors) - 3} more)"
        _garmin_compare_status.set(summary)
        if added > 0:
            ui.notification_show(f"Added {added} Garmin activity(ies) to pre-scan.", type="message", duration=4)
        if dl_errors:
            ui.notification_show(
                f"Garmin download errors ({len(dl_errors)}): {'; '.join(dl_errors[:3])}",
                type="error", duration=10,
            )

