    @reactive.Effect
    @reactive.event(input.whoop_compare_apply)
    async def _whoop_compare_apply():
        wsync = _get_whoop_sync()
        req(wsync)
        recent = _whoop_recent_data()
        req(recent)

        slug = None
        try:
            slug = input.compare_profile()
        except Exception:
            pass
        if not slug:
            _whoop_compare_status.set("Select an athlete profile first.")
            return

        athlete = slug.replace("_", " ").title()
        hp = history_path(athlete, APP_DIR)
        hist = load_history(hp)
        updated = 0

        if "date" not in hist.columns:
            _whoop_compare_status.set("No sessions in profile to update.")
            return

        # Pre-compute date lookup for O(1) matching
        hist["_date_str"] = hist["date"].astype(str).str.strip()

        for rd in recent:
            d = rd.get("date", "")
            if not d:
                continue
            mask = hist["_date_str"] == d
            if not mask.any():
                continue
            # Vectorized update — apply all Whoop columns at once via .loc
            any_set = False
            for src_key, dst_col in _WHOOP_COL_MAP.items():
                val = rd.get(src_key)
                if val is not None:
                    hist.loc[mask, dst_col] = val
                    any_set = True
            if any_set:
                updated += int(mask.sum())

        hist.drop(columns=["_date_str"], inplace=True, errors="ignore")

        if updated > 0:
            save_history(hist, hp)
            _notify_athlete_tracker()  # update MBP Athletes.xlsx immediately
            await _persist_to_browser(slug)
            clear_history_cache()
            history_trigger.set(history_trigger() + 1)

        _whoop_compare_status.set(f"Updated {updated} session(s) with Whoop data.")
        if updated > 0:
            ui.notification_show(
                f"\u2705 Updated {updated} session(s) with Whoop data. Charts and tables refreshed.",
                type="message", duration=5,
            )
        else:
            _whoop_compare_status.set("No matching sessions found. Make sure you have sessions saved for these dates.")
            ui.notification_show("No matching sessions found for Whoop dates.", type="warning", duration=4)

    # --- Compare: FIT file upload pre-scan ---
    _compare_save_result = reactive.Value(None)

    @reactive.Calc
    def compare_fit_uploads():
        """Parse each uploaded FIT file for pre-scan (manual uploads + Garmin)."""
        # Gather manual uploads
        fi_list = None
        try:
            fi_list = input.compare_fit_upload()
        except Exception:
            pass

        # Gather Garmin-fetched files
        garmin_files = _garmin_compare_files()

        # Require at least one source
        req((fi_list is not None and len(fi_list) > 0) or (garmin_files and len(garmin_files) > 0))

        results = []

        # --- Process manual file uploads ---
        if fi_list:
            for fi in fi_list:
                try:
                    fpath = fi["datapath"]
                    fname = fi["name"]
                    with open(fpath, "rb") as f:
                        raw = f.read()
                    lower = fname.lower()
                    fbytes = None
                    if lower.endswith(".fit"):
                        fbytes = raw
                    elif len(raw) >= 12 and raw[8:12] == b".FIT":
                        fbytes = raw
                    elif lower.endswith(".zip"):
                        try:
                            with zipfile.ZipFile(io.BytesIO(raw)) as z:
                                members = [m for m in z.namelist() if m.lower().endswith(".fit")]
                                if members:
                                    chosen = sorted(members, key=lambda s: (s.count("/"), len(s), s))[0]
                                    fbytes = z.read(chosen)
                                    fname = chosen
                        except Exception:
                            pass
                    if fbytes is None:
                        continue
                    parsed = _prescan_fit_bytes(fbytes, fname, fi["name"])
                    if parsed is not None:
                        results.append(parsed)
                except Exception:
                    continue

        # --- Process Garmin-fetched files ---
        if garmin_files:
            for fbytes, gfname in garmin_files:
                try:
                    parsed = _prescan_fit_bytes(fbytes, gfname, gfname)
                    if parsed is not None:
                        results.append(parsed)
                except Exception:
                    continue

        return results

    def _prescan_fit_bytes(fbytes: bytes, fname: str, original_name: str) -> dict | None:
        """Parse FIT bytes and extract pre-scan metadata for the Compare upload pipeline."""
        meta, df_raw = parse_fit_bytes(fbytes)
        if df_raw.empty:
            return None
        # Auto-store FIT to _temp/ immediately on parse (same as Session page)
        try:
            _st = meta.get("start_time")
            if _st and fbytes:
                _iso = str(_st.isoformat()) if hasattr(_st, "isoformat") else str(_st)
                _fp = _fit_store_path_local("_temp", _iso)
                _fp.parent.mkdir(parents=True, exist_ok=True)
                _fp.write_bytes(fbytes)
        except Exception:
            pass
        df_base = ensure_elapsed_sec(df_raw)
        mode = infer_mode(meta, df_base)
        # Check power availability
        pw_raw = pd.to_numeric(df_base["power_w"], errors="coerce") if "power_w" in df_base.columns else None
        has_power = bool(pw_raw is not None and pw_raw.notna().any() and float(pw_raw.fillna(0).max()) > 0)
        output_col, output_unit, output_used = choose_output_metric(mode=mode, df=df_base, has_native_power=has_power)
        needs_power = bool((mode != "run") and (output_col == "power_w") and (not has_power))
        # Check distance
        dist_km = float("nan")
        if "distance_m" in df_base.columns:
            try:
                d = pd.to_numeric(df_base["distance_m"], errors="coerce").max()
                if np.isfinite(d):
                    dist_km = d / 1000.0
            except Exception:
                pass
        has_dist = bool(np.isfinite(dist_km) and dist_km > 0.01)
        # Extract last valid heart rate from FIT data
        last_hr = float("nan")
        if "heart_rate" in df_base.columns:
            hr_series = pd.to_numeric(df_base["heart_rate"], errors="coerce").dropna()
            hr_valid = hr_series[hr_series > 0]
            if not hr_valid.empty:
                last_hr = float(hr_valid.iloc[-1])
        # Extract session start time for display
        start_time = meta.get("start_time")
        session_pht = ""
        if start_time is not None:
            try:
                st = pd.Timestamp(start_time)
                if st.tzinfo is None:
                    st = st.tz_localize("UTC")
                pht = st.tz_convert("Asia/Manila")
                session_pht = f"{pht.strftime('%b')} {pht.day}, {pht.strftime('%Y %I:%M %p')} PHT"
            except Exception:
                pass
        # Auto-extract power from filename (e.g. "130w", "200W", "150 w")
        filename_power = float("nan")
        try:
            _pw_match = re.search(r'(\d+)\s*[wW]\b', original_name)
            if _pw_match:
                filename_power = float(_pw_match.group(1))
        except Exception:
            pass

        # --- Pre-run full analysis pipeline during prescan ---
        analysis = _get_analysis()
        pre_analysis = None  # will hold cached analysis results
        try:
            df_work = df_base
            if mode == "run":
                df_work = add_ngp_speed(df_base)
                df_work = ensure_elapsed_sec(df_work)

            max_gap_sec = 10.0
            cols_1hz = ["heart_rate", "power_w", "cadence", "speed_mps", "ngp_speed_mps", "grade"]
            df_full_1hz, gap_break = analysis.resample_records_to_1hz(df_work, cols_1hz, max_gap_sec=max_gap_sec)
            if not df_full_1hz.empty:
                df_full_1hz = df_full_1hz.sort_index()
                t0 = df_work.index[0]
                df_full_1hz["elapsed_sec"] = (df_full_1hz.index - t0).total_seconds()

            warmup_min = 15
            try:
                wu = analysis._auto_detect_warmup_end_sec(df_work, mode=mode)
                warmup_min = int(wu.get("warmup_end_min", 15))
            except Exception:
                pass

            clean = analysis.prepare_clean_segment_1hz(
                df_work, warmup_sec=warmup_min * 60, end_exclude_sec=0,
                max_gap_sec=max_gap_sec, cadence_required_ratio=0.60,
                ftp_w=0, stride_thr_pct=1.25, min_stride_confirm_sec=3,
                recovery_buffer_sec=60,
                stride_mode="Option A — stop analysis at first stride",
                pause_fallback_power_w=5.0, pause_fallback_speed_mps=0.22,
                df_full_1hz=df_full_1hz, gap_break_sec_full=gap_break,
            )

            if clean.df_used_1hz.empty:
                # Store a minimal pre_analysis with the clean object so notes are preserved
                total_elapsed_sec = float(pd.to_numeric(df_work["elapsed_sec"], errors="coerce").max()) if "elapsed_sec" in df_work.columns else float("nan")
                total_minutes = total_elapsed_sec / 60.0 if np.isfinite(total_elapsed_sec) else float("nan")
                pre_analysis = {
                    "clean": clean, "df_work": df_work, "res": None,
                    "ef": float("nan"), "avg_out": float("nan"), "avg_hr": float("nan"),
                    "avg_speed_kph": float("nan"), "avg_power_w": float("nan"),
                    "low_thr": float("nan"), "high_thr": float("nan"),
                    "status": "", "driver_label": "",
                    "terrain_info": None, "terrain": "unknown",
                    "drift_sec_val": None, "drift_elapsed_val": None,
                    "weather": "", "temp_min_c": float("nan"), "temp_max_c": float("nan"),
                    "total_minutes": total_minutes, "minutes_analyzed": 0,
                    "warmup_min": warmup_min, "erg_subtype": "erg",
                }
            else:
                erg_subtype = infer_erg_subtype(meta) if mode == "erg" else "erg"
                seconds_analyzed = len(clean.df_used_1hz)
                minutes_analyzed = seconds_analyzed / 60.0
                terrain_info = compute_terrain(df_work, max_gap_sec=max_gap_sec, mode=mode)
                terrain = terrain_info.terrain

                res = analysis.compute_decoupling_1hz(clean.df_used_1hz, output_col=output_col)
                ef = avg_out = avg_hr = float("nan")
                low_thr = high_thr = float("nan")
                status = ""
                driver_label = ""
                drift_sec_val = drift_elapsed_val = None

                if res is not None:
                    ef, avg_out, avg_hr = analysis.compute_overall_ef_1hz(clean.df_used_1hz, output_col=output_col, decoupling_res=res)
                    low_thr, high_thr = thresholds_for_session(mode=mode, terrain=terrain, minutes_analyzed=minutes_analyzed, erg_subtype=erg_subtype)
                    status = analysis.classify_decoupling(float(res.decoupling_pct), float(low_thr), float(high_thr), mode=mode, terrain=terrain)
                    driver_label, _, _ = analysis.drift_driver_breakdown(hr1=res.hr1, hr2=res.hr2, out1=res.out1, out2=res.out2)
                    try:
                        drift_sec_val, drift_elapsed_val, _ = analysis.detect_point_of_no_return_details_1hz(
                            clean.df_used_1hz, hr_col="heart_rate", output_col=output_col,
                        )
                    except Exception:
                        pass

                avg_speed_kph = float("nan")
                if "speed_mps" in clean.df_used_1hz.columns:
                    avg_speed_kph = float(pd.to_numeric(clean.df_used_1hz["speed_mps"], errors="coerce").mean()) * 3.6
                avg_power_w = float("nan")
                if "power_w" in clean.df_used_1hz.columns:
                    avg_power_w = float(pd.to_numeric(clean.df_used_1hz["power_w"], errors="coerce").mean())

                weather = get_activity_weather_summary(meta, df_raw)
                temp_min_c, temp_max_c = extract_temp_bounds_from_weather_summary(weather)
                total_elapsed_sec = float(pd.to_numeric(df_work["elapsed_sec"], errors="coerce").max()) if "elapsed_sec" in df_work.columns else float("nan")
                total_minutes = total_elapsed_sec / 60.0 if np.isfinite(total_elapsed_sec) else float("nan")

                pre_analysis = {
                    "clean": clean, "df_work": df_work, "res": res,
                    "ef": ef, "avg_out": avg_out, "avg_hr": avg_hr,
                    "avg_speed_kph": avg_speed_kph, "avg_power_w": avg_power_w,
                    "low_thr": low_thr, "high_thr": high_thr,
                    "status": status, "driver_label": driver_label,
                    "terrain_info": terrain_info, "terrain": terrain,
                    "drift_sec_val": drift_sec_val, "drift_elapsed_val": drift_elapsed_val,
                    "weather": weather, "temp_min_c": temp_min_c, "temp_max_c": temp_max_c,
                    "total_minutes": total_minutes, "minutes_analyzed": minutes_analyzed,
                    "warmup_min": warmup_min, "erg_subtype": erg_subtype,
                }
        except Exception:
            pass  # pre-analysis failed — will re-run at save time

        # Garmin 2-min recovery HR extracted from FIT event messages
        recovery_hr_bpm = meta.get("recovery_hr_bpm")  # None if not present

        return {
            "fname": fname, "fbytes": fbytes, "meta": meta, "df_raw": df_raw,
            "mode": mode, "has_power": has_power, "needs_power": needs_power,
            "dist_km": dist_km, "has_dist": has_dist,
            "output_col": output_col, "output_unit": output_unit, "output_used": output_used,
            "last_hr": last_hr, "session_pht": session_pht,
            "filename_power": filename_power,
            "pre_analysis": pre_analysis,
            "recovery_hr_bpm": recovery_hr_bpm,
        }

    @output
    @render.ui
    def compare_fit_prescan():
        """Show missing metric inputs for each uploaded FIT file."""
        uploads = compare_fit_uploads()
        if not uploads:
            return ui.div()
        parts = []
        for i, u in enumerate(uploads):
            session_pht = u.get("session_pht", "")
            # Format session duration from pre_analysis total_minutes
            _dur_txt = ""
            _pre = u.get("pre_analysis") or {}
            _tm = _pre.get("total_minutes", float("nan"))
            if np.isfinite(_tm) and _tm > 0:
                _hrs = int(_tm // 60)
                _mins = int(_tm % 60)
                _dur_txt = f"{_hrs}h {_mins:02d}m" if _hrs > 0 else f"{_mins}m"
            file_parts = [
                ui.tags.span(f"{u['fname']}", style=f"color: {COLOR_ELITE}; font-weight: 600; font-size: 13px;"),
                ui.tags.span(
                    f" — {u['mode']}, {len(u['df_raw'])} records"
                    + (f", {_dur_txt}" if _dur_txt else ""),
                    style="font-size: 12px; opacity: 0.7;",
                ),
            ]
            if session_pht or _dur_txt:
                _date_dur_parts = []
                if session_pht:
                    _date_dur_parts.extend([
                        fa.icon_svg("calendar-day", width="13px", height="13px", fill=COLOR_ADAPTING),
                        ui.tags.span(f" {session_pht}", style=f"color: {COLOR_ADAPTING}; font-weight: 600; font-size: 12px;"),
                    ])
                if _dur_txt:
                    if session_pht:
                        _date_dur_parts.append(ui.tags.span("  ·  ", style="opacity:0.4; font-size:12px;"))
                    _date_dur_parts.extend([
                        fa.icon_svg("clock", width="13px", height="13px", fill="#38bdf8"),
                        ui.tags.span(f" {_dur_txt}", style="color: #38bdf8; font-weight: 600; font-size: 12px;"),
                    ])
                file_parts.append(
                    ui.div(*_date_dur_parts, style="margin-top: 4px;"),
                )
            if u["needs_power"]:
                _fp = u.get("filename_power", float("nan"))
                _fp_val = int(_fp) if np.isfinite(_fp) and _fp > 0 else 0
                _fp_label = f"Avg power (W) — auto: {_fp_val}W from filename" if _fp_val > 0 else "Avg power (W)"
                file_parts.append(
                    ui.input_numeric(f"cfu_power_{i}", _fp_label, value=_fp_val, min=0, max=5000, step=1),
                )
            if not u["has_dist"]:
                if u["mode"] == "stairmaster":
                    file_parts.append(
                        ui.input_numeric(f"cfu_elev_{i}", "Elevation (m)", value=0, min=0, max=50000, step=1),
                    )
                else:
                    file_parts.append(
                        ui.input_numeric(f"cfu_dist_{i}", "Distance (km)", value=0, min=0, max=1000, step=0.1),
                    )
            # 2-min Recovery Gap auto-computed from FIT data
            last_hr_txt = f"{int(u['last_hr'])} bpm" if np.isfinite(u.get("last_hr", float("nan"))) else "N/A"
            _rhr_bpm = u.get("recovery_hr_bpm")
            _gap = None
            if _rhr_bpm is not None and np.isfinite(u.get("last_hr", float("nan"))) and u["last_hr"] > _rhr_bpm:
                _gap = int(u["last_hr"] - _rhr_bpm)
            _gap_txt = f"{_gap} bpm" if _gap is not None else "N/A"
            _gap_color = COLOR_ELITE if _gap is not None else "rgba(255,255,255,0.4)"
            file_parts.append(
                ui.layout_columns(
                    ui.div(
                        ui.tags.label("Last HR at stop", style="font-size:11px; opacity:0.7; display:block;"),
                        ui.tags.span(last_hr_txt, style=f"font-weight:700; color:{COLOR_HR}; font-size:14px;"),
                        style="padding:4px 0;",
                    ),
                    ui.div(
                        ui.tags.label("2min Recovery Gap (auto)", style="font-size:11px; opacity:0.7; display:block;"),
                        ui.tags.span(_gap_txt, style=f"font-weight:700; color:{_gap_color}; font-size:14px;"),
                        style="padding:4px 0;",
                    ),
                    col_widths=[6, 6],
                ),
            )
            file_parts.append(
                ui.layout_columns(
                    ui.input_numeric(f"cfu_rpe1_{i}", "RPE 1st half", value=None, min=1, max=10, step=0.5),
                    ui.input_numeric(f"cfu_rpe2_{i}", "RPE 2nd half", value=None, min=1, max=10, step=0.5),
                    col_widths=[6, 6],
                ),
            )
            # Fluid and carb always shown
            file_parts.append(
                ui.layout_columns(
                    ui.input_numeric(f"cfu_fluid_{i}", "Fluid intake (ml)", value=None, min=0, max=10000, step=50),
                    ui.input_numeric(f"cfu_carb_{i}", "Carb intake (g)", value=None, min=0, max=1000, step=5),
                    col_widths=[6, 6],
                ),
            )
            # Hill sprint checkbox for run sessions
            if u["mode"] == "run":
                file_parts.append(
                    ui.input_checkbox(
                        f"cfu_hillsprint_{i}",
                        ui.TagList(fa.icon_svg("mountain", width="13px", height="13px"), " Hill Sprints (30s \u00d7 6-10 all-out, 4 min rest)"),
                        value=False,
                    ),
                )
            parts.append(ui.div(*file_parts, style="margin-bottom: 10px; padding: 8px; border: 1px solid rgba(255,255,255,0.1); border-radius: 6px;"))
        return ui.div(
            ui.tags.span(f"{len(uploads)} file(s) ready", style=f"color: {COLOR_ELITE}; font-weight: 600; display: block; margin-bottom: 6px;"),
            *parts,
        )

    @reactive.Effect
    @reactive.event(input.compare_save_sessions)
    async def _compare_save_fit_sessions():
        """Run analysis on each uploaded FIT and save to the selected profile."""
        analysis = _get_analysis()
        uploads = compare_fit_uploads()
        req(uploads)
        slug = input.compare_profile()
        # If no profile selected, auto-create one named with current Philippine date/time
        if not slug:
            now_pht = pd.Timestamp.now(tz="Asia/Manila")
            auto_name = now_pht.strftime("Session %b %d %Y %I%M%p")
            slug = sanitize_slug(auto_name)
            # Update the selectize to show the new profile
            ui.update_selectize("compare_profile", choices={slug: auto_name}, selected=slug)
            ui.notification_show(f"Auto-created profile: {auto_name}", type="message", duration=4)
        # Use slug as athlete name (profile name)
        athlete = slug.replace("_", " ").title()
        hp = history_path(athlete, APP_DIR)
        hist = load_history(hp)
        saved = 0
        errors = []
        n_total = len(uploads)
        progress = ui.Progress(min=0, max=n_total)
        progress.set(message="Analyzing sessions\u2026", value=0)
        for i, u in enumerate(uploads):
            progress.set(value=i, message=f"Saving {i+1}/{n_total}: {u['fname']}", detail="Reading pre-analyzed data…")
            try:
                meta = u["meta"]
                df_raw = u["df_raw"]
                mode = u["mode"]
                output_col = u["output_col"]
                output_unit = u["output_unit"]
                output_used = u["output_used"]
                has_power = u["has_power"]

                # Use pre-computed analysis from prescan if available
                pa = u.get("pre_analysis")
                if pa is not None:
                    clean = pa["clean"]
                    res = pa["res"]
                    ef = pa["ef"]; avg_out = pa["avg_out"]; avg_hr = pa["avg_hr"]
                    avg_speed_kph = pa["avg_speed_kph"]; avg_power_w = pa["avg_power_w"]
                    low_thr = pa["low_thr"]; high_thr = pa["high_thr"]
                    status = pa["status"]; driver_label = pa["driver_label"]
                    terrain_info = pa["terrain_info"]; terrain = pa["terrain"]
                    drift_sec_val = pa["drift_sec_val"]; drift_elapsed_val = pa["drift_elapsed_val"]
                    weather = pa["weather"]; temp_min_c = pa["temp_min_c"]; temp_max_c = pa["temp_max_c"]
                    total_minutes = pa["total_minutes"]; minutes_analyzed = pa["minutes_analyzed"]
                    warmup_min = pa["warmup_min"]; erg_subtype = pa["erg_subtype"]
                    df_work = pa["df_work"]
                else:
                    # Fallback: full analysis at save time (should rarely happen)
                    progress.set(value=i, message=f"Analyzing {i+1}/{n_total}: {u['fname']}", detail="Running full analysis…")
                    df_base = ensure_elapsed_sec(df_raw)
                    df_work = df_base
                    if mode == "run":
                        df_work = add_ngp_speed(df_base)
                        df_work = ensure_elapsed_sec(df_work)
                    erg_subtype = infer_erg_subtype(meta) if mode == "erg" else "erg"
                    max_gap_sec = 10.0
                    cols_1hz = ["heart_rate", "power_w", "cadence", "speed_mps", "ngp_speed_mps", "grade"]
                    df_full_1hz, gap_break = analysis.resample_records_to_1hz(df_work, cols_1hz, max_gap_sec=max_gap_sec)
                    if not df_full_1hz.empty:
                        df_full_1hz = df_full_1hz.sort_index()
                        t0 = df_work.index[0]
                        df_full_1hz["elapsed_sec"] = (df_full_1hz.index - t0).total_seconds()
                    warmup_min = 15
                    try:
                        wu = analysis._auto_detect_warmup_end_sec(df_work, mode=mode)
                        warmup_min = int(wu.get("warmup_end_min", 15))
                    except Exception:
                        pass
                    clean = analysis.prepare_clean_segment_1hz(
                        df_work, warmup_sec=warmup_min * 60, end_exclude_sec=0,
                        max_gap_sec=max_gap_sec, cadence_required_ratio=0.60,
                        ftp_w=0, stride_thr_pct=1.25, min_stride_confirm_sec=3,
                        recovery_buffer_sec=60,
                        stride_mode="Option A — stop analysis at first stride",
                        pause_fallback_power_w=5.0, pause_fallback_speed_mps=0.22,
                        df_full_1hz=df_full_1hz, gap_break_sec_full=gap_break,
                    )
                    if clean.df_used_1hz.empty:
                        # Build specific error with diagnostics from analysis notes
                        _raw_len = len(df_raw) if df_raw is not None else 0
                        _total_sec = float(pd.to_numeric(df_work["elapsed_sec"], errors="coerce").max()) if "elapsed_sec" in df_work.columns else 0
                        _total_min = _total_sec / 60.0 if np.isfinite(_total_sec) and _total_sec > 0 else 0
                        _reason = "; ".join(clean.notes) if clean.notes else "unknown reason"
                        _detail = (
                            f"{u['fname']}: not enough steady-state data — "
                            f"mode={mode}, {_raw_len} records, {_total_min:.0f} min total, "
                            f"warmup={warmup_min} min. Reason: {_reason}"
                        )
                        errors.append(_detail)
                        continue
                    seconds_analyzed = len(clean.df_used_1hz)
                    minutes_analyzed = seconds_analyzed / 60.0
                    terrain_info = compute_terrain(df_work, max_gap_sec=max_gap_sec, mode=mode)
                    terrain = terrain_info.terrain
                    res = analysis.compute_decoupling_1hz(clean.df_used_1hz, output_col=output_col)
                    ef = avg_out = avg_hr = float("nan")
                    low_thr = high_thr = float("nan")
                    status = ""; driver_label = ""
                    drift_sec_val = drift_elapsed_val = None
                    if res is not None:
                        ef, avg_out, avg_hr = analysis.compute_overall_ef_1hz(clean.df_used_1hz, output_col=output_col, decoupling_res=res)
                        low_thr, high_thr = thresholds_for_session(mode=mode, terrain=terrain, minutes_analyzed=minutes_analyzed, erg_subtype=erg_subtype)
                        status = analysis.classify_decoupling(float(res.decoupling_pct), float(low_thr), float(high_thr), mode=mode, terrain=terrain)
                        driver_label, _, _ = analysis.drift_driver_breakdown(hr1=res.hr1, hr2=res.hr2, out1=res.out1, out2=res.out2)
                        try:
                            drift_sec_val, drift_elapsed_val, _ = analysis.detect_point_of_no_return_details_1hz(
                                clean.df_used_1hz, hr_col="heart_rate", output_col=output_col,
                            )
                        except Exception:
                            pass
                    avg_speed_kph = float("nan")
                    if "speed_mps" in clean.df_used_1hz.columns:
                        avg_speed_kph = float(pd.to_numeric(clean.df_used_1hz["speed_mps"], errors="coerce").mean()) * 3.6
                    avg_power_w = float("nan")
                    if "power_w" in clean.df_used_1hz.columns:
                        avg_power_w = float(pd.to_numeric(clean.df_used_1hz["power_w"], errors="coerce").mean())
                    weather = get_activity_weather_summary(meta, df_raw)
                    temp_min_c, temp_max_c = extract_temp_bounds_from_weather_summary(weather)
                    total_elapsed_sec = float(pd.to_numeric(df_work["elapsed_sec"], errors="coerce").max()) if "elapsed_sec" in df_work.columns else float("nan")
                    total_minutes = total_elapsed_sec / 60.0 if np.isfinite(total_elapsed_sec) else float("nan")

                # Check if pre-analysis had empty clean segment
                if pa is not None and clean.df_used_1hz.empty:
                    _raw_len = len(df_raw) if df_raw is not None else 0
                    _tm = pa.get("total_minutes", 0)
                    _total_min = _tm if (_tm and np.isfinite(_tm)) else 0
                    _wmin = pa.get("warmup_min", 15)
                    _reason = "; ".join(clean.notes) if clean.notes else "unknown reason"
                    _detail = (
                        f"{u['fname']}: not enough steady-state data — "
                        f"mode={mode}, {_raw_len} records, {_total_min:.0f} min total, "
                        f"warmup={_wmin} min. Reason: {_reason}"
                    )
                    errors.append(_detail)
                    continue

                # Manual power injection (optional — save proceeds even without power)
                if u["needs_power"]:
                    try:
                        mp = float(getattr(input, f"cfu_power_{i}")() or 0)
                    except Exception:
                        mp = 0.0
                    if mp > 0:
                        df_m = clean.df_used_1hz.copy()
                        df_m["power_w"] = mp
                        clean = dc_replace(clean, df_used_1hz=df_m)
                        # Re-compute decoupling and averages with injected power
                        res = analysis.compute_decoupling_1hz(clean.df_used_1hz, output_col=output_col)
                        if res is not None:
                            ef, avg_out, avg_hr = analysis.compute_overall_ef_1hz(clean.df_used_1hz, output_col=output_col, decoupling_res=res)
                            avg_power_w = mp

                start_time = meta.get("start_time")
                start_iso = str(start_time.isoformat()) if hasattr(start_time, "isoformat") else str(start_time)

                # 2-min Recovery Gap = last HR at stop − HR after 2 min (auto from FIT)
                last_hr = u.get("last_hr", float("nan"))
                _rhr_bpm = u.get("recovery_hr_bpm")
                hr_after_2min = float(_rhr_bpm) if _rhr_bpm is not None else float("nan")
                if np.isfinite(last_hr) and np.isfinite(hr_after_2min) and last_hr > hr_after_2min:
                    recovery_hr = last_hr - hr_after_2min
                else:
                    recovery_hr = float("nan")

                # User-entered RPE
                try:
                    rpe_h1 = float(getattr(input, f"cfu_rpe1_{i}")()) if getattr(input, f"cfu_rpe1_{i}")() is not None else float("nan")
                except Exception:
                    rpe_h1 = float("nan")
                try:
                    rpe_h2 = float(getattr(input, f"cfu_rpe2_{i}")()) if getattr(input, f"cfu_rpe2_{i}")() is not None else float("nan")
                except Exception:
                    rpe_h2 = float("nan")

                # Auto-populate HRV/RHR from Whoop and Garmin (no user selection needed)
                progress.set(value=i, message=f"Analyzing {i+1}/{n_total}: {u['fname']}", detail="Fetching Whoop/Garmin data…")
                whoop_val = float("nan")
                garmin_hrv_val = float("nan")
                garmin_rhr_val = float("nan")
                _w_rec_data = _w_slp_data = _w_cyc_data = None

                # Auto-fetch Whoop data for this session date if connected
                _w_date = str(start_time.date()) if hasattr(start_time, "date") else ""
                if _w_date and _whoop_tokens() is not None:
                    try:
                        _wsync = _get_whoop_sync()
                        _wcreds = (await _maybe_await(_wsync.load_credentials())) if _wsync else None
                        if _wsync and _wcreds:
                            _wtok = _whoop_tokens()
                            _w_rec, _wtok = await _maybe_await(_wsync.get_recovery_for_date(_wtok, _wcreds["client_id"], _wcreds["client_secret"], _w_date))
                            _w_slp, _wtok = await _maybe_await(_wsync.get_sleep_for_date(_wtok, _wcreds["client_id"], _wcreds["client_secret"], _w_date))
                            _w_cyc, _wtok = await _maybe_await(_wsync.get_cycle_for_date(_wtok, _wcreds["client_id"], _wcreds["client_secret"], _w_date))
                            _whoop_tokens.set(_wtok)
                            if _w_rec:
                                if _w_rec.get("recovery_score") is not None:
                                    whoop_val = float(_w_rec["recovery_score"])
                                _w_rec_data = _w_rec
                            _w_slp_data = _w_slp
                            _w_cyc_data = _w_cyc
                    except Exception:
                        _w_rec_data = _w_slp_data = _w_cyc_data = None

                # Auto-fetch Garmin HRV/RHR for this session date if connected
                if _w_date and _garmin_client() is not None:
                    try:
                        _gsync = _get_garmin_sync()
                        if _gsync:
                            _gclient = _garmin_client()
                            # Try to get HRV data from Garmin for the session date
                            try:
                                hrv_data = await _maybe_await(_gclient.get_hrv_data(_w_date))
                                if hrv_data:
                                    # Extract HRV summary (weekly average or nightly average)
                                    _hrv_summary = hrv_data.get("hrvSummary", {})
                                    _last_night = _hrv_summary.get("lastNightAvg")
                                    _weekly = _hrv_summary.get("weeklyAvg")
                                    if _last_night and float(_last_night) > 0:
                                        garmin_hrv_val = float(_last_night)
                                    elif _weekly and float(_weekly) > 0:
                                        garmin_hrv_val = float(_weekly)
                            except Exception:
                                pass
                            # Try to get resting HR from Garmin
                            try:
                                hr_data = await _maybe_await(_gclient.get_rhr_day(_w_date))
                                if hr_data:
                                    for ts_entry in hr_data.get("allMetrics", {}).get("metricsMap", {}).get("WELLNESS_RESTING_HEART_RATE", []):
                                        if ts_entry.get("value"):
                                            garmin_rhr_val = float(ts_entry["value"])
                                            break
                            except Exception:
                                pass
                    except Exception:
                        pass
                try:
                    fluid_val = float(getattr(input, f"cfu_fluid_{i}")()) if getattr(input, f"cfu_fluid_{i}")() is not None else float("nan")
                except Exception:
                    fluid_val = float("nan")
                try:
                    carb_val = float(getattr(input, f"cfu_carb_{i}")()) if getattr(input, f"cfu_carb_{i}")() is not None else float("nan")
                except Exception:
                    carb_val = float("nan")

                # User-entered distance or elevation (stairmaster)
                dist_val = u["dist_km"]
                elev_override = float("nan")
                if not u["has_dist"]:
                    if mode == "stairmaster":
                        try:
                            elev_override = float(getattr(input, f"cfu_elev_{i}")() or 0)
                        except Exception:
                            elev_override = 0.0
                    else:
                        try:
                            dist_val = float(getattr(input, f"cfu_dist_{i}")() or 0)
                        except Exception:
                            dist_val = 0.0

                row = {
                    "start_time_iso": start_iso,
                    "athlete_id": athlete,
                    "date": str(start_time.date()) if hasattr(start_time, "date") else "",
                    "mode": mode,
                    "terrain": terrain,
                    "output_used": output_used,
                    "distance_km": dist_val,
                    "elev_gain_m": elev_override if np.isfinite(elev_override) else terrain_info.elev_gain_m,
                    "decoupling_pct": res.decoupling_pct if res else float("nan"),
                    "low_thr": low_thr,
                    "high_thr": high_thr,
                    "status": status,
                    "ef": ef,
                    "avg_hr": avg_hr,
                    "avg_output": avg_out,
                    "avg_speed_kph": avg_speed_kph,
                    "avg_power_w": avg_power_w,
                    "output_unit": output_unit,
                    "total_minutes": total_minutes,
                    "minutes_analyzed": minutes_analyzed,
                    "file_name": u["fname"],
                    "weather_summary": weather,
                    "hr_h1": res.hr1 if res else float("nan"),
                    "hr_h2": res.hr2 if res else float("nan"),
                    "out_h1": res.out1 if res else float("nan"),
                    "out_h2": res.out2 if res else float("nan"),
                    "drift_driver": driver_label,
                    "recovery_hr": recovery_hr,
                    "last_hr_bpm": last_hr if np.isfinite(last_hr) else float("nan"),
                    "recovery_hr_2min_bpm": hr_after_2min if np.isfinite(hr_after_2min) else float("nan"),
                    "rpe_h1": rpe_h1,
                    "rpe_h2": rpe_h2,
                    "warmup_min": warmup_min,
                    "end_exclude_min": 0,
                    "event_goal_min": 60.0,
                    "erg_subtype": erg_subtype,
                    "whoop_score": whoop_val,
                    "fluid_intake_ml": fluid_val,
                    "carb_intake_g": carb_val,
                    "garmin_hrv_ms": garmin_hrv_val,
                    "garmin_resting_hr": garmin_rhr_val,
                    "temp_min_c": temp_min_c,
                    "temp_max_c": temp_max_c,
                    "time_to_drift_sec": drift_sec_val if drift_sec_val is not None else float("nan"),
                    "time_to_drift_elapsed_sec": drift_elapsed_val if drift_elapsed_val is not None else float("nan"),
                }
                # Hill sprints checkbox (run sessions only)
                try:
                    if mode == "run" and input[f"cfu_hillsprint_{i}"]():
                        row["hill_sprints"] = "1"
                except Exception:
                    pass
                # Add Whoop auto-fetched columns if available
                try:
                    if _w_rec_data:
                        if _w_rec_data.get("hrv_rmssd_milli") is not None:
                            row["whoop_hrv_ms"] = _w_rec_data["hrv_rmssd_milli"]
                        if _w_rec_data.get("resting_heart_rate") is not None:
                            row["whoop_resting_hr"] = _w_rec_data["resting_heart_rate"]
                        if _w_rec_data.get("spo2_percentage") is not None:
                            row["whoop_spo2"] = _w_rec_data["spo2_percentage"]
                        if _w_rec_data.get("skin_temp_celsius") is not None:
                            row["whoop_skin_temp_c"] = _w_rec_data["skin_temp_celsius"]
                    if _w_slp_data:
                        if _w_slp_data.get("sleep_performance_percentage") is not None:
                            row["whoop_sleep_perf"] = _w_slp_data["sleep_performance_percentage"]
                        if _w_slp_data.get("sleep_efficiency_percentage") is not None:
                            row["whoop_sleep_efficiency"] = _w_slp_data["sleep_efficiency_percentage"]
                        if _w_slp_data.get("total_sleep_hours") is not None:
                            row["whoop_sleep_hours"] = _w_slp_data["total_sleep_hours"]
                        if _w_slp_data.get("rem_min") is not None:
                            row["whoop_rem_min"] = _w_slp_data["rem_min"]
                        if _w_slp_data.get("sws_min") is not None:
                            row["whoop_sws_min"] = _w_slp_data["sws_min"]
                        if _w_slp_data.get("light_min") is not None:
                            row["whoop_light_min"] = _w_slp_data["light_min"]
                        if _w_slp_data.get("awake_min") is not None:
                            row["whoop_awake_min"] = _w_slp_data["awake_min"]
                        if _w_slp_data.get("respiratory_rate") is not None:
                            row["whoop_resp_rate"] = _w_slp_data["respiratory_rate"]
                    if _w_cyc_data:
                        if _w_cyc_data.get("strain") is not None:
                            row["whoop_strain"] = _w_cyc_data["strain"]
                        if _w_cyc_data.get("kilojoules") is not None:
                            row["whoop_calories_kj"] = _w_cyc_data["kilojoules"]
                except Exception:
                    pass  # Non-critical — save proceeds without Whoop data
                hist, action = _history_upsert_row(hist, row)
                saved += 1
                # Copy FIT file from _temp to athlete's permanent directory
                try:
                    _temp_path = _fit_store_path_local("_temp", start_iso)
                    _perm_path = _fit_store_path_local(slug, start_iso)
                    if _temp_path.exists():
                        _perm_path.parent.mkdir(parents=True, exist_ok=True)
                        import shutil
                        shutil.copy2(str(_temp_path), str(_perm_path))
                        _temp_path.unlink(missing_ok=True)  # clean up temp
                    elif u.get("fbytes"):
                        # Fallback: write directly from upload bytes
                        _perm_path.parent.mkdir(parents=True, exist_ok=True)
                        _perm_path.write_bytes(u["fbytes"])
                    # Also sync to api_server (for remote/Pyodide access)
                    if _perm_path.exists():
                        await _store_fit_on_server(_perm_path.read_bytes(), slug, start_iso)
                except Exception:
                    pass
            except Exception as e:
                errors.append(f"{u['fname']}: {e}")
                continue

        if saved > 0:
            progress.set(value=n_total, message="Saving to profile…", detail="Writing history CSV…")
            try:
                save_history(hist, hp)
                _notify_athlete_tracker()  # update MBP Athletes.xlsx immediately
                progress.set(value=n_total, message="Saving to profile…", detail="Syncing to browser storage…")
                await _persist_to_browser(slug)
                clear_history_cache()
                history_trigger.set(history_trigger() + 1)
                # Auto-republish if sharing is active
                try:
                    if _share_is_active():
                        updated_hist = load_history(hp)
                        csv_text = updated_hist.to_csv(index=False)
                        await _share_post("/api/share/publish",
                                          {"slug": slug, "csv_text": csv_text})
                except Exception:
                    pass  # silent — don't block save flow
            except Exception as e:
                errors.append(f"Save error: {e}")

        # Close progress bar
        progress.close()

        if saved > 0 and not errors:
            _compare_save_result.set({"ok": True, "msg": f"{saved} session(s) saved to {athlete}."})
            ui.notification_show(f"\u2705 {saved} session(s) saved to {athlete}.", type="message", duration=5)
            ui.update_accordion("profile_mgmt_accordion", show=False)
            _garmin_compare_files.set([])  # clear Garmin files after successful save
        elif saved > 0 and errors:
            err_detail = "; ".join(errors[:5])
            if len(errors) > 5:
                err_detail += f" (+{len(errors) - 5} more)"
            _compare_save_result.set({"ok": True, "msg": f"{saved} saved, {len(errors)} error(s): {err_detail}"})
            ui.notification_show(f"\u26a0\ufe0f {saved} saved, {len(errors)} error(s): {err_detail}", type="warning", duration=10)
            ui.update_accordion("profile_mgmt_accordion", show=False)
            _garmin_compare_files.set([])  # clear Garmin files after save
        else:
            err_detail = "; ".join(errors[:5]) if errors else "No valid sessions."
            if len(errors) > 5:
                err_detail += f" (+{len(errors) - 5} more)"
            _compare_save_result.set({"ok": False, "msg": err_detail})
            ui.notification_show(f"\u274c No sessions saved. {err_detail}", type="error", duration=10)

    @output
    @render.ui
    def compare_save_status():
        result = _compare_save_result()
        if result is None:
            return ui.div()
        color = COLOR_ELITE if result.get("ok") else COLOR_NEEDS_WORK
        return ui.p(result.get("msg", ""), style=f"color: {color}; font-size: 12px; margin-top: 6px;")


