def _rag_color_for(status: str) -> str:
    """Return RAG color (colorblind-safe, Section 12.1) based on status text."""
    s = str(status).lower()
    if "elite" in s or "increase" in s:
        return COLOR_ELITE
    elif "adapting" in s or "maintain" in s:
        return COLOR_ADAPTING
    elif "needs" in s or "lessen" in s:
        return COLOR_NEEDS_WORK
    # Fallback to the original status_color_for
    return status_color_for(status)


def _build_advanced_metrics(result: dict) -> Tag:
    """Build the advanced metrics section for progressive disclosure (Section 2.2)."""
    items = []

    # Half-by-half breakdown
    res = result["res"]
    items.append(ui.layout_columns(
        ui.value_box("HR 1st Half", f"{res.hr1:.0f} bpm" if np.isfinite(res.hr1) else "—",
                     showcase=fa.icon_svg("heart"), theme="danger"),
        ui.value_box("HR 2nd Half", f"{res.hr2:.0f} bpm" if np.isfinite(res.hr2) else "—",
                     showcase=fa.icon_svg("heart"), theme="danger"),
        ui.value_box(f"Output 1st Half", f"{res.out1:.1f}" if np.isfinite(res.out1) else "—",
                     showcase=fa.icon_svg("bolt"), theme="info"),
        ui.value_box(f"Output 2nd Half", f"{res.out2:.1f}" if np.isfinite(res.out2) else "—",
                     showcase=fa.icon_svg("bolt"), theme="info"),
        col_widths=[3, 3, 3, 3],
    ))

    # Cardiac cost (runs)
    if result["mode"] == "run" and np.isfinite(result.get("beats_per_km", float("nan"))):
        items.append(ui.layout_columns(
            ui.value_box("Beats/km", f"{result['beats_per_km']:.0f}",
                         showcase=fa.icon_svg("heart-pulse"), theme="warning"),
            ui.value_box("Cardiac Cost Rise", f"{result['cardiac_cost_rise_pct']:.1f}%" if np.isfinite(result['cardiac_cost_rise_pct']) else "—",
                         showcase=fa.icon_svg("arrow-up"), theme="warning"),
            col_widths=[6, 6],
        ))

    # Power decay
    if np.isfinite(result.get("power_decay_pct", float("nan"))):
        items.append(ui.layout_columns(
            ui.value_box("Energy (kJ)", f"{result['energy_kj']:.0f}" if np.isfinite(result['energy_kj']) else "—",
                         showcase=fa.icon_svg("fire"), theme="info"),
            ui.value_box("Power Decay", f"{result['power_decay_pct']:.1f}%",
                         showcase=fa.icon_svg("arrow-down"), theme="warning"),
            col_widths=[6, 6],
        ))

    if not items:
        items.append(ui.p("No additional metrics available for this session.", style="opacity: 0.6;"))

    return ui.TagList(*items)


def _render_sprint_analysis(sprint_res: dict) -> Tag:
    """Build the full Inverted Pyramid UI for a sprint analysis result."""
    sr = sprint_res["sprint_result"]
    warmup_dev = sprint_res.get("warmup_dev")
    garmin_name = sprint_res.get("garmin_name", "Athlete")
    mode = sprint_res.get("mode", "run")
    terrain_info = sprint_res.get("terrain_info")
    weather = sprint_res.get("weather", "")
    total_minutes = sprint_res.get("total_minutes", 0)
    hr_max_input = sprint_res.get("hr_max_input")

    # Verdict color
    verdict = sr.session_verdict
    if "Well Done" in verdict:
        v_color = COLOR_ELITE
    elif "Sub-Optimal" in verdict:
        v_color = COLOR_ADAPTING
    else:
        v_color = COLOR_NEEDS_WORK

    fi_pct = sr.fatigue_index_pct
    fi_str = f"{fi_pct:.1f}%" if np.isfinite(fi_pct) else "—"

    # Fatigue Index calculation breakdown
    first_rep = sr.sprints[0] if sr.sprints else None
    last_rep = sr.sprints[-1] if sr.sprints else None
    fi_explanation = ""
    if first_rep and last_rep and np.isfinite(first_rep.mean_output) and np.isfinite(last_rep.mean_output):
        unit = first_rep.output_unit
        fi_explanation = (
            f"( Sprint 1 avg {first_rep.mean_output:.1f} {unit}"
            f" − Sprint {last_rep.rep_number} avg {last_rep.mean_output:.1f} {unit} )"
            f" ÷ Sprint 1 avg {first_rep.mean_output:.1f} {unit}"
            f" × 100 = {fi_pct:.1f}%"
        )

    # Terrain strings
    km_str = f"{terrain_info.distance_km:.2f} km" if terrain_info and np.isfinite(terrain_info.distance_km) else "—"
    gain_str = f"{terrain_info.elev_gain_m:.0f} m" if terrain_info and np.isfinite(terrain_info.elev_gain_m) else "—"

    # Peak HR %Max
    peak_hr_str = f"{sr.peak_hr_pct_of_max:.0f}%" if np.isfinite(sr.peak_hr_pct_of_max) else "—"

    # Avg rest-end HR
    avg_rest_hr_str = f"{sr.avg_hr_at_end_of_rest:.0f} bpm" if np.isfinite(sr.avg_hr_at_end_of_rest) else "—"

    # ---- TIER 1: THE GLANCE ----
    tier1_greeting = ui.card(
        ui.div(
            ui.h3(f"Hello, {garmin_name}!", style=f"color: {COLOR_ELITE}; margin: 0;"),
            ui.p(f"MCT4 Sprint Session — {sr.num_sprints} sprints — {km_str} — Gain: {gain_str}",
                 style="margin: 4px 0 0 0; opacity: 0.8;"),
            style="background: rgba(46,93,75,0.92); border-radius: 12px; padding: 16px;",
        ),
    )

    tier1_hero = ui.card(
        ui.card_header("Sprint Fatigue Index"),
        ui.div(
            ui.div(
                ui.span(fi_str, style=f"font-size: 48px; font-weight: 850; color: {v_color}; font-family: 'Roboto Mono', monospace;"),
                style="margin-right: 16px;",
            ),
            ui.div(
                ui.span(verdict, class_="status-badge", style=f"background: {v_color}; color: #000; padding: 6px 16px; border-radius: 20px; font-weight: 700; font-size: 15px;"),
            ),
            style="display: flex; align-items: center; flex-wrap: wrap; gap: 12px;",
        ),
        ui.p(
            ui.tags.em(fi_explanation),
            style="font-size: 12px; opacity: 0.65; margin-top: 8px; font-family: 'Roboto Mono', monospace;",
        ) if fi_explanation else None,
        ui.tags.ul(
            *[ui.tags.li(r, style="font-size: 13px; opacity: 0.85;") for r in sr.session_verdict_reasons],
            style="margin-top: 10px; padding-left: 20px;",
        ) if sr.session_verdict_reasons else None,
    )

    # ---- TIER 1B: VALUE BOXES ----
    vboxes = [
        ui.value_box("Fatigue Index", fi_str,
                      showcase=fa.icon_svg("chart-line"),
                      theme="primary" if "Well Done" in verdict else ("warning" if "Sub-Optimal" in verdict else "danger")),
    ]
    if hr_max_input and np.isfinite(sr.peak_hr_pct_of_max):
        vboxes.append(
            ui.value_box("Peak HR %Max", peak_hr_str,
                          showcase=fa.icon_svg("heart-pulse"), theme="danger"),
        )
    vboxes.append(
        ui.value_box("Avg Rest End HR", avg_rest_hr_str,
                      showcase=fa.icon_svg("bed-pulse"), theme="info"),
    )
    vboxes.append(
        ui.value_box("Sprint Count", str(sr.num_sprints),
                      showcase=fa.icon_svg("bolt"), theme="info"),
    )
    n_cols = len(vboxes)
    col_w = [12 // n_cols] * n_cols
    tier1b_vboxes = ui.layout_columns(*vboxes, col_widths=col_w)

    # ---- TIER 1C: WARMUP DEVIATION ----
    warmup_card = None
    if warmup_dev and warmup_dev.go_no_go != "unknown":
        wd_color = COLOR_ELITE if warmup_dev.go_no_go == "GO" else COLOR_NEEDS_WORK
        dev_str = f"{warmup_dev.deviation_bpm:+.1f} bpm" if warmup_dev.deviation_bpm is not None and np.isfinite(warmup_dev.deviation_bpm) else "—"
        warmup_card = ui.card(
            ui.card_header("Warm-up HR Deviation (San Millan)"),
            ui.div(
                ui.span(warmup_dev.go_no_go, style=f"font-size: 20px; font-weight: 800; color: {wd_color}; margin-right: 12px;"),
                ui.span(f"Deviation: {dev_str}", style="opacity: 0.8;"),
                style="display: flex; align-items: center;",
            ),
            ui.p(warmup_dev.message, style="font-size: 13px; opacity: 0.7; margin-top: 6px;"),
        )

    # ---- TIER 2: CHARTS ----
    chart_panels = []
    try:
        fig_timeline = _sprint_mod.build_session_timeline_chart(sr)
        chart_panels.append(
            ui.accordion_panel("Session Timeline",
                               _render_plotly_card("Session Timeline", fig_timeline, full_screen=True),
                               icon=fa.icon_svg("chart-area")),
        )
    except Exception:
        pass
    try:
        fig_power = _sprint_mod.build_sprint_power_chart(sr)
        chart_panels.append(
            ui.accordion_panel("Sprint Power / Speed",
                               _render_plotly_card("Sprint Output per Rep", fig_power, full_screen=True),
                               icon=fa.icon_svg("bolt")),
        )
    except Exception:
        pass
    try:
        fig_hr = _sprint_mod.build_hr_recovery_chart(sr)
        chart_panels.append(
            ui.accordion_panel("HR Recovery Overlay",
                               _render_plotly_card("HR Recovery per Sprint", fig_hr, full_screen=True),
                               icon=fa.icon_svg("heart-pulse")),
        )
    except Exception:
        pass
    try:
        fig_fi = _sprint_mod.build_fatigue_index_chart(sr)
        chart_panels.append(
            ui.accordion_panel("Fatigue Index",
                               _render_plotly_card("Progressive Fatigue", fig_fi, full_screen=True),
                               icon=fa.icon_svg("chart-line")),
        )
    except Exception:
        pass
    if hr_max_input:
        try:
            fig_peak = _sprint_mod.build_peak_hr_chart(sr)
            chart_panels.append(
                ui.accordion_panel("Peak HR %Max",
                                   _render_plotly_card("Peak HR %Max per Rep", fig_peak, full_screen=True),
                                   icon=fa.icon_svg("heart-circle-bolt")),
            )
        except Exception:
            pass

    tier2_charts = None
    if chart_panels:
        tier2_charts = ui.accordion(*chart_panels, id="sprint_charts_accordion", open=["Session Timeline", "Sprint Power / Speed"], multiple=True)

    # ---- TIER 3: SPRINT TABLE ----
    table_rows = []
    for rep in sr.sprints:
        is_key_rep = rep.rep_number in (3, 4)
        bold = "font-weight:700;" if is_key_rep else ""
        # Color by fatigue
        if rep.fatigue_pct <= 10:
            row_bg = "rgba(0,255,255,0.06);"
        elif rep.fatigue_pct <= 15:
            row_bg = "rgba(255,133,27,0.06);"
        else:
            row_bg = "rgba(255,65,54,0.06);"

        out_str = f"{rep.mean_output:.1f}" if np.isfinite(rep.mean_output) else "—"
        peak_str = f"{rep.peak_output:.1f}" if np.isfinite(rep.peak_output) else "—"
        fat_str = f"{rep.fatigue_pct:.1f}%" if np.isfinite(rep.fatigue_pct) else "—"
        hr_end = f"{rep.hr_at_sprint_end:.0f}" if np.isfinite(rep.hr_at_sprint_end) else "—"
        hr_peak = f"{rep.hr_peak_in_recovery:.0f}" if np.isfinite(rep.hr_peak_in_recovery) else "—"
        hr_4m = f"{rep.hr_at_4min_recovery:.0f}" if np.isfinite(rep.hr_at_4min_recovery) else "—"

        # Recovery status
        if hr_max_input and np.isfinite(rep.hr_at_4min_recovery):
            pct_of_max = rep.hr_at_4min_recovery / hr_max_input * 100
            rec_status = "OK" if pct_of_max < 65 else "Slow"
        else:
            rec_status = "—"

        table_rows.append(
            f"<tr style='background:{row_bg}{bold}'>"
            f"<td style='padding:4px 8px;'>{rep.rep_number}</td>"
            f"<td style='padding:4px 8px;'>{rep.duration_sec:.0f}s</td>"
            f"<td style='padding:4px 8px;'>{out_str} {rep.output_unit}</td>"
            f"<td style='padding:4px 8px;'>{peak_str} {rep.output_unit}</td>"
            f"<td style='padding:4px 8px;'>{fat_str}</td>"
            f"<td style='padding:4px 8px;'>{hr_end}</td>"
            f"<td style='padding:4px 8px;'>{hr_peak}</td>"
            f"<td style='padding:4px 8px;'>{hr_4m}</td>"
            f"<td style='padding:4px 8px;'>{rec_status}</td>"
            f"</tr>"
        )
    table_html = (
        "<div style='overflow-x:auto;'>"
        "<table style='width:100%; border-collapse:collapse; font-size:13px;'>"
        "<thead><tr style='border-bottom:2px solid rgba(255,255,255,0.2);'>"
        "<th style='padding:6px 8px; text-align:left;'>Rep</th>"
        "<th style='padding:6px 8px; text-align:left;'>Duration</th>"
        "<th style='padding:6px 8px; text-align:left;'>Mean Output</th>"
        "<th style='padding:6px 8px; text-align:left;'>Peak Output</th>"
        "<th style='padding:6px 8px; text-align:left;'>Fatigue %</th>"
        "<th style='padding:6px 8px; text-align:left;'>HR End</th>"
        "<th style='padding:6px 8px; text-align:left;'>HR Peak Rec</th>"
        "<th style='padding:6px 8px; text-align:left;'>HR @4min</th>"
        "<th style='padding:6px 8px; text-align:left;'>Recovery</th>"
        "</tr></thead>"
        "<tbody>" + "\n".join(table_rows) + "</tbody>"
        "</table></div>"
    )
    tier3_table = ui.card(
        ui.card_header("Sprint Details"),
        ui.HTML(table_html),
    )

    # ---- TIER 4: REFERENCE TABLE ----
    ref_html = (
        "<div style='overflow-x:auto;'>"
        "<table style='width:100%; border-collapse:collapse; font-size:13px;'>"
        "<thead><tr style='border-bottom:2px solid rgba(255,255,255,0.2);'>"
        "<th style='padding:6px 8px; text-align:left;'>Criterion</th>"
        f"<th style='padding:6px 8px; text-align:left; color:{COLOR_ELITE};'>Well Done</th>"
        f"<th style='padding:6px 8px; text-align:left; color:{COLOR_NEEDS_WORK};'>Counter-Productive</th>"
        f"<th style='padding:6px 8px; text-align:left; color:{v_color};'>Your Session</th>"
        "</tr></thead>"
        "<tbody>"
        f"<tr><td style='padding:4px 8px;'>Fatigue Index</td>"
        f"<td style='padding:4px 8px;'>&lt;15%</td>"
        f"<td style='padding:4px 8px;'>&gt;20%</td>"
        f"<td style='padding:4px 8px; color:{v_color};'>{fi_str}</td></tr>"
        f"<tr><td style='padding:4px 8px;'>HR Recovery @4min</td>"
        f"<td style='padding:4px 8px;'>&lt;65% HRmax</td>"
        f"<td style='padding:4px 8px;'>&gt;75% HRmax</td>"
        f"<td style='padding:4px 8px;'>{sr.hr_recovery_status}</td></tr>"
        f"<tr><td style='padding:4px 8px;'>Peak HR (sprint 3-4)</td>"
        f"<td style='padding:4px 8px;'>90-95% HRmax</td>"
        f"<td style='padding:4px 8px;'>&gt;97% or &lt;85% HRmax</td>"
        f"<td style='padding:4px 8px;'>{peak_hr_str if hr_max_input else 'N/A (set HRmax)'}</td></tr>"
        "</tbody></table></div>"
    )
    tier4_ref = ui.card(
        ui.card_header("MCT4 Reference"),
        ui.HTML(ref_html),
    )

    # ---- RECOMMENDATION ----
    rec_card = None
    if sr.recommendation:
        rec_card = ui.card(
            ui.card_header("Recommendation"),
            ui.div(HTML(_md_to_html(sr.recommendation))),
        )

    # Assemble
    parts = [tier1_greeting, tier1_hero, tier1b_vboxes]
    if warmup_card:
        parts.append(warmup_card)
    if rec_card:
        parts.append(rec_card)
    if tier2_charts:
        parts.append(tier2_charts)
    parts.append(tier3_table)
    parts.append(tier4_ref)

    return ui.TagList(*parts)


def _short_file_warning(mode: str, total_minutes: float) -> Optional[Tag]:
    """Return a warning card if the file is too short for reliable analysis."""
    if not np.isfinite(total_minutes) or total_minutes <= 0:
        return None
    min_required = 60.0 if mode in ("run", "stairmaster", "erg") else 90.0
    if total_minutes >= min_required:
        return None
    label = {"run": "run", "stairmaster": "stairmaster", "erg": "ergometer", "bike": "bike"}.get(mode, mode)
    return ui.div(
        HTML(
            f"<strong>Heads up:</strong> this file is <strong>{total_minutes:.1f} min</strong>. "
            f"Aerobic decoupling is more reliable on steady <strong>{label}</strong> sessions "
            f"of at least <strong>{min_required:.0f} min</strong>."
        ),
        style=f"color: {COLOR_ADAPTING}; font-weight: 700; padding: 8px 12px; margin: 8px 0; border-radius: 8px; background: rgba(255,133,27,0.1);",
    )


def _md_to_html(md_text: str) -> str:
    """Lightweight markdown→HTML for recommendation text.

    Handles: **bold**, *italic*, `code`, bullet lists (- item),
    indented sub-bullets (  - item), and paragraph breaks (\\n\\n).
    No external dependency required.
    """
    if not md_text:
        return ""
    # Normalize line endings
    text = md_text.replace("\r\n", "\n")
    # Process line-by-line: group contiguous bullet lines into lists,
    # and non-bullet lines into paragraphs.
    lines = text.strip().split("\n")
    html_parts: list[str] = []
    buf_text: list[str] = []     # accumulates non-bullet lines
    buf_list: list[str] = []     # accumulates bullet lines

    def flush_text():
        if buf_text:
            joined = " ".join(l.strip() for l in buf_text if l.strip())
            if joined:
                html_parts.append(f"<p>{_md_inline(joined)}</p>")
            buf_text.clear()

    def flush_list():
        if buf_list:
            html_parts.append(_md_list_to_html(buf_list))
            buf_list.clear()

    for line in lines:
        stripped = line.strip()
        if not stripped:
            # Blank line — flush both buffers
            flush_list()
            flush_text()
            continue
        if re.match(r"^\s*-\s", line):
            # Bullet line
            flush_text()
            buf_list.append(line)
        else:
            # Non-bullet line
            flush_list()
            buf_text.append(line)

    flush_list()
    flush_text()
    return "\n".join(html_parts)


def _md_list_to_html(lines: list[str]) -> str:
    """Convert markdown bullet lines to nested <ul> HTML."""
    html = "<ul style='margin:6px 0; padding-left:20px;'>"
    for line in lines:
        if not line.strip():
            continue
        m = re.match(r"^(\s*)-\s(.*)", line)
        if not m:
            continue
        indent = len(m.group(1))
        content = _md_inline(m.group(2).strip())
        if indent >= 2:
            html += f"<ul style='margin:2px 0; padding-left:16px;'><li>{content}</li></ul>"
        else:
            html += f"<li>{content}</li>"
    html += "</ul>"
    return html


def _md_inline(text: str) -> str:
    """Apply inline markdown formatting: **bold**, *italic*, `code`."""
    # Bold: **text**
    text = re.sub(r"\*\*(.+?)\*\*", r"<strong>\1</strong>", text)
    # Italic: *text* (but not inside already-processed <strong> tags)
    text = re.sub(r"(?<!\*)\*(?!\*)(.+?)(?<!\*)\*(?!\*)", r"<em>\1</em>", text)
    # Code: `text`
    text = re.sub(r"`(.+?)`", r"<code>\1</code>", text)
    return text


def _render_plotly_card(title: str, fig, full_screen: bool = False, static: bool = False, tooltip: str = "") -> Tag:
    """Render a Plotly figure inside a Shiny card using HTML export.

    full_screen=True adds expand-to-fullscreen button (Section 10.2).
    static=True disables Plotly interactivity (faster rendering for read-only charts).
    tooltip='' optional explanatory tooltip shown as ℹ icon next to title.
    """
    try:
        _cfg = {"responsive": True, "staticPlot": True, "displayModeBar": False} if static else {"responsive": True}
        html_str = fig.to_html(full_html=False, include_plotlyjs=False, config=_cfg)
        if tooltip:
            header_content = ui.div(
                ui.tags.span(title, style="margin-right:6px;"),
                ui.tooltip(
                    ui.tags.span("ℹ", style="cursor:help; opacity:0.6; font-size:13px; border:1px solid rgba(255,255,255,0.3); border-radius:50%; padding:0 5px; vertical-align:middle;"),
                    tooltip,
                ),
                style="display:flex; align-items:center;",
            )
        else:
            header_content = title
        return ui.card(
            ui.card_header(header_content),
            ui.HTML(html_str),
            full_screen=full_screen,
        )
    except Exception as e:
        return ui.card(
            ui.card_header(title),
            ui.p(f"Chart rendering error: {e}"),
        )


