    def _cors_json(data: dict, status_code: int = 200) -> _JSONResponse:
        """Return JSONResponse with permissive CORS headers for mobile/ngrok."""
        resp = _JSONResponse(data, status_code=status_code)
        resp.headers["Access-Control-Allow-Origin"] = "*"
        resp.headers["Access-Control-Allow-Methods"] = "GET, POST, OPTIONS"
        resp.headers["Access-Control-Allow-Headers"] = "Content-Type, ngrok-skip-browser-warning"
        return resp

    async def _api_ping(_request: _Request) -> _JSONResponse:
