        })

    def _row_to_json_clean(row: dict) -> dict:
        """Convert an analysis row dict to JSON-safe dict."""
        import numpy as _np
        clean = {}
        for k, v in row.items():
            try:
                if isinstance(v, (_np.integer,)):
                    v = int(v)
                elif isinstance(v, (_np.floating,)):
                    v = float(v)
                elif isinstance(v, _np.bool_):
                    v = bool(v)
                if isinstance(v, float) and (_math.isnan(v) or _math.isinf(v)):
                    clean[k] = None
                else:
                    clean[k] = v
            except (TypeError, ValueError):
                clean[k] = None
        return clean

    def _save_session_to_history(row: dict, athlete_slug: str, fbytes: bytes):
        """Save an analysis row to history CSV and store FIT file."""
        from history import load_history, _history_upsert_row, save_history
        csv_path = APP_DIR / f"ad_history_{athlete_slug}.csv"
        hist = load_history(csv_path) if csv_path.exists() else pd.DataFrame()
        hist, _action = _history_upsert_row(hist, row)
        save_history(hist, csv_path)

        # Store FIT bytes for session replay
        start_iso = row.get("start_time_iso", "")
        if start_iso and fbytes:
            fpath = _fit_store_path_api(athlete_slug, start_iso)
            fpath.parent.mkdir(parents=True, exist_ok=True)
            fpath.write_bytes(fbytes)

    def _extract_fit_from_zip(zbytes: bytes) -> list:
        """Extract .fit files from a ZIP archive. Returns list of (filename, bytes) tuples."""
        import zipfile, io
        results = []
        try:
            with zipfile.ZipFile(io.BytesIO(zbytes)) as zf:
                for name in zf.namelist():
                    if name.lower().endswith('.fit') and not name.startswith('__MACOSX'):
                        results.append((name, zf.read(name)))
        except zipfile.BadZipFile:
            pass
        return results

    async def _api_analyze(_request: _Request) -> _JSONResponse:
        # Handle CORS preflight
        if _request.method == "OPTIONS":
            return _cors_json({})
        try:
            body = await _request.json()
            fit_b64 = body.get("fit_base64", "")
            fname = body.get("file_name", "upload.fit")
            athlete = body.get("athlete_name", "Mobile User")
            max_hr = float(body.get("max_hr", 0) or 0)
            if not fit_b64:
                return _cors_json({"error": "fit_base64 required"}, 400)

            import auto_fetch as _af
            raw_bytes = base64.b64decode(fit_b64)

            # --- ZIP handling: extract .fit files from ZIP archives ---
            is_zip = fname.lower().endswith('.zip') or (len(raw_bytes) > 4 and raw_bytes[:4] == b'PK\x03\x04')
            if is_zip:
                fit_files = await _asio.to_thread(_extract_fit_from_zip, raw_bytes)
                if not fit_files:
                    return _cors_json({"error": "No .fit files found inside the ZIP archive."}, 422)

                # Process all FIT files from the ZIP
                all_results = []
                athlete_slug = athlete.strip().lower().replace(" ", "_")
                athlete_slug = "".join(c for c in athlete_slug if c.isalnum() or c in "_-") or "default"

                for fit_name, fbytes in fit_files:
                    row = await _asio.to_thread(_af.analyze_fit_bytes, fbytes, fit_name, athlete)
                    if row is None:
                        continue
                    try:
                        await _asio.to_thread(_save_session_to_history, row, athlete_slug, fbytes)
                    except Exception:
                        import traceback as _tb; _tb.print_exc()
                    detail = None
                    try:
                        detail = await _asio.to_thread(_af.extract_timeseries_and_zones, fbytes, fit_name, max_hr_override=max_hr)
                    except Exception:
                        import traceback as _tb; _tb.print_exc()
                    clean = _row_to_json_clean(row)
                    entry = {"result": clean}
                    if detail:
                        entry["timeseries"] = detail.get("timeseries")
                        entry["zones"] = detail.get("zones")
                    all_results.append(entry)

                if not all_results:
                    return _cors_json({"error": "No sessions could be analyzed from the ZIP."}, 422)

                # Return first result as primary (backward compat) + all results in batch array
                resp = {"ok": True, "result": all_results[0]["result"]}
                if all_results[0].get("timeseries"):
                    resp["timeseries"] = all_results[0]["timeseries"]
                if all_results[0].get("zones"):
                    resp["zones"] = all_results[0]["zones"]
                if len(all_results) > 1:
                    resp["batch"] = all_results
                return _cors_json(resp)

            # --- Single FIT file ---
            fbytes = raw_bytes
            row = await _asio.to_thread(_af.analyze_fit_bytes, fbytes, fname, athlete)
            if row is None:
                return _cors_json(
                    {"error": "Analysis failed — file may be too short or unsupported."},
                    422,
                )

            # Save to history CSV and store FIT file
            athlete_slug = athlete.strip().lower().replace(" ", "_")
            athlete_slug = "".join(c for c in athlete_slug if c.isalnum() or c in "_-") or "default"
            try:
                await _asio.to_thread(_save_session_to_history, row, athlete_slug, fbytes)
            except Exception:
                import traceback as _tb; _tb.print_exc()

            # Extract 30s-smoothed time series + HR zone data
            detail = None
            try:
                detail = await _asio.to_thread(_af.extract_timeseries_and_zones, fbytes, fname, max_hr_override=max_hr)
            except Exception:
                import traceback as _tb; _tb.print_exc()

            clean = _row_to_json_clean(row)
            resp = {"ok": True, "result": clean}
            if detail:
                resp["timeseries"] = detail.get("timeseries")
                resp["zones"] = detail.get("zones")
            return _cors_json(resp)
        except Exception as e:
            import traceback as _tb
            _tb.print_exc()
            return _cors_json({"error": str(e)}, 500)

    async def _api_session_update(_request: _Request) -> _JSONResponse:
        """Update a session's editable fields."""
        if _request.method == "OPTIONS":
            return _cors_json({})
        try:
            body = await _request.json()
            athlete_slug = body.get("athlete_slug", "")
            start_time_iso = body.get("start_time_iso", "")
            if not athlete_slug or not start_time_iso:
                return _cors_json({"error": "athlete_slug and start_time_iso required"}, 400)

            from history import load_history, save_history

            csv_path = APP_DIR / f"ad_history_{athlete_slug}.csv"
            if not csv_path.exists():
                return _cors_json({"error": "No history found"}, 404)

            hist = load_history(csv_path)
            mask = hist["start_time_iso"].astype(str) == str(start_time_iso)
            if not mask.any():
                return _cors_json({"error": "Session not found"}, 404)

            # All editable fields (matching desktop edit modal)
            _EDITABLE_FIELDS = [
                "warmup_min", "distance_km", "avg_power_w", "avg_hr",
                "rpe_h1", "rpe_h2", "whoop_score",
                "fluid_intake_ml", "carb_intake_g",
                "recovery_hr", "garmin_hrv_ms", "garmin_resting_hr",
            ]
            updates = {}
            for field in _EDITABLE_FIELDS:
                val = body.get(field)
                if val is not None and val != "":
                    try:
                        updates[field] = float(val)
                    except (TypeError, ValueError):
                        pass

            # String fields
            for str_field in ["mode"]:
                val = body.get(str_field)
                if val is not None and val != "":
                    updates[str_field] = str(val)

            if updates:
                for col, val in updates.items():
                    if col not in hist.columns:
                        hist[col] = float("nan")
                    hist.loc[mask, col] = val
                await _asio.to_thread(save_history, hist, csv_path)

            return _cors_json({"ok": True, "updated_fields": list(updates.keys())})
        except Exception as e:
            import traceback as _tb; _tb.print_exc()
            return _cors_json({"error": str(e)}, 500)

    async def _api_session_delete(_request: _Request) -> _JSONResponse:
        """Delete one or more sessions from history CSV and stored FIT files."""
        if _request.method == "OPTIONS":
            return _cors_json({})
        try:
            body = await _request.json()
            athlete_slug = body.get("athlete_slug", "")
            isos = body.get("isos", [])
            if not athlete_slug or not isos:
                return _cors_json({"error": "athlete_slug and isos list required"}, 400)

            from history import load_history, save_history
            from utils import PROFILE_META_START_TIME_ISO

            csv_path = APP_DIR / f"ad_history_{athlete_slug}.csv"
            if not csv_path.exists():
                return _cors_json({"error": "No history found"}, 404)

            hist = load_history(csv_path)
            if hist.empty or "start_time_iso" not in hist.columns:
                return _cors_json({"error": "Empty history"}, 404)

            before = len(hist)
            iso_strs = [str(i) for i in isos]
            st_col = hist["start_time_iso"].astype(str)
            # Keep rows that are NOT in the delete list, or are the profile meta row
            keep_mask = ~st_col.isin(iso_strs) | (st_col == PROFILE_META_START_TIME_ISO)
            hist = hist[keep_mask]
            after = len(hist)
            deleted = before - after

            if deleted > 0:
                await _asio.to_thread(save_history, hist, csv_path)
                # Also delete stored FIT files
                for iso in isos:
                    try:
                        fpath = _fit_store_path_api(athlete_slug, str(iso))
                        if fpath.exists():
                            fpath.unlink()
                    except Exception:
                        pass

            return _cors_json({"ok": True, "deleted": deleted})
        except Exception as e:
            import traceback as _tb; _tb.print_exc()
            return _cors_json({"error": str(e)}, 500)

    async def _api_garmin_restore(_request: _Request) -> _JSONResponse:
        """Stub so mobile doesn't error on startup garmin/restore call."""
