    def _fit_store_path_api(athlete_slug: str, start_time_iso: str) -> Path:
        safe_iso = start_time_iso.replace(":", "-").replace("+", "p")
        return APP_DIR / "fit_store" / athlete_slug / f"{safe_iso}.fit"

    def _json_safe(v):
        """Convert a single value to JSON-safe Python type."""
        import numpy as _np2
        try:
            if v is None:
                return None
            if isinstance(v, _np2.integer):
                return int(v)
            if isinstance(v, _np2.floating):
                v = float(v)
            if isinstance(v, _np2.bool_):
                return bool(v)
            if isinstance(v, float) and (_math.isnan(v) or _math.isinf(v)):
                return None
            if isinstance(v, (pd.Timestamp,)):
                return str(v.isoformat()) if hasattr(v, "isoformat") else str(v)
            return v
        except (TypeError, ValueError):
            return None

    async def _api_fit_history(_request: _Request) -> _JSONResponse:
        """Return full granular session data for an athlete from history CSV."""
        if _request.method == "OPTIONS":
            return _cors_json({})
        try:
            body = await _request.json()
            athlete_slug = body.get("athlete_slug", "")
            if not athlete_slug:
                return _cors_json({"error": "athlete_slug required"}, 400)

            from history import load_history
            from utils import PROFILE_META_START_TIME_ISO
            csv_path = APP_DIR / f"ad_history_{athlete_slug}.csv"
            if not csv_path.exists():
                return _cors_json({"sessions": []})

            hist = load_history(csv_path)
            if hist.empty:
                return _cors_json({"sessions": []})

            # Exclude profile metadata row
            hist = hist[hist["start_time_iso"].astype(str) != PROFILE_META_START_TIME_ISO]

            # Columns to expose to mobile Granular Session Data
            _GRANULAR_COLS = [
                "start_time_iso", "date", "athlete_id", "mode", "terrain",
                "status", "decoupling_pct", "ef", "drift_driver",
                "warmup_min", "avg_output", "avg_hr", "avg_power_w",
                "avg_speed_kph", "total_minutes", "minutes_analyzed",
                "distance_km", "elev_gain_m", "recovery_hr",
                "recovery_hr_2min_bpm", "last_hr_bpm",
                "temp_min_c", "temp_max_c", "weather_summary",
                "fluid_intake_ml", "carb_intake_g",
                "whoop_score", "garmin_hrv_ms", "garmin_resting_hr",
                "rpe_h1", "rpe_h2", "file_name", "output_used",
                "output_unit", "low_thr", "high_thr",
                "tss", "normalized_power_w", "intensity_factor",
                "time_to_drift_sec", "hr_h1", "hr_h2",
                "out_h1", "out_h2",
            ]

            sessions = []
            for _, r in hist.iterrows():
                iso = str(r.get("start_time_iso", ""))
                if not iso:
                    continue
                fpath = _fit_store_path_api(athlete_slug, iso)
                row = {"has_fit": fpath.exists()}
                for col in _GRANULAR_COLS:
                    val = r.get(col, None)
                    row[col] = _json_safe(val)
                sessions.append(row)

            # Sort by date descending
            sessions.sort(key=lambda s: s.get("start_time_iso", ""), reverse=True)
            return _cors_json({"sessions": sessions})
        except Exception as e:
            return _cors_json({"error": str(e)}, 500)

    async def _api_fit_retrieve(_request: _Request) -> _JSONResponse:
        """Retrieve a stored FIT file as base64."""
        if _request.method == "OPTIONS":
            return _cors_json({})
        try:
            body = await _request.json()
            athlete_slug = body.get("athlete_slug", "")
            start_time_iso = body.get("start_time_iso", "")
            if not athlete_slug or not start_time_iso:
                return _cors_json({"error": "athlete_slug and start_time_iso required"}, 400)

            fpath = _fit_store_path_api(athlete_slug, start_time_iso)
            if not fpath.exists():
                # Also check _temp
                temp_path = _fit_store_path_api("_temp", start_time_iso)
                if temp_path.exists():
                    fpath = temp_path
                else:
                    return _cors_json({"ok": False, "error": "FIT file not found"})

            fbytes = await _asio.to_thread(fpath.read_bytes)
            return _cors_json({
                "ok": True,
                "fit_base64": base64.b64encode(fbytes).decode("ascii"),
                "size_bytes": len(fbytes),
            })
        except Exception as e:
            return _cors_json({"error": str(e)}, 500)

    def _generate_session_praise(session_data: dict) -> str:
        """Build a 'What you did well' section based on session metrics.

        Evaluates recovery HR gap, decoupling %, efficiency factor, duration,
        pacing consistency, and other markers to give the athlete positive
        reinforcement about what they nailed in this session.
        """
        try:
            praise: list[str] = []

            # --- Recovery Heart Rate (2-min gap) ---
            # Scale: >=30 excellent, 20-29 good, 12-19 average, <12 poor
            rec_hr = float(session_data.get("recovery_hr", float("nan")))
            if np.isfinite(rec_hr) and rec_hr > 0:
                if rec_hr >= 30:
                    praise.append(
                        f"**Outstanding recovery heart rate** — your HR dropped **{rec_hr:.0f} bpm** "
                        f"in 2 minutes. This signals excellent cardiac fitness and parasympathetic reactivation. "
                        f"Your heart recovers like a well-trained endurance athlete."
                    )
                elif rec_hr >= 20:
                    praise.append(
                        f"**Strong recovery heart rate** — a **{rec_hr:.0f} bpm** drop in 2 minutes "
                        f"shows solid autonomic fitness. Your body shifts efficiently from effort to rest."
                    )
                elif rec_hr >= 12:
                    praise.append(
                        f"**Adequate recovery heart rate** — your HR fell **{rec_hr:.0f} bpm** in 2 minutes, "
                        f"within the normal range. Consistent aerobic training will push this higher over time."
                    )

            # --- Aerobic Decoupling ---
            dec = float(session_data.get("decoupling_pct", float("nan")))
            low_thr = float(session_data.get("low_thr", 5.0))
            if np.isfinite(dec):
                if dec < low_thr and dec >= 0:
                    praise.append(
                        f"**Exceptional aerobic coupling** — only **{dec:.1f}%** decoupling. "
                        f"Your output and heart rate stayed locked together, a hallmark of aerobic durability."
                    )
                elif dec <= (low_thr + 2) and dec >= 0:
                    praise.append(
                        f"**Good pacing discipline** — **{dec:.1f}%** decoupling is within the adaptation zone. "
                        f"You held a steady effort without overcooking it."
                    )

            # --- Efficiency Factor (EF) ---
            ef = float(session_data.get("ef", float("nan")))
            if np.isfinite(ef) and ef > 0:
                mode = str(session_data.get("mode", "run")).lower()
                if mode == "run" and ef >= 1.5:
                    praise.append(
                        f"**High efficiency factor** ({ef:.2f}) — you're producing strong output per heartbeat. "
                        f"This indicates solid aerobic development."
                    )
                elif mode == "bike" and ef >= 1.6:
                    praise.append(
                        f"**High efficiency factor** ({ef:.2f}) — excellent power output relative to heart rate. "
                        f"Your aerobic engine is working efficiently."
                    )

            # --- Duration commitment ---
            total_min = float(session_data.get("total_minutes", float("nan")))
            if np.isfinite(total_min):
                if total_min >= 90:
                    praise.append(
                        f"**Long session commitment** — logging **{total_min:.0f} minutes** builds deep "
                        f"aerobic adaptations (mitochondrial density, fat oxidation, mental resilience)."
                    )
                elif total_min >= 60:
                    praise.append(
                        f"**Solid duration** — **{total_min:.0f} minutes** is a quality aerobic stimulus "
                        f"for building endurance."
                    )

            # --- Pacing consistency (HR halves close) ---
            hr_h1 = float(session_data.get("hr_h1", float("nan")))
            hr_h2 = float(session_data.get("hr_h2", float("nan")))
            if np.isfinite(hr_h1) and np.isfinite(hr_h2) and hr_h1 > 0:
                hr_diff_pct = abs(hr_h2 - hr_h1) / hr_h1 * 100
                if hr_diff_pct < 3:
                    praise.append(
                        f"**Rock-steady heart rate** — only **{abs(hr_h2 - hr_h1):.0f} bpm** difference "
                        f"between halves ({hr_h1:.0f} → {hr_h2:.0f}). "
                        f"This even-split effort maximizes aerobic adaptation."
                    )

            # --- Output consistency (pace/power halves close) ---
            out_h1 = float(session_data.get("out_h1", float("nan")))
            out_h2 = float(session_data.get("out_h2", float("nan")))
            if np.isfinite(out_h1) and np.isfinite(out_h2) and out_h1 > 0:
                out_diff_pct = abs(out_h2 - out_h1) / out_h1 * 100
                if out_diff_pct < 3:
                    output_used = str(session_data.get("output_used", "output"))
                    praise.append(
                        f"**Consistent {output_used.lower()}** — your output barely shifted between halves, "
                        f"showing disciplined pacing."
                    )

            # --- Warm-up done properly ---
            warmup_min = float(session_data.get("warmup_min", float("nan")))
            if np.isfinite(warmup_min) and warmup_min >= 10:
                praise.append(
                    f"**Proper warm-up** ({warmup_min:.0f} min) — allowing your body to "
                    f"transition gradually protects joints and gives a cleaner aerobic reading."
                )

            # --- Fueling / hydration logged ---
            fluid = float(session_data.get("fluid_intake_ml", float("nan")))
            carbs = float(session_data.get("carb_intake_g", float("nan")))
            if np.isfinite(fluid) and fluid > 0 and np.isfinite(carbs) and carbs > 0:
                praise.append(
                    f"**Nutrition tracked** — logging **{fluid:.0f} ml** fluid and **{carbs:.0f} g** carbs "
                    f"shows the attention to detail that separates good athletes from great ones."
                )
            elif np.isfinite(fluid) and fluid > 0:
                praise.append(
                    f"**Hydration tracked** — you logged **{fluid:.0f} ml** of fluid intake. "
                    f"Staying on top of hydration is critical for cardiac efficiency."
                )

            if not praise:
                return ""

            # Build markdown section
            header = "**What you did well this session:**"
            bullets = "\n".join([f"- {p}" for p in praise])
            return f"{header}\n{bullets}"

        except Exception:
            import traceback; traceback.print_exc()
            return ""

    def _generate_coach_recommendation(session_data: dict) -> str:
        """Generate a coaching recommendation from session data using analysis.py logic."""
        try:
            from analysis import recommendation_text
            dec = float(session_data.get("decoupling_pct", float("nan")))
            if not np.isfinite(dec):
                return ""
            mode = str(session_data.get("mode", "run"))
            low_thr = float(session_data.get("low_thr", 2.0))
            high_thr = float(session_data.get("high_thr", 5.0))
            total_min = float(session_data.get("total_minutes", 60))
            avg_out = float(session_data.get("avg_output", 0))
            avg_hr = float(session_data.get("avg_hr", 0))
            avg_speed = float(session_data.get("avg_speed_kph", float("nan")))
            output_unit = str(session_data.get("output_unit", ""))
            output_used = str(session_data.get("output_used", ""))
            warmup_min = int(float(session_data.get("warmup_min", 15)))
            terrain = str(session_data.get("terrain", ""))
            status = str(session_data.get("status", ""))

            raw = recommendation_text(
                mode=mode, dec=dec, low_thr=low_thr, high_thr=high_thr,
                event_goal_min=60.0, total_min=total_min,
                avg_out=avg_out, avg_hr=avg_hr, avg_speed_kph=avg_speed,
                output_unit=output_unit, output_used=output_used,
                warmup_min=warmup_min, end_exclude_min=0,
                terrain=terrain, status=status,
            )
            return raw
        except Exception:
            import traceback; traceback.print_exc()
            return ""

    async def _api_fit_detail(_request: _Request) -> _JSONResponse:
        """Return 30s-smoothed time series + HR zones + coach rec for a stored FIT file."""
        if _request.method == "OPTIONS":
            return _cors_json({})
        try:
            body = await _request.json()
            athlete_slug = body.get("athlete_slug", "")
            start_time_iso = body.get("start_time_iso", "")
            max_hr = float(body.get("max_hr", 0) or 0)
            if not athlete_slug or not start_time_iso:
                return _cors_json({"error": "athlete_slug and start_time_iso required"}, 400)

            fpath = _fit_store_path_api(athlete_slug, start_time_iso)
            if not fpath.exists():
                temp_path = _fit_store_path_api("_temp", start_time_iso)
                if temp_path.exists():
                    fpath = temp_path
                else:
                    return _cors_json({"ok": False, "error": "FIT file not found"})

            import auto_fetch as _af
            fbytes = await _asio.to_thread(fpath.read_bytes)
            detail = await _asio.to_thread(
                _af.extract_timeseries_and_zones, fbytes, f"session_{start_time_iso}",
                max_hr_override=max_hr,
            )
            if detail is None:
                return _cors_json({"ok": False, "error": "Could not extract detail data"})

            # Generate coaching guidance from history data (praise + recommendation)
            coach_guidance = ""
            try:
                from history import load_history
                csv_path = APP_DIR / f"ad_history_{athlete_slug}.csv"
                if csv_path.exists():
                    hist = load_history(csv_path)
                    match = hist[hist["start_time_iso"].astype(str) == start_time_iso]
                    if not match.empty:
                        row_data = match.iloc[0].to_dict()
                        praise = await _asio.to_thread(_generate_session_praise, row_data)
                        coach_rec = await _asio.to_thread(_generate_coach_recommendation, row_data)
                        parts = [p for p in (praise, coach_rec) if p]
                        coach_guidance = "\n\n".join(parts)
            except Exception:
                import traceback as _tb; _tb.print_exc()

            return _cors_json({
                "ok": True,
                "timeseries": detail.get("timeseries"),
                "zones": detail.get("zones"),
                "coach_recommendation": coach_guidance,
            })
        except Exception as e:
            import traceback as _tb; _tb.print_exc()
            return _cors_json({"error": str(e)}, 500)

    async def _api_health_today(_request: _Request) -> _JSONResponse:
        """Return today's health metrics (Whoop recovery, Garmin HRV/RHR) from history CSV.

        Also returns 7-day rolling averages and baseline data for fatigue indicators.
        The mobile "Today's Workout" Home page uses this to show readiness.
        """
        if _request.method == "OPTIONS":
            return _cors_json({})
        try:
            body = await _request.json()
            athlete_slug = body.get("athlete_slug", "")
            if not athlete_slug:
                return _cors_json({"error": "athlete_slug required"}, 400)

            from history import load_history
            from utils import PROFILE_META_START_TIME_ISO
            import datetime as _dt

            csv_path = APP_DIR / f"ad_history_{athlete_slug}.csv"
            if not csv_path.exists():
                return _cors_json({"ok": True, "has_data": False})

            hist = load_history(csv_path)
            if hist.empty:
                return _cors_json({"ok": True, "has_data": False})

            # Exclude profile metadata row
            hist = hist[hist["start_time_iso"].astype(str) != PROFILE_META_START_TIME_ISO]
            if hist.empty:
                return _cors_json({"ok": True, "has_data": False})

            # Parse dates and sort descending
            hist["_date"] = pd.to_datetime(hist["start_time_iso"], errors="coerce", utc=True)
            hist = hist.dropna(subset=["_date"]).sort_values("_date", ascending=False)

            # Today in UTC+8 (PHT)
            pht_tz = _dt.timezone(_dt.timedelta(hours=8))
            today_pht = _dt.datetime.now(pht_tz).date()

            # Build health response
            result = {
                "ok": True,
                "has_data": True,
                "today": today_pht.isoformat(),
                # Today's values (from the most recent session today or the latest available)
                "whoop_recovery": None,
                "whoop_hrv_ms": None,
                "whoop_resting_hr": None,
                "garmin_hrv_ms": None,
                "garmin_resting_hr": None,
                # 7-day rolling averages
                "avg_7d_garmin_hrv": None,
                "avg_7d_garmin_rhr": None,
                "avg_7d_whoop_recovery": None,
                "avg_7d_whoop_hrv": None,
                # 30-day baseline averages (for fatigue indicators)
                "baseline_garmin_hrv": None,
                "baseline_garmin_rhr": None,
                "baseline_whoop_recovery": None,
                # Latest date with valid data
                "latest_data_date": None,
                # HRV trend (7 day series for mini chart)
                "hrv_trend_dates": [],
                "hrv_trend_values": [],
                "rhr_trend_dates": [],
                "rhr_trend_values": [],
            }

            # Helper: get numeric or None
            def _nv(val):
                if val is None or (isinstance(val, float) and (val != val)):
                    return None
                try:
                    v = float(val)
                    return v if v == v else None  # NaN check
                except (TypeError, ValueError):
                    return None

            # Find latest Whoop data
            for _, r in hist.iterrows():
                ws = _nv(r.get("whoop_score"))
                if ws is not None:
                    result["whoop_recovery"] = round(ws)
                    wh = _nv(r.get("whoop_hrv_ms"))
                    if wh is not None:
                        result["whoop_hrv_ms"] = round(wh)
                    wr = _nv(r.get("whoop_resting_hr"))
                    if wr is not None:
                        result["whoop_resting_hr"] = round(wr)
                    result["latest_data_date"] = str(r.get("_date", ""))[:10]
                    break

            # Find latest Garmin data
            for _, r in hist.iterrows():
                gh = _nv(r.get("garmin_hrv_ms"))
                gr = _nv(r.get("garmin_resting_hr"))
                if gh is not None or gr is not None:
                    if gh is not None:
                        result["garmin_hrv_ms"] = round(gh)
                    if gr is not None:
                        result["garmin_resting_hr"] = round(gr)
                    if not result["latest_data_date"]:
                        result["latest_data_date"] = str(r.get("_date", ""))[:10]
                    break

            # Compute 7-day and 30-day averages from history
            cutoff_7d = today_pht - _dt.timedelta(days=7)
            cutoff_30d = today_pht - _dt.timedelta(days=30)

            garmin_hrvs_7d, garmin_rhrs_7d = [], []
            whoop_recs_7d, whoop_hrvs_7d = [], []
            garmin_hrvs_30d, garmin_rhrs_30d, whoop_recs_30d = [], [], []

            # For trend mini-chart (last 14 days)
            cutoff_14d = today_pht - _dt.timedelta(days=14)
            hrv_trend, rhr_trend = {}, {}  # date_str -> value

            for _, r in hist.iterrows():
                rd = r["_date"]
                try:
                    row_date = rd.date() if hasattr(rd, 'date') else rd.to_pydatetime().date()
                except Exception:
                    continue

                gh = _nv(r.get("garmin_hrv_ms"))
                gr = _nv(r.get("garmin_resting_hr"))
                ws = _nv(r.get("whoop_score"))
                wh = _nv(r.get("whoop_hrv_ms"))

                # 30-day window
                if row_date >= cutoff_30d:
                    if gh is not None:
                        garmin_hrvs_30d.append(gh)
                    if gr is not None:
                        garmin_rhrs_30d.append(gr)
                    if ws is not None:
                        whoop_recs_30d.append(ws)

                # 7-day window
                if row_date >= cutoff_7d:
                    if gh is not None:
                        garmin_hrvs_7d.append(gh)
                    if gr is not None:
                        garmin_rhrs_7d.append(gr)
                    if ws is not None:
                        whoop_recs_7d.append(ws)
                    if wh is not None:
                        whoop_hrvs_7d.append(wh)

                # 14-day trend (prefer Garmin HRV, fallback to Whoop HRV)
                if row_date >= cutoff_14d:
                    ds = row_date.isoformat()
                    hrv_val = gh if gh is not None else wh
                    if hrv_val is not None and ds not in hrv_trend:
                        hrv_trend[ds] = round(hrv_val)
                    rhr_val = gr
                    if rhr_val is not None and ds not in rhr_trend:
                        rhr_trend[ds] = round(rhr_val)

            # Set averages
            if garmin_hrvs_7d:
                result["avg_7d_garmin_hrv"] = round(sum(garmin_hrvs_7d) / len(garmin_hrvs_7d))
            if garmin_rhrs_7d:
                result["avg_7d_garmin_rhr"] = round(sum(garmin_rhrs_7d) / len(garmin_rhrs_7d))
            if whoop_recs_7d:
                result["avg_7d_whoop_recovery"] = round(sum(whoop_recs_7d) / len(whoop_recs_7d))
            if whoop_hrvs_7d:
                result["avg_7d_whoop_hrv"] = round(sum(whoop_hrvs_7d) / len(whoop_hrvs_7d))
            if garmin_hrvs_30d:
                result["baseline_garmin_hrv"] = round(sum(garmin_hrvs_30d) / len(garmin_hrvs_30d))
            if garmin_rhrs_30d:
                result["baseline_garmin_rhr"] = round(sum(garmin_rhrs_30d) / len(garmin_rhrs_30d))
            if whoop_recs_30d:
                result["baseline_whoop_recovery"] = round(sum(whoop_recs_30d) / len(whoop_recs_30d))

            # Trend arrays (sorted ascending)
            sorted_hrv = sorted(hrv_trend.items())
            result["hrv_trend_dates"] = [d for d, _ in sorted_hrv]
            result["hrv_trend_values"] = [v for _, v in sorted_hrv]
            sorted_rhr = sorted(rhr_trend.items())
            result["rhr_trend_dates"] = [d for d, _ in sorted_rhr]
            result["rhr_trend_values"] = [v for _, v in sorted_rhr]

            return _cors_json(result)
        except Exception as e:
            import traceback as _tb; _tb.print_exc()
            return _cors_json({"error": str(e)}, 500)

